window.DK_TERIM_DIZIN=window.DK_TERIM_DIZIN||{};DK_TERIM_DIZIN["mto316"]={"v":"d1b3e90c1c","terim":[{"id":"unit-acre","tr":"Akre","en":"Acre","kisa":"acre","tur":"birim","es":["alan birimi","acre — akre","İngiliz alan birimi"],"tanim":["İngiliz ve ABD geleneksel ölçü sisteminde kullanılan alan ölçü birimidir.","1 akre yaklaşık 0,4047 ha (4046,86 m²) alana eşittir; 640 akre 1 milkare alan oluşturur.","Küçük drenaj alanlarının hidrolojik boyutlandırılmasında ve rasyonel yöntem hesaplarında kullanılır."],"tanim_en":"A unit of land area in the English and United States customary systems equal to 4046.86 square metres or 43560 square feet.","bag":{"kavram":["akis-birim","rasyonel"],"soru":["S4","S33","S34"],"hesap":["rasyonel-ing"]}},{"id":"unit-acre-ft","tr":"Akre-ayak","en":"Acre-foot","kisa":"acre-ft","tur":"birim","es":["ac-ft","acre-feet","acre-ft — akre-fit","akre-fit","İngiliz hacim birimi"],"tanim":["1 akre büyüklüğündeki alanı 1 fit derinliğinde örten su hacmine eşit hacim birimidir.","1 akre-ayak yaklaşık 1233,5 m³ su hacmine karşılık gelir; 1 milkare alana düşen 1 inç akış 53,33 akre-ayak hacim üretir.","HEC-HMS model çıktılarında doğrudan akış hacmini ve haznelerde depolanan su miktarını ifade etmek için kullanılır."],"tanim_en":"A unit of volume equal to the volume of water that will cover an area of one acre to a depth of one foot, approximately 1233.5 cubic metres.","bag":{"kavram":["akis-birim","hec-hms","ic-kayip"],"soru":["S4","S34"],"hesap":[]}},{"id":"unit-cfs","tr":"Fit küp bölü saniye","en":"Cubic feet per second","kisa":"cfs","tur":"birim","es":["ft3/s","ft³/s","cubic foot per second","cfs — saniyede fit küp","cfs debi birimi","saniyede fit küp"],"tanim":["İngiliz ve ABD geleneksel ölçü sisteminde birim zamanda geçen akışkan hacmini belirten debi birimidir.","1 cfs yaklaşık 0,02832 m³/s akıma karşılık gelir; 1 in/h şiddetindeki yağışın 1 akre alandan akması yaklaşık 1 cfs debi üretir.","HEC-HMS hidrolik model çıktılarında ve rasyonel yöntem debi hesaplarında temel akım birimi olarak kullanılır."],"tanim_en":"A unit of volumetric flow rate equal to one cubic foot of water passing a given point in one second, approximately 0.02832 cubic metres per second.","bag":{"kavram":["akis-birim","hec-hms","rasyonel"],"soru":["S4","S33","S37","S38"],"hesap":["cfs-m3s","rasyonel-ing"]}},{"id":"unit-ha","tr":"Hektar","en":"Hectare","kisa":"ha","tur":"birim","es":["10^4 m2","ha","10000 m2","alan birimi","10⁴ m²"],"tanim":["Metrik sistemde 10 000 m² büyüklüğündeki alanı temsil eden arazi alan ölçü birimidir.","1 ha değeri 0,01 km² veya yaklaşık 2,471 akre büyüklüğe karşılık gelir.","Küçük havzaların drenaj alanı sınıflandırmasında ve rasyonel yöntemin uygulanabilirliğinin belirlenmesinde kullanılır."],"tanim_en":"A metric unit of land area equal to 10000 square metres or 0.01 square kilometres.","bag":{"kavram":["akis-birim","rasyonel","hazne"],"soru":["S1","S2","S4","S6","S7","S8"],"hesap":["rasyonel","rasyonel-ing"]}},{"id":"unit-in","tr":"İnç","en":"Inch","kisa":"in","tur":"birim","es":["parmak","inç derinliği","inch","inches","in derinlik","in"],"tanim":["İngiliz ve ABD geleneksel ölçü sisteminde kullanılan uzunluk ve su derinliği birimidir.","1 inç tam olarak 25,4 mm değerine eşittir.","Yağış derinliği, sızma kaybı, buharlaşma tavası ölçümleri ve SCS eğri numarası yönteminde tutma kapasitesi hesabında kullanılır."],"tanim_en":"A unit of length in the English and United States customary systems equal to 25.4 millimetres, widely used for precipitation depth.","bag":{"kavram":["akis-birim","ic-kayip","scs-cn"],"soru":["S2","S4","S6","S14","S15","S26"],"hesap":["havza-butcesi","kalis-suresi","cfs-m3s","radar-zr"]}},{"id":"unit-kg-m2","tr":"Kilogram bölü metrekare","en":"Kilogram per square metre","kisa":"kg/m²","tur":"birim","es":["kg m-2","kg/m2","kilogram/metrekare","kilograms per square metre","kilograms per square meter","kg/m²"],"tanim":["SI sisteminde birim yüzey alanına düşen kütleyi belirten alansal kütle yoğunluğu birimidir.","Suyun yoğunluğu 1000 kg/m³ olduğunda 1 m² alana 1 mm kalınlığında su yayılması 1 kg kütleye denktir (1 kg/m² = 1 mm).","Atmosfer sütunundaki yağışa geçebilir su miktarını ve olası en büyük yağış hesaplarını kütle tabanında ifade etmek için kullanılır."],"tanim_en":"The SI unit of surface density equal to one kilogram distributed over an area of one square metre, equivalent to one millimetre of water depth.","bag":{"kavram":["akis-birim","pw","hershfield"],"soru":["S23","S24","S29","S31"],"hesap":[]}},{"id":"unit-kg-m3","tr":"Kilogram bölü metreküp","en":"Kilogram per cubic metre","kisa":"kg/m³","tur":"birim","es":["su yoğunluğu birimi","kg/m3","yoğunluk birimi","kilogram/metreküp","kilograms per cubic metre","kg/m³"],"tanim":["SI sisteminde birim hacimdeki kütle miktarını tanımlayan hacimsel kütle yoğunluğu birimidir.","Standart koşullarda saf suyun yoğunluğu yaklaşık 1000 kg/m³ olarak kabul edilir.","Hidrolojik denklemlerde su kütlesi ile su hacmi arasındaki dönüşümü sağlamak ve hidrostatik basınç hesabını yürütmek için kullanılır."],"tanim_en":"The SI coherent derived unit of volumetric density equal to one kilogram per cubic metre of volume.","bag":{"kavram":["akis-birim","pw"],"soru":["S24"],"hesap":[]}},{"id":"unit-km2","tr":"Kilometrekare","en":"Square kilometre","kisa":"km²","tur":"birim","es":["sq km","10^6 m2","km2","square kilometer","kilometrekare alan","alan km2"],"tanim":["Metrik sistemde kenarları 1000 metre olan bir karenin alanına eşit standart coğrafi alan birimidir.","1 km² tam olarak 1 000 000 m² ya da 100 hektara eşittir; 1 mm derinliğinde yağış 1 km² alanda 1000 m³ su hacmi üretir.","Hidrolojik havza sınırlandırmasında, alansal yağış ortalamalarında ve ölçüm ağı yoğunluğu ölçütlerinde temel alan birimidir."],"tanim_en":"A metric unit of area equal to the area of a square with sides of one kilometre, equivalent to one million square metres.","bag":{"kavram":["akis-birim","thiessen","izohiyet"],"soru":["S1","S2","S4","S10","S11","S13"],"hesap":[]}},{"id":"unit-m3-s","tr":"Metreküp bölü saniye","en":"Cubic metres per second","kisa":"m³/s","tur":"birim","es":["cumec","m3/s","kübik metre bölü saniye","debi birimi","metreküp/saniye","metreküp / saniye"],"tanim":["SI sisteminde bir akarsu kesitinden bir saniyede geçen bir metreküp akışkan hacmini belirten debi birimidir.","Uluslararası hidrolojide standart akım birimi olup 1 m³/s yaklaşık 35,315 cfs değerine karşılık gelir.","Hidrograf çizimlerinde, taşkın ötelemesinde ve hidrometeorolojik tasarım debisi belirlemelerinde temel büyüklüktür."],"tanim_en":"The coherent SI derived unit of volumetric flow rate equal to one cubic metre of fluid passing a cross-section per second.","bag":{"kavram":["akis-birim","su-butcesi","hazne"],"soru":["S1","S2","S4","S25","S26","S30"],"hesap":["cfs-m3s","rasyonel","rasyonel-ing"]}},{"id":"unit-mi2","tr":"Milkare","en":"Square mile","kisa":"mi²","tur":"birim","es":["sq mi","kare mil","mi²","mil kare"],"tanim":["İngiliz ve ABD geleneksel ölçü sisteminde kenarları bir mil olan karenin alanını belirten coğrafi alan birimidir.","1 milkare tam olarak 640 akre ya da yaklaşık 2,58999 km² alana eşittir; 1 inç yağışın 1 mi² alana yayılması 53,33 akre-ayak hacim üretir.","HEC-HMS havza modellemesinde ve CBS tabanlı akarsu ağı ayırma eşiği tanımlamalarında yaygın kullanılır."],"tanim_en":"A unit of area in the English and United States customary systems equal to 640 acres or approximately 2.59 square kilometres.","bag":{"kavram":["akis-birim","ic-kayip","gis-havza"],"soru":["S34","S39"],"hesap":[]}},{"id":"unit-mm","tr":"Milimetre","en":"Millimetre","kisa":"mm","tur":"birim","es":["millimeter","mm","mm derinlik","milimetre yağış","mm birimi","milimetre derinlik"],"tanim":["Metrenin binde birine (0,001 m) eşit olan uzunluk ve derinlik birimidir.","Yağış, buharlaşma ve akış derinliği ölçümlerinde standart birimdir; 1 m² alana düşen 1 kg su 1 mm derinliğe denktir.","Kitapta su bütçesi bileşenlerinin gösteriminde ve yağış-akış bağıntılarında temel derinlik ölçüsü olarak yer alır."],"tanim_en":"A unit of length equal to one thousandth of a metre, standard for measuring precipitation and runoff depth.","bag":{"kavram":["akis-birim","su-butcesi","yagis-siddeti"],"soru":["S1","S2","S4","S6","S7","S8"],"hesap":["gizli-isi","rasyonel"]}},{"id":"runoff-volume","tr":"Akış hacmi","en":"Runoff volume","kisa":"V","tur":"olcu","es":["total runoff volume","toplam akış hacmi","doğrudan akış hacmi","direct runoff volume","net akış hacmi","toplam su hacmi"],"tanim":["Bir yağış olayı sonucunda havza çıkış kesitinden geçen toplam doğrudan akış suyu miktarıdır.","Birimi m³ cinsinden verilir; hidrografta taban akışı ayrıldıktan sonra doğrudan akış hidrografının altında kalan alanın integraliyle hesaplanır.","Kitapta havza akış derinliği ve akış katsayısı değerlerinin bulunmasında temel büyüklük olarak ele alınır."],"tanim_en":"The total volume of water passing through a catchment outlet during a runoff event, obtained by integrating direct runoff.","bag":{"kavram":["akis-birim","hidrograf","ic-kayip"],"soru":["S30","S34","S43"],"hesap":["akis-derinlik","hidrograf","uzun-donem-et","havza-butcesi"]}},{"id":"sym-a-area","tr":"alan","en":"area","kisa":"A","tur":"olcu","es":["havza alanı sembolü","fırtına alanı","drenaj alanı sembolü","drainage area A","watershed area","drainage area"],"tanim":["Su toplama havzasının, fırtına yayılımının ya da su yüzeyinin iki boyutlu büyüklüğünü temsil eden semboldür.","Hidrolojik hesaplarda bağlama göre m², km² ya da ha birimleriyle yer alır; rasyonel yöntemde ha, derinlik-hacim dönüşümünde m² kullanılır.","Kitapta su bütçesi, rasyonel pik debi hesabı ve Horton derinlik-alan bağıntılarında temel değişken olarak kullanılır."],"tanim_en":"A variable denoting catchment area, rainfall coverage, or lake surface area in hydrological equations.","bag":{"kavram":["akis-birim","rasyonel","horton-da"],"soru":["S1","S2","S4","S10","S11","S13"],"hesap":["uzun-donem-et","havza-butcesi","akis-derinlik","thiessen"]}},{"id":"perched-water-table","tr":"Tünemiş su tablası","en":"Perched water table","kisa":"","tur":"kavram","es":["askıda su tablası","perched aquifer"],"tanim":["Doymamış bölge içinde, düşük geçirgenliğe sahip yerel bir tabakanın üzerinde suyun birikmesiyle ana su tablasından bağımsız oluşan yerel doygun katmandır.","Genellikle geçici nitelik taşır; yağışlı dönemlerde tabaka üzerinde su birikerek yanal ara akışa ya da yüzeye ulaşıp doygunluk fazlası akışa yol açar.","Kitapta yamaç hidrolojisi ve doygunluk akışı mekanizmalarında yerel doygunluk alanlarının oluşumunu açıklamakta kullanılır."],"tanim_en":"Region in the unsaturated zone where the soil may be locally saturated because it overlies a low-permeability zone.","bag":{"kavram":["akis-mekanizma","taban-akisi"],"soru":[],"hesap":[]}},{"id":"saturated-zone","tr":"Doygun bölge","en":"Saturated zone","kisa":"","tur":"kavram","es":["phreatic zone","yeraltı suyu doygunluk kuşağı"],"tanim":["Su taşıyan bir jeolojik formasyonun bütün gözenek ve boşluklarının tamamen suyla dolu olduğu yer altı katmanıdır.","Bu bölgede gözenek suyu basıncı atmosfer basıncından büyüktür ve bölgenin üst sınırını serbest akiferlerde yeraltı su tablası belirler.","Kitapta taban akışını besleyen yeraltı suyu rezervuarı ve yüzeye ulaştığında Dunne akışını oluşturan ortam olarak yer alır."],"tanim_en":"Part of a water-bearing formation in which all voids are filled with water.","bag":{"kavram":["akis-mekanizma","taban-akisi"],"soru":[],"hesap":[]}},{"id":"unsaturated-zone","tr":"Doymamış bölge","en":"Unsaturated zone","kisa":"","tur":"kavram","es":["vadoz zon","vadose zone","aerasyon zonu"],"tanim":["Yer yüzeyi ile yeraltı su tablası arasında bulunan, boşluklarında hem hava hem su yer alan yer altı kuşağıdır.","Bu kuşakta su basıncı atmosfer basıncından düşüktür; sızan su matris emme kuvvetiyle tutulur ya da yerçekimiyle derine süzülür.","Kitapta sızma kaybının emildiği ve yağışın doğrudan akışa geçmesini engelleyen ana depolama kuşağı olarak değerlendirilir."],"tanim_en":"Subsurface zone above the water table in which the interstices are filled with air and water, and the water pressure is less than atmospheric pressure.","bag":{"kavram":["akis-mekanizma","su-yolu"],"soru":[],"hesap":[]}},{"id":"variable-source-area","tr":"değişken katkı alanı (değişken kaynak alanı)","en":"variable source area","kisa":"VSA","tur":"kavram","es":["değişken alan konsepti","değişken akış alanı","contributing area","expanding source area","değişken katkı alanı","VSA"],"tanim":["Yağış sırasında doymuş duruma gelerek doğrudan yüzey akışına fiilen su veren ve fırtına boyunca dinamik biçimde genişleyip daralan havza bölümüdür.","Özellikle vadi tabanlarında ve dere kenarlarında su tablasının yüzeye çıkmasıyla oluşur; Dunne akış mekanizmasının temel çalışma alanıdır.","Kitapta havzanın tamamının değil, yalnızca doymuş kesimlerinin akış ürettiğini gösteren kavram olarak ele alınır."],"tanim_en":"The dynamic portion of a drainage basin that becomes saturated and contributes to direct runoff during a storm.","bag":{"kavram":["akis-mekanizma"],"soru":[],"hesap":[]}},{"id":"cumulative-infiltration","tr":"birikimli sızma","en":"cumulative infiltration","kisa":"F","tur":"olcu","es":["kümülatif infiltrasyon","toplam sızma derinliği","sızma kaybı"],"tanim":["Yağış başlangıcından itibaren geçen süre boyunca birim zemin alanından içeriye giren toplam su derinliğidir.","Birimi mm cinsinden ölçülür; anlık sızma kapasitesinin zamana göre integraline eşittir ve zemin doygunluğa eriştikçe artış eğimi yatıklaşır.","Kitapta yüzey akışına katılmayan hidrolojik sızma kayıplarının toplam derinliğini belirlemede kullanılır."],"tanim_en":"The total depth of water that has infiltrated into the soil profile over a given duration from rainfall onset.","bag":{"kavram":["akis-mekanizma","su-yolu"],"soru":[],"hesap":[]}},{"id":"hydraulic-conductivity","tr":"hidrolik iletkenlik","en":"hydraulic conductivity","kisa":"K","tur":"olcu","es":["geçirgenlik katsayısı","soil conductivity","toprak geçirgenlik katsayısı sembolü"],"tanim":["Gözenekli bir ortamın, birim hidrolik eğim altında birim alandan su iletme kapasitesini belirten fiziksel katsayıdır.","Birimi mm/h ya da m/s cinsinden verilir; doymuş zeminlerde kumlu bünyede 10–25 mm/h düzeyindeyken killi bünyede 1–3 mm/h düzeyine geriler.","Kitapta Horton sızma eğrisinin son sızma kapasitesi (f_c) ve HEC-HMS sabit kayıp hızı parametresinin fiziksel karşılığıdır."],"tanim_en":"A property of porous media relating specific discharge to the hydraulic gradient under laminar flow.","bag":{"kavram":["akis-mekanizma"],"soru":[],"hesap":[]}},{"id":"infiltration-capacity","tr":"sızma kapasitesi (f, f₀)","en":"infiltration capacity","kisa":"f","tur":"olcu","es":["sızma hızı kapasitesi","zeminin sızma yeteneği","sızma sığası","infiltrasyon kapasitesi","kuru toprak sızma kapasitesi","initial infiltration rate"],"tanim":["Belirli koşullar altında suyun birim zamanda ve birim alanda toprak matriksine girebileceği en yüksek hızdır.","Birimi mm/h cinsinden ifade edilir; kuru zeminde başlangıç kapasitesi f₀ ile en yüksek değerine ulaşır, zemin ıslandıkça azalarak doygun hidrolik iletkenliğe (f_c) iner.","Kitapta Horton mekanizmasında yağış şiddetiyle (i > f) kıyaslanarak yüzey akışının oluşumunu denetleyen temel ölçüttür."],"tanim_en":"Maximum rate at which water can penetrate the soil matrix per unit area under certain conditions.","bag":{"kavram":["akis-mekanizma","ic-kayip"],"soru":["S31"],"hesap":["ic-kayip"]}},{"id":"ponding-time","tr":"göllenme zamanı","en":"ponding time","kisa":"tp","tur":"olcu","es":["time to ponding","göllenme anı","göllenme zamanı sembolü","ponding time tp","yüzeyde göllenme","surface ponding"],"tanim":["Yağış başlangıcından yüzeyde serbest su birikintilerinin oluşmaya başladığı ana kadar geçen süre.","Toprağın anlık sızma kapasitesinin yağış şiddetine eşitlendiği anda gerçekleşir ve zaman birimiyle (saat veya dk) ifade edilir.","Horton akış mekanizmasında yüzey akışının başlama anını belirler."],"tanim_en":"The time elapsed from the beginning of rainfall until the moment when water begins to accumulate on the soil surface because rainfall intensity exceeds infiltration capacity.","bag":{"kavram":["akis-mekanizma"],"soru":[],"hesap":[]}},{"id":"ultimate-infiltration-capacity","tr":"son sızma kapasitesi (fc, Horton)","en":"final infiltration capacity","kisa":"fc","tur":"olcu","es":["denge sızma kapasitesi","steady-state infiltration capacity","doygun hidrolik iletkenlik","sabit sızma hızı sembolü","steady-state infiltration","fc"],"tanim":["Uzun süreli ve sürekli yağış altında toprak tam doygunluğa ulaştığında gözlenen en düşük ve kararlı sızma hızı.","Birimi mm/saat veya inç/saat olup doymuş hidrolik iletkenliğe yakınsar; kumlu toprakta 10–25 mm/saat, killi toprakta 1–3 mm/saat aralığında yer alır.","Horton sızma denkleminde asimptotik alt sınırı, HEC-HMS modelinde ise başlangıç kaybı sonrasındaki sabit kayıp hızını temsil eder."],"tanim_en":"The minimum asymptotic rate at which a fully saturated soil can absorb water under ponded conditions.","bag":{"kavram":["akis-mekanizma","ic-kayip"],"soru":["S34","S38"],"hesap":["ic-kayip"]}},{"id":"capillary-action","tr":"Kılcallık","en":"Capillary action","kisa":"","tur":"surec","es":["kapiler hareket","kılcal yükselme","capillarity","capillary rise","kılcal çekim"],"tanim":["Suyun katı yüzeylerle adhezyon ve kohezyon kuvvetleri ile yüzey gerilimi etkisiyle dar toprak gözeneklerinde yerçekimine karşı veya yanal hareket etmesi.","Yeraltı su tablası üzerinde kapiler saçak kuşağını meydana getirir ve doymamış bölgede emme basıncıyla su tutulmasını sağlar.","Kuru toprağın ilk sızma emişini güçlendirir ve bitki kök bölgesine besin maddelerinin taşınmasına katkı verir."],"tanim_en":"The movement of water within narrow soil pores caused by surface tension, adhesion, and cohesion, often acting against gravity.","bag":{"kavram":["akis-mekanizma"],"soru":[],"hesap":[]}},{"id":"overland-flow","tr":"yüzey akışı (yüzeysel akış)","en":"overland flow (surface runoff)","kisa":"","tur":"surec","es":["yüzeysel akış","surface runoff","yamaç yüzey akışı","Yüzeysel akış","overland flow","doğrudan yüzey akışı"],"tanim":["Belirgin bir akarsu yatağına girmeden önce zemin yüzeyi üzerinden yamaç boyunca akan yağış suyu payı.","Tutulma, çukur depolaması ve sızma kayıpları karşılandıktan sonra oluşan fazla yağışla meydana gelir; havza akış bileşenleri içinde en yüksek hıza sahiptir.","Akım hidrografının yükselme kolunu ve tepe debisi noktasını doğrudan belirler."],"tanim_en":"The flow of precipitation water over the ground surface before it reaches a defined stream channel.","bag":{"kavram":["akis-mekanizma","hidrograf","su-yolu"],"soru":["S5","S31"],"hesap":[]}},{"id":"return-flow","tr":"geri dönen akış (return flow)","en":"return flow","kisa":"","tur":"surec","es":["vadi tabanına çıkan ara akış","resurfacing flow","yüzeye çıkan akış","dönen akış"],"tanim":["Yamaçta toprağa sızıp yanal akan suyun, vadi tabanındaki doymuş alanda yeniden yüzeye çıkması (geri dönen akış).","Yüzeye çıkan bu su, doymuş alana doğrudan düşen yağmurla birleşerek doygunluk fazlası (Dunne) yüzey akışını büyütür.","WMO sözlüğünde aynı terim sulama ya da kullanım için çevrilen suyun yeniden akarsuya ya da yeraltına dönen kısmı anlamında da kullanılır."],"tanim_en":"Water that infiltrates on a slope and emerges at the surface in a valley bottom, or water returning to a channel after diversion.","bag":{"kavram":["akis-mekanizma","hidrograf"],"soru":[],"hesap":[]}},{"id":"horton-infiltration-equation","tr":"Horton sızma denklemi","en":"Horton infiltration equation","kisa":"","tur":"yontem","es":["Horton sızma modeli","Horton equation","Horton formülü","Horton sızma bağıntısı"],"tanim":["Yağış şiddeti sızma kapasitesini aştığında sızma hızının başlangıç değerinden kararlı son değere doğru üstel azalışını veren ampirik formül.","Başlangıç sızma kapasitesi (f₀), son sızma kapasitesi (fc) ve azalma katsayısı (k) olmak üzere üç parametre barındırır.","Hidrolojide göllenme zamanı sonrasında yüzey akışına dönüşecek fazla yağış miktarının ve hiyetografının türetilmesinde kullanılır."],"tanim_en":"An empirical equation describing the exponential decay of soil infiltration capacity from an initial to a steady final rate during a storm.","bag":{"kavram":["akis-mekanizma"],"soru":[],"hesap":[]}},{"id":"linearity-assumption","tr":"doğrusallık varsayımı","en":"linearity assumption","kisa":"","tur":"kavram","es":["birim hidrograf doğrusallığı","linear system assumption","linearity","orantılılık ilkesi","doğrusallık hipotezi"],"tanim":["Bir değişkendeki değişimin diğer değişkende doğrudan orantılı bir değişim meydana getirdiği doğrusal ilişki kabulü.","Havzaya giren fazla yağış miktarı belirli bir oranla değiştiğinde, çıkıştaki doğrudan akış debisi hidrografı ordinatlarının da aynı oranda ölçekleneceğini öngörür.","Birim hidrograf yönteminin ve süperpozisyon ilkesinin temelini oluşturur; yağış iki katına çıktığında doğrudan akış debisi de iki katına çıkar."],"tanim_en":"The principle that direct runoff discharge is directly proportional to excess rainfall depth in linear catchment modeling.","bag":{"kavram":["birim-hidrograf"],"soru":[],"hesap":[]}},{"id":"time-invariance","tr":"zamanla değişmezlik","en":"time invariance","kisa":"","tur":"kavram","es":["zaman invaryansı","time-invariant system","time-invariant response","zamandan bağımsızlık","sistem invaryansı"],"tanim":["Bir sistemin belirli bir girdiye verdiği tepkinin, girdinin uygulandığı zamandan bağımsız olması ve zaman içinde biçim değiştirmemesi ilkesi.","Havzanın morfolojik ve hidrolik özelliklerinin fırtınalar arasında değişmediğini, aynı fazla yağış girdisine her zaman özdeş birim hidrograf tepkisi verileceğini kabul eder.","Birim hidrograf hesabında sonraki adımlarda gelen yağışların akış tepkilerinin biçim değiştirmeden yalnızca zamanda ötelenerek toplanmasını sağlar."],"tanim_en":"The property of a hydrological catchment where the unit runoff response remains identical over time regardless of when rainfall occurs.","bag":{"kavram":["birim-hidrograf"],"soru":["S40"],"hesap":[]}},{"id":"sym-u-ordinate","tr":"birim hidrograf ordinatı","en":"unit hydrograph ordinate","kisa":"U","tur":"olcu","es":["Qₙ","Pₘ","convolution ordinate","U","birim hidrograf debisi","U ordinatı"],"tanim":["Belirli bir süre boyunca havza geneline düzgün yayılan 1 birimlik (örneğin 10 mm) fazla yağışın havza çıkışında oluşturduğu doğrudan akış debisi.","Birimi m³/s olup ardışık zaman adımlarında (örneğin 0, 5, 15, 10, 5, 0 m³/s) havzanın hidrograf ordinat değerlerini gösterir.","Kesikli evrişim denkleminde fazla yağış bloklarıyla çarpılarak toplam doğrudan akış hidrografının ordinatlarını oluşturur."],"tanim_en":"The discharge value of a unit hydrograph at a given time step resulting from one unit of excess precipitation over a catchment.","bag":{"kavram":["birim-hidrograf"],"soru":[],"hesap":["birim-hidrograf"]}},{"id":"discrete-convolution","tr":"kesikli evrişim (konvolüsyon)","en":"discrete convolution","kisa":"","tur":"yontem","es":["convolution of excess rainfall","kesikli evrişim","konvolüsyon integrali","konvolüsyon","convolution","kesikli konvolüsyon"],"tanim":["Kesikli zaman serisi olarak verilen fazla yağış girdisi ile havzanın birim hidrograf tepkisini çarparak doğrudan akış hidrografını türeten matematiksel işlem.","Her zaman adımındaki fazla yağış bloğunun meydana getirdiği ötelenmiş akış katkılarını süperpozisyon ilkesi uyarınca üst üste toplar.","Birim hidrograf yönteminde doğrusal havza sisteminin toplam taşkın debisi hidrografını elde etmek için temel algoritma olarak kullanılır."],"tanim_en":"A mathematical operation that combines discrete excess rainfall blocks with unit hydrograph ordinates through superposition to determine the direct runoff hydrograph.","bag":{"kavram":["birim-hidrograf"],"soru":[],"hesap":["birim-hidrograf"]}},{"id":"s-curve","tr":"S-eğrisi (S-hidrografı)","en":"S-curve (S-hydrograph)","kisa":"","tur":"yontem","es":["S-curve method","S-hydrograph","S hidrografı","S eğrisi","1-hour UH","1 saatlik BH"],"tanim":["Bir havzada birim sürede bir birim etkin yağışın kesintisiz sürmesi halinde oluşan birikimli doğrudan akış hidrografı.","Birim hidrografların kendi süreleri kadar ötelenerek üst üste toplanmasıyla elde edilir ve zamanla denge debisine ulaşır.","Belirli bir süreli birim hidrograftan farklı süreli yeni bir birim hidrograf türetmek için kullanılır."],"tanim_en":"A direct runoff hydrograph resulting from continuous effective rainfall at a constant rate over a drainage basin.","bag":{"kavram":["birim-hidrograf"],"soru":["S41","S43"],"hesap":["scs-cn","birim-hidrograf"]}},{"id":"superposition-principle","tr":"üst üste toplama (süperpozisyon)","en":"superposition principle","kisa":"","tur":"yontem","es":["principle of superposition","lag and add","süperpozisyon ilkesi","ötele ve topla"],"tanim":["Doğrusal hidrolojik sistemlerde ardışık yağış darbelerinin oluşturduğu akışların birbirine eklenerek toplam akışın bulunabileceğini belirten temel ilke.","Sistem tepkisinin yağış miktarıyla orantılı olduğunu ve farklı zamanlardaki girdilerin birbirinden bağımsız toplanabileceğini varsayar.","Birim hidrograftan karmaşık yağışlar için doğrudan akış hidrografı türetilirken çarp, ötele ve topla adımlarında kullanılır."],"tanim_en":"A principle stating that the total runoff hydrograph from multiple rainfall periods equals the sum of the individual hydrographs shifted in time.","bag":{"kavram":["birim-hidrograf"],"soru":["S40","S43"],"hesap":["birim-hidrograf"]}},{"id":"synthetic-unit-hydrograph","tr":"sentetik birim hidrograf","en":"synthetic unit hydrograph","kisa":"SUH","tur":"yontem","es":["synthetic UH","sentetik BH","yapay birim hidrograf","SUH"],"tanim":["Akım gözlemi bulunmayan veya yetersiz olan havzalarda havza morfometrisi ve fiziksel parametrelere dayanılarak türetilen birim hidrograf.","Havza alanı, ana kol uzunluğu ve havza eğimi gibi özellikler kullanılarak ampirik bağıntılarla tepe debisi ve gecikme süresi hesaplanır.","HEC-HMS gibi hidrolojik model yazılımlarında akım verisi olmayan alt havzaların taşkın hidrografını belirlemekte kullanılır."],"tanim_en":"A unit hydrograph developed for ungauged catchments based on empirical relations with physical basin characteristics.","bag":{"kavram":["birim-hidrograf","clark"],"soru":[],"hesap":["clark","birim-hidrograf"]}},{"id":"break-in-slope","tr":"eğim kırılması","en":"break in slope","kisa":"","tur":"kavram","es":["kırılma noktası","slope change","eğim değişimi","çift kütle kırılması"],"tanim":["Çift kütle eğrisi grafiğinde birikimli değerlerin oluşturduğu doğrunun eğiminde meydana gelen belirgin açısal yön değişimi.","İstasyon taşınması, alet türünün değişmesi veya çevre örtüsündeki başkalaşım gibi yapay etkenlerin ölçüm şartlarını değiştirdiğini gösterir.","Yağış serisinde tutarlılığın hangi yılda bozulduğunu belirleyip eski dönemi düzeltmek için gereken eğim oranını hesaplamaya yarar."],"tanim_en":"A significant change in the gradient of a double-mass curve indicating a change in the observation conditions at a station.","bag":{"kavram":["cift-kutle"],"soru":["S14"],"hesap":[]}},{"id":"climatological-normal","tr":"yıllık normal yağış (iklim normali)","en":"normal annual precipitation (climatological normal)","kisa":"N","tur":"kavram","es":["Nₓ","Nᵢ","%10 kuralı","iklim normali","yıllık normal"],"tanim":["Bir istasyonda uzun bir dönemin (WMO standardı 30 yıl; güncel dönem 1991–2020) yıllık toplam yağışlarının ortalaması.","Kitaptaki normal oran örneğinde (S44) eksik istasyonun normali Nₓ = 900 mm, komşularınki 820, 1050 ve 930 mm'dir.","Normaller birbirinden %10'dan fazla farklıysa eksik değer basit ortalama yerine normal oran yöntemiyle tamamlanır."],"tanim_en":"The average value of annual precipitation computed over a uniform and relatively long period of at least thirty years.","bag":{"kavram":["cift-kutle","normal-oran","su-butcesi"],"soru":["S44"],"hesap":[]}},{"id":"consistency-of-record","tr":"tutarlılık","en":"consistency","kisa":"","tur":"kavram","es":["consistency of a record","seri tutarlılığı","inconsistent data","consistency check","a consistent series","tutarlılık testi"],"tanim":["Bir istasyonun gözlem serisindeki verilerin zaman boyunca aynı ölçüm şartlarında ve çevre ortamında toplanmış olma niteliği.","İstasyonun taşınması, alet değişimi veya çevredeki yapılaşma gibi yapay etkenlerden kaynaklanan sistematik sapmaların bulunmadığını gösterir.","Hidrolojik analiz öncesinde en az 30 yıllık serinin homojenliğini doğrulamak amacıyla çift kütle eğrisiyle sınanır."],"tanim_en":"A condition where a station observation series represents uniform observational conditions without artificial systematic shifts over time.","bag":{"kavram":["cift-kutle","normal-oran"],"soru":["S15"],"hesap":[]}},{"id":"homogeneity","tr":"homojenlik","en":"homogeneity","kisa":"","tur":"kavram","es":["türdeşlik","seri homojenliği","homogeneity test"],"tanim":["Bir ölçüm serisinin baştan sona aynı koşullarda (aynı yer, aynı alet, aynı çevre) elde edilmiş olması; seri içindeki farklar yalnız doğal değişkenlikten gelir.","Taşkın serisinde değerler aynı tür nedenden ve değişmeyen havzadan gelmeli: kentleşme, ya da baraj veya köprü yıkılmasından gelen yağışsız taşkın seriyi bozar.","Yağış serisinde çift kütle eğrisiyle denetlenir: noktalar tek doğru üzerindeyse seri homojendir, eğim kırılması bozulmayı gösterir (WMO-No. 385'te sözcüğün yeraltı suyunda ayrı bir anlamı da var)."],"tanim_en":"Property of a data series obtained under unchanged observing conditions, so that its variations reflect only natural variability.","bag":{"kavram":["taskin-frekansi","cift-kutle"],"soru":[],"hesap":[]}},{"id":"outlier","tr":"aykırı değer","en":"outlier","kisa":"","tur":"kavram","es":["aşırı uç değer","tek aykırı değer","outlier test"],"tanim":["Bir veri kümesindeki diğer tüm gözlemlerden belirgin derecede farklı ve genel dağılım eğiliminden çok uzak olan aşırı değer.","Alet hatası gibi yapay bir kusurdan veya nadir görülen olağanüstü şiddetli bir meteorolojik olaydan ileri gelebilir.","Frekans analizinde ve Hershfield olası en büyük yağış hesabında tek bir aykırı değer ortalamayı ve standart sapmayı büyüterek sonucu katlar."],"tanim_en":"An observation that deviates markedly from the other members of the sample in which it appears.","bag":{"kavram":["cift-kutle","hershfield"],"soru":["S23"],"hesap":[]}},{"id":"correction-factor","tr":"düzeltme katsayısı","en":"correction factor","kisa":"c.f.","tur":"olcu","es":["apply a correction factor","düzeltme katsayısı Mc/Ma","c.f.","Mc/Ma","eğim oranı"],"tanim":["Sistematik bir hata veya gözlem koşulu değişikliği içeren verileri referans seviyeye uyarlamak için çarpılan boyutsuz katsayı.","Çift kütle eğrisi yönteminde eğim kırılmasından sonraki eğimin kırılmadan önceki eğime bölünmesiyle hesaplanır.","İstasyon yerinin taşınması öncesindeki eski yağış verilerini güncel ölçüm şartlarına uyumlu kılmak için kullanılır."],"tanim_en":"A numerical factor by which a quantity is multiplied in order to adjust for systematic errors or changes in observational conditions.","bag":{"kavram":["cift-kutle"],"soru":["S14"],"hesap":["cift-kutle"]}},{"id":"storage-coefficient","tr":"depolama katsayısı (Clark R)","en":"storage coefficient (Clark)","kisa":"R","tur":"olcu","es":["Clark depolama katsayısı","Clark storage coefficient","hazne depolama sabiti","Clark R","storage coefficient"],"tanim":["Clark birim hidrografında havza çıkışına konan doğrusal haznenin depolama sabiti: depo = R × çıkış (S = R·O); birimi saattir.","R büyüdükçe hazne suyu daha uzun tutar: hidrograf tepesi düşer, gecikir ve yayvanlaşır (kitap S35: R = 12 h'te tepe 45,3 m³/s, R = 24 h'te 24,7 m³/s).","Aynı ad hidrojeolojide başka bir büyüklüğü (akiferin birim yük düşümünde verdiği su hacmi, depolama katsayısı) anlatır; Clark'taki R bir zaman sabitidir."],"tanim_en":"In the Clark unit hydrograph, the time constant R (hours) of the linear reservoir, storage = R × outflow, that attenuates the translated runoff.","bag":{"kavram":["clark"],"soru":["S35"],"hesap":["clark"]}},{"id":"surface-roughness","tr":"yüzey pürüzlülüğü","en":"surface roughness","kisa":"n","tur":"olcu","es":["hidrolik pürüzlülük","Manning pürüzlülüğü"],"tanim":["Yüzey üzerinden akan suyun veya hareket eden havanın karşılaştığı sürtünme direncini belirleyen fiziksel pürüzlülük özelliği.","Açık kanal ve yüzeysel akış hesaplarında genellikle Manning pürüzlülük katsayısı (n) ile temsil edilir.","Havzada akış hızını, toplanma süresini ve hidrograf tepe debisinin ötelenme miktarını doğrudan etkiler."],"tanim_en":"Frictional resistance offered by a ground or channel surface to the movement of water or air across it.","bag":{"kavram":["clark","oteleme"],"soru":[],"hesap":["clark"]}},{"id":"sym-ca-clark","tr":"Clark ağırlıkları","en":"Clark routing coefficients","kisa":"C_A, C_B","tur":"olcu","es":["giriş ağırlığı","Clark inflow coefficient","hafıza ağırlığı","Clark carryover coefficient","CB — Clark hafıza katsayısı","Clark routing coefficient CB symbol"],"tanim":["Clark birim hidrografı doğrusal hazne sonlu fark denkleminde kullanılan boyutsuz yönlendirme katsayıları.","C_A yeni giriş akımının mevcut çıkışa yansıyan payını, C_B = 1 − C_A ise bir önceki çıkış debisinin süren etkisini temsil eder.","Zaman adımı Δt ve depolama katsayısı R parametrelerinden analitik olarak hesaplanır."],"tanim_en":"Dimensionless routing coefficients derived from time step and storage coefficient to route inflow through a linear reservoir.","bag":{"kavram":["clark"],"soru":[],"hesap":["clark"]}},{"id":"time-area-histogram","tr":"zaman–alan histogramı","en":"time–area histogram","kisa":"","tur":"yontem","es":["zaman-alan eğrisi","time–area curve","time–area method"],"tanim":["Bir havzada eş varış zamanı çizgileri arasında kalan drenaj alanlarının çıkış noktasına ulaşma sürelerine göre dağılımını gösteren grafik.","Toplanma süresi Tc eşit zaman adımlarına bölünerek her aralıktan çıkışa katkı sağlayan alan büyüklüğü hesaplanır.","Clark birim hidrograf yönteminde yağış akışının çıkışa ötelenmesini sağlayıp doğrusal hazneye giren debiyi üretir."],"tanim_en":"Histogram showing the distribution of catchment area contributing to runoff at the outlet as a function of travel time.","bag":{"kavram":["clark"],"soru":[],"hesap":["clark"]}},{"id":"spillway","tr":"dolusavak","en":"spillway","kisa":"Qcap","tur":"cihaz","es":["spillway design flood","baraj dolusavağı","taşkın savağı","dolu savak","spillway crest","savak"],"tanim":["Baraj ve bentlerde fazla taşkın suyunun yapıya zarar vermeden mansaba aktarılmasını sağlayan hidrolik yapı.","Geçirebileceği en yüksek debi olası en büyük taşkın (PMF) ya da yüksek tekerrür süreli taşkın debilerine göre tasarlanır.","Hazne su bütçesinde su seviyesi kret kotunu aştığında çıkan debiyi (Qout) oluşturarak baraj gövdesinin aşılmasını önler."],"tanim_en":"Structure, usually in dams, over which excess flood water flows.","bag":{"kavram":["donus-risk","zarf","hershfield"],"soru":[],"hesap":[]}},{"id":"geometric-distribution","tr":"geometrik dağılım (ilk aşılmaya kadar bekleme)","en":"geometric distribution","kisa":"","tur":"kavram","es":["geometrik bekleme süresi","geometric waiting time","en az bir aşılma","at least once","en az bir kez aşılma","exceeded at least once"],"tanim":["Bağımsız Bernoulli denemelerinde ilk başarıya ya da ilk aşılmaya kadar gereken deneme sayısını modelleyen kesikli olasılık dağılımı.","Herhangi bir yılda aşılma olasılığı p = 1/T olduğunda beklenen bekleme süresi ortalama T yıl olur.","Dönüş aralığının istatistiksel tanımını oluşturur ve tasarım ömrü boyunca aşılma riski formülünün temelini kurar."],"tanim_en":"Discrete probability distribution of the number of independent trials required to obtain the first exceedance of a threshold.","bag":{"kavram":["donus-risk"],"soru":[],"hesap":[]}},{"id":"hundred-year-flood","tr":"100 yıllık olay (yağış / taşkın)","en":"100-year event (rainfall / flood)","kisa":"","tur":"kavram","es":["100 yıllık yağış","100 yıllık taşkın","50 yıllık yağış","100-year flood","100-year rainfall"],"tanim":["Herhangi bir yılda meydana gelme ya da aşılma olasılığı yüzde 1 (p = 0,01) olan hidrolojik taşkın veya yağış olayı.","Dönüş aralığı T = 100 yıl olup kesinlikle yüz yılda bir olacağı anlamına gelmez; birbirini izleyen yıllarda da tekrarlayabilir.","Köprü, menfez ve taşkın koruma yapılarının boyutlandırılmasında standart tasarım büyüklüğüdür."],"tanim_en":"Hydrological event that has a one percent probability of being equaled or exceeded in any single year.","bag":{"kavram":["donus-risk","hershfield","gumbel"],"soru":["S18","S24","S45"],"hesap":[]}},{"id":"design-life","tr":"tasarım ömrü","en":"design life","kisa":"n","tur":"olcu","es":["hizmet ömrü","yapı ömrü","service life","yapı ömrü sembolü","hizmet süresi sembolü"],"tanim":["Bir su yapısının (menfez, köprü, baraj) işlevini güvenle sürdürmesi planlanan hizmet süresi; birimi yıldır.","Yapının türüne ve önemine göre seçilir; kitaptaki örnekte menfezin ömrü 30 yıldır (S18).","Risk bağıntısında üs n olarak girer: ömür uzadıkça aynı dönüş aralıklı olayın en az bir kez aşılma olasılığı büyür."],"tanim_en":"Period of time in years during which a civil structure is expected to function safely and fulfill its operational role.","bag":{"kavram":["donus-risk"],"soru":[],"hesap":["risk","gumbel"]}},{"id":"exceedance-probability","tr":"aşılma olasılığı (p = 1/T)","en":"exceedance probability (AEP)","kisa":"p","tur":"olcu","es":["AEP","aşılmama olasılığı 1 − 1/T"],"tanim":["Belirli bir büyüklükteki hidrolojik debi ya da yağışın belirli bir zaman diliminde aşılma veya eşitlenme olasılığı.","Yıllık aşılma olasılığı (AEP) boyutsuz olup dönüş aralığının tersine eşittir (p = 1/T); yüzde veya ondalık kesirle gösterilir.","Hidrolojik risk analizinde ve Gumbel frekans dağılımında kümülatif aşılma olasılığını belirler."],"tanim_en":"Probability that a hydrological event of a given magnitude will be equaled or exceeded in any given year.","bag":{"kavram":["taskin-frekansi","donus-risk","gumbel"],"soru":["S18","S24"],"hesap":["risk","gumbel"]}},{"id":"sym-xt-extreme","tr":"T yıllık değer","en":"T-year value (quantile)","kisa":"X_T","tur":"olcu","es":["T yıllık değer","XT","xT","dönüş aralıklı yağış","tasarım yağışı","T-year event"],"tanim":["Belirli bir T dönüş aralığında ortalama olarak her T yılda bir kez aşılması beklenen kuantil büyüklüğünü ifade eder.","Yağış için mm, debi için m³/s biriminde tanımlanır; frekans denkleminde seri ortalaması ile standart sapmanın frekans katsayısıyla çarpımı toplanarak hesaplanır.","Kitapta Gumbel dağılımı ve frekans analiziyle hidrolik yapıların tasarım büyüklüklerini belirlemede temel kuantil olarak yer alır."],"tanim_en":"The magnitude of a hydrological event expected to be equaled or exceeded once on average during a return period of T years.","bag":{"kavram":["donus-risk","hershfield","gumbel"],"soru":["S24","S45"],"hesap":["gumbel","risk","hershfield"]}},{"id":"basin-shape","tr":"havza şekli","en":"basin shape","kisa":"","tur":"kavram","es":["havza formu","şekil faktörü","catchment shape","watershed shape"],"tanim":["Bir drenaj havzasının su ayrım çizgisiyle çevrili sınırlarının iki boyutlu geometrik biçimini ifade eder.","Dairesel, uzun veya yelpaze biçiminde sınıflandırılır; şekil faktörüyle toplanma süresini ve suyun toplanma hızını belirler.","Kitapta hidrograf tepe debisi ve pik zamanlamasını denetleyen temel havza özelliklerinden biri olarak açıklanır; yuvarlak havzada tepe debisi daha yüksek ve erken oluşur."],"tanim_en":"The geometric form and outline of a drainage basin that influences the concentration of runoff and the shape of the flood hydrograph.","bag":{"kavram":["gis-havza"],"soru":["S31"],"hesap":[]}},{"id":"hillslope","tr":"Yamaç","en":"Hillslope","kisa":"","tur":"kavram","es":["havza yamacı","eğimli yüzey","hillslope hydrological response","dağ yamacı","hillslope hydrologic response"],"tanim":["Bir drenaj havzasında su ayrım çizgisi ile akarsu yatağı arasında uzanan eğimli vadi yan yüzeyini tanımlar.","Yağışın sızma, yüzey akışı ve ara akış yoluyla vadi tabanındaki kanala iletildiği ana morfolojik birimi oluşturur.","Kitapta orografik yağış artışının görüldüğü ve Horton ile Dunne akış mekanizmalarının geliştiği eğimli alan olarak ele alınır."],"tanim_en":"The inclined surface of a drainage basin located between the drainage divide and the stream channel network.","bag":{"kavram":["gis-havza","akis-mekanizma"],"soru":["S11"],"hesap":[]}},{"id":"sink","tr":"çukur","en":"sink","kisa":"","tur":"kavram","es":["DEM çukuru","depresyon hücresi","akışsız hücre","depression","topographic sink"],"tanim":["Sayısal yükseklik modelinde (DEM) çevresindeki sekiz komşu hücrenin hepsinden alçak olan, suyun dışarı akamadığı hücre ya da hücre grubu (çukur).","Çoğu kez veri hatasıdır; doldurulmazsa akış yönü kesilir ve havza parçalanır (Preprocess Sinks adımı bunu düzeltir).","Akışkanlar dinamiğinde aynı sözcük akım çizgilerinin yakınsadığı noktayı anlatır; havza ayırmadaki anlamı topoğrafik çukurdur."],"tanim_en":"In a digital elevation model, a cell or group of cells lower than all its neighbours, from which no downslope flow path exists (a pit).","bag":{"kavram":["gis-havza"],"soru":["S5","S39"],"hesap":[]}},{"id":"stream-network","tr":"Akarsu ağı","en":"Stream network","kisa":"","tur":"kavram","es":["drenaj ağı","nehir şebekesi","kanal ağı","nehir kolları şebekesi","ana kanal","main channel"],"tanim":["Bir havzada toplanan yüzey ve yeraltı sularını ortak bir çıkış noktasına doğru boşaltan kanallar ve nehir kolları bütününü oluşturur.","Sayısal yükseklik modelinde akış birikim değeri belirli bir eşik sınırını aşan hücre dizilimlerinin birleşmesiyle haritalanır.","Kitapta havzanın alt bölümlere ayrılması ve akarsu yataklarında taşkın ötelemesi yapılması amacıyla temel iletim hattı olarak kullanılır."],"tanim_en":"The interconnected system of surface channels that drains runoff from a catchment toward a single outlet.","bag":{"kavram":["gis-havza","su-butcesi","oteleme"],"soru":[],"hesap":[]}},{"id":"digital-elevation-model","tr":"sayısal yükseklik modeli","en":"digital elevation model","kisa":"DEM","tur":"kod","es":["SYM","DEM grid","sayısal arazi modeli","DEM","digital terrain model"],"tanim":["Arazi yüzey kotlarının sayısal ve düzenli bir ızgara biçiminde bilgisayarlı temsilini oluşturur.","Piksel çözünürlüğü (Δx) ve her pikselin zemin kotuyla tanımlanan raster veri matrisi olarak tanımlanır.","Kitapta D8 algoritması aracılığıyla akış yönü, akış birikimi ve drenaj sınırlarının bilgisayarda otomatik çıkarılmasında temel altlık olarak işlev görür."],"tanim_en":"A computerized representation of land surface elevation stored as a regular grid of terrain heights.","bag":{"kavram":["gis-havza"],"soru":["S18","S39"],"hesap":[]}},{"id":"basin-slope","tr":"havza eğimi","en":"basin slope","kisa":"","tur":"olcu","es":["ortalama havza eğimi","topoğrafik eğim","catchment slope","watershed slope","ortalama eğim"],"tanim":["Bir havza yüzeyindeki düşey kot farkının yatay mesafeye oranını belirten ortalama topoğrafik meyilini ifade eder.","Metre/metre (m/m) ya da yüzde (%) biriminde ifade edilir; DEM tabanlı hücre eğimlerinin havza genelinde toplanmasıyla elde edilir.","Kitapta yüzey suyunun akış süratini, toplanma süresini ve hidrograf tepe debisinin sivriliğini denetleyen ana morfolojik faktör olarak kabul edilir."],"tanim_en":"The average rate of change in elevation along the terrain of a catchment that controls runoff velocity and hydrograph peak discharge.","bag":{"kavram":["gis-havza"],"soru":[],"hesap":["d8-egim"]}},{"id":"flow-accumulation","tr":"akış birikimi","en":"flow accumulation","kisa":"Ac","tur":"olcu","es":["akış toplanması","flow accumulation grid","birikim alanı","accumulated flow area","birikimli alan","akış birikim alanı"],"tanim":["Bir sayısal yükseklik modelinde her hücreye mansap yönünde akış ileten memba hücrelerinin toplam sayısı ya da drenaj alanını belirtir.","Hücre sayısı veya kilometrekare (km²) biriminde ölçülür; su ayrım çizgilerinde 1 iken vadi tabanlarına ve havza çıkışına doğru büyür.","Kitapta D8 akış yönü haritası üzerinden yüksekten alçağa toplanarak dere şebekesini ve havza sınırlarını ayırmada kullanılır."],"tanim_en":"The total number of upstream cells or contributing drainage area that drains into a specific grid cell.","bag":{"kavram":["gis-havza"],"soru":[],"hesap":["d8-egim"]}},{"id":"stream-threshold","tr":"akarsu eşiği","en":"stream threshold","kisa":"Amin","tur":"olcu","es":["akarsu tanımlama eşiği","stream definition threshold","eşik drenaj alanı","minimum drainage area","threshold area"],"tanim":["Sayısal yükseklik modelinde bir hücrenin sürekli akarsu kanalı sayılabilmesi için gereken en küçük akış birikim alanı ya da hücre sayısını temsil eder.","Kilometrekare (km²), milkare (mi²) veya hücre sayısı cinsinden kullanıcı tarafından tanımlanır.","Kitapta HEC-HMS akarsu tanımlama (Identify Streams) aşamasında dere ağının yoğunluğunu ve alt havza sayısını belirleyen sınır parametre olarak işlev görür."],"tanim_en":"The minimum upstream contributing area required for a grid cell to be designated as part of the stream network.","bag":{"kavram":["gis-havza"],"soru":["S39"],"hesap":["d8-egim"]}},{"id":"break-points","tr":"kırılma noktaları","en":"break points","kisa":"","tur":"yontem","es":["çıkış ve birleşim noktaları","havza kırılma noktaları","outlet points","pour points","subbasin outlets"],"tanim":["CBS tabanlı havza modellemesinde alt havza sınırlarını ayırmak amacıyla akarsu şebekesi üzerine konulan hedef döküm noktalarını belirtir.","Kanal ağı üzerinde mansap çıkışları ve kol birleşim kavşaklarına yerleştirilen noktasal koordinatlar olarak tanımlanır.","Kitapta HEC-HMS CBS adımlarında akarsuların belirlenmesinden sonra, havza elemanlarını ayırma (Delineate Elements) işleminden önce uygulanır."],"tanim_en":"Target outlet points placed along the stream network to define subbasin boundaries and drainage elements in hydrologic modeling.","bag":{"kavram":["gis-havza"],"soru":["S39"],"hesap":["d8-egim"]}},{"id":"delineate-elements","tr":"elemanları ayırma","en":"delineate elements","kisa":"","tur":"yontem","es":["havza elemanlarını çıkarma","watershed delineation","alt havza sınırlandırma"],"tanim":["Sayısal yükseklik modeli ve akış verilerinden alt havza sınırları ile akarsu kollarını vektör elemanlar olarak üreten CBS adımı.","Akış yönü ızgarasını belirlenen çıkış ve kırılma noktalarından yukarı doğru tarayarak kapalı alt havza poligonları ve akarsu çizgileri oluşturur.","Kitapta havza modelleme akışının son aşaması olup HEC-HMS modeline aktarılacak alt havza ve akarsu kesimlerini tanımlar."],"tanim_en":"The automated GIS procedure that delineates subbasin boundary polygons and stream reach vectors from flow direction grids and outlet points.","bag":{"kavram":["gis-havza"],"soru":["S39"],"hesap":["d8-egim"]}},{"id":"flow-direction","tr":"akış yönü (D8)","en":"flow direction","kisa":"","tur":"yontem","es":["D8 flow direction","D8 akış yönü","en dik iniş","maksimum eğim yönü","steepest slope","steepest descent"],"tanim":["Sayısal yükseklik modelindeki her hücrenin yüzey suyunu komşu sekiz hücreden eğimi en dik olanına yönlendiren algoritma.","Komşu hücreye uzaklık kardinal yönlerde hücre boyu (Δx), çapraz yönde ise √2·Δx alınır; düşüşün uzaklığa bölünmesiyle bulunan en büyük pozitif eğim akış yönünü seçer.","Kitapta drenaj ağının ve akış birikiminin çıkarılmasında temel yönlendirme ızgarası olarak işlev görür."],"tanim_en":"The hydrologic terrain modeling method assigning surface runoff from each grid cell to the steepest downslope neighboring cell among eight directions.","bag":{"kavram":["gis-havza"],"soru":["S39"],"hesap":["d8-egim"]}},{"id":"identify-streams","tr":"akarsuları tanımlama","en":"identify streams","kisa":"","tur":"yontem","es":["Identify Streams","dere ağı çıkarma","akarsu ağı belirleme"],"tanim":["Sayısal yükseklik modelinde birikimli drenaj alanı veya hücre sayısı belirlenen eşik değerini aşan ızgaraları akarsu yatağı olarak sınıflandıran CBS adımı.","Kullanıcının belirlediği minimum eşik alanı drenaj yoğunluğunu ve akarsu kollarının sıklığını denetler.","Kitapta akış yönü ve akış birikimi ızgaralarından yararlanarak kırılma noktaları ve alt havza sınırlarının oluşturulmasına zemin hazırlar."],"tanim_en":"The GIS method defining stream network cells whose accumulated upstream contributing area exceeds a designated threshold value.","bag":{"kavram":["gis-havza"],"soru":["S39"],"hesap":["d8-egim"]}},{"id":"preprocess-sinks","tr":"çukur doldurma","en":"preprocess sinks","kisa":"","tur":"yontem","es":["sink filling","çukur giderme"],"tanim":["Sayısal yükseklik modelinde çevresindeki komşularından daha alçak kotta kalan çukurlukların su akışını kesintiye uğratmaması için dökülme kotuna kadar doldurulması adımı.","Çukur hücrenin kotu en alçak komşusunun kotuna küçük bir artış miktarı (ε) eklenerek yükseltilir.","Kitapta kesintisiz bir drenaj ağı ve doğru akış yönü ızgarası elde etmek için akış analizlerinin başında zorunlu ön işlem olarak uygulanır."],"tanim_en":"The elevation model conditioning step raising the elevation of depression cells to their lowest outflow spill level to ensure continuous drainage flow.","bag":{"kavram":["gis-havza"],"soru":["S39"],"hesap":["d8-egim"]}},{"id":"unit-j-per-kg","tr":"joule/kilogram","en":"joules per kilogram","kisa":"J/kg","tur":"birim","es":["J/kg","joule bölü kilogram","J kg⁻¹"],"tanim":["Birim kütle başına düşen enerji miktarını gösteren SI türetilmiş birimi.","Buharlaşma gizli ısısı için kullanılır; 20 °C civarında su için yaklaşık 2,43×10⁶ J/kg değerini alır.","Buharlaşma derinliği ile gizli ısı akısı arasındaki enerji dönüşüm hesabında buharlaşma gizli ısısının (Lv) birimi olarak geçer."],"tanim_en":"SI derived unit of specific energy or heat of vaporization representing energy per unit mass.","bag":{"kavram":["gizli-isi"],"soru":["S29"],"hesap":[]}},{"id":"unit-mj-per-m2","tr":"megajoule/metrekare","en":"megajoules per square metre","kisa":"MJ/m²","tur":"birim","es":["MJ/m2","megajoule bölü metrekare","MJ m⁻²"],"tanim":["Birim yatay yüzey alanına düşen veya yüzeyden aktarılan toplam enerji miktarını gösteren birim.","Buharlaşma derinliğinin kütlesel karşılığı ile buharlaşma gizli ısısının çarpımıyla hesaplanır.","Buharlaşma için gereken günlük enerji miktarını alan bazında belirlemede kullanılır."],"tanim_en":"Unit of energy per unit surface area representing radiant exposure or energy required for evaporation.","bag":{"kavram":["gizli-isi"],"soru":["S29"],"hesap":[]}},{"id":"unit-w-per-m2","tr":"watt/metrekare","en":"watts per square metre","kisa":"W/m²","tur":"birim","es":["W/m2","watt bölü metrekare","W m⁻²"],"tanim":["Birim yüzey alanından birim zamanda aktarılan enerji akı yoğunluğunu belirten SI birimi.","Yüzey enerji bütçesi bileşenleri ile radyasyon akılarının standart ölçü birimi.","Gizli ısı akısı (LE), duyulur ısı akısı (H) ve net ışınım (Rn) terimlerini ortak birimle ifade ederek buharlaşmayı enerji dengesine bağlar."],"tanim_en":"SI unit of heat flux density representing energy transfer per unit area per unit time.","bag":{"kavram":["gizli-isi"],"soru":["S29"],"hesap":[]}},{"id":"energy-limited-evaporation","tr":"enerji sınırlı ve su sınırlı buharlaşma","en":"energy-limited vs water-limited evaporation","kisa":"","tur":"kavram","es":["enerji kısıtlı buharlaşma","radiation-limited evaporation","su kısıtlı buharlaşma","energy-limited evaporation"],"tanim":["Buharlaşmanın ortamdaki su miktarından ziyade mevcut net enerji ve atmosferik taleple sınırlandığı rejim ile su yokluğuyla sınırlandığı rejimin karşılaştırması.","Su bol olduğunda buharlaşma hızı yüzey net ışınımı ve atmosferik enerji bütçesi sınırına dayanır; kurak ortamda ise zemin nemi kontrol edici etkendir.","Hidrometeorolojide göl ve ıslak yüzeylerde buharlaşmanın üst sınırını belirlemede temel kabuldür."],"tanim_en":"Hydrologic concept where evaporation rate is constrained either by available energy or by soil moisture availability.","bag":{"kavram":["gizli-isi"],"soru":[],"hesap":[]}},{"id":"surface-energy-budget","tr":"yüzey enerji bütçesi","en":"surface energy balance","kisa":"Rn = H + LE + G","tur":"kavram","es":["enerji dengesi","energy-balance method","enerji bütçesi","energy balance","surface energy balance","yüzey enerji dengesi"],"tanim":["Yeryüzü yüzeyine ulaşan net radyasyon enerjisinin duyulur ısı, gizli ısı ve zemin ısı akıları arasındaki dağılımını ifade eden denge eşitliği.","Birimi W/m² cinsinden olup yüzey sıcaklığı ile atmosferik sınır tabakanın ısıl dengesini denetler.","Kitapta buharlaşmanın enerjisel sınırını belirlemek ve açık su ile arazi yüzeyinden buharlaşma kaybını hesaplamak için kullanılır."],"tanim_en":"The balance equation of radiant energy at the Earth surface partitioned into sensible heat, latent heat, and ground heat flux.","bag":{"kavram":["gizli-isi"],"soru":["S29"],"hesap":[]}},{"id":"ground-heat-flux","tr":"toprak ısı akısı","en":"ground heat flux","kisa":"G","tur":"olcu","es":["zemin ısı akısı","soil heat flux","toprak iletim akısı","zemin ısı iletim akısı","G"],"tanim":["Yeryüzü ile toprak katmanları arasında iletim yoluyla birim alandan birim zamanda aktarılan termal enerji akısı.","W/m² birimiyle ölçülür; gündüz zemin altına doğru pozitif, gece yüzeye doğru negatif yönlü seyreder ve günlük toplamı sıfıra yakın kalır.","Yüzey enerji bütçesinde (Rn = H + LE + G) yer alarak buharlaşmaya (LE) kalan net enerji payını doğrudan etkiler."],"tanim_en":"Rate of heat transfer through the ground per unit area by thermal conduction.","bag":{"kavram":["gizli-isi"],"soru":[],"hesap":["gizli-isi"]}},{"id":"heat-of-vaporization","tr":"buharlaşma gizli ısısı","en":"latent heat of vaporization","kisa":"Lᵥ","tur":"olcu","es":["buharlaşma ısısı","faz değişim ısısı","latent heat release","gizli ısı","latent heat","buharlaşma entalpisi"],"tanim":["Birim kütledeki suyun sıvı fazdan buhar fazına geçmesi sırasında soğurulan veya yoğuşma sırasında salınan ısı enerjisi miktarı.","SI birimi J/kg olup 20 °C civarında yaklaşık 2,43×10⁶ J/kg (580 cal/g) seviyesinde yer alır; sıcaklık arttıkça hafifçe azalır.","Kitapta buharlaşma derinliğini enerji akısına bağlamak ve maksimum potansiyel buharlaşma hızını hesaplamak için temel katsayıdır."],"tanim_en":"The amount of heat absorbed or liberated when a unit quantity of water undergoes evaporation or condensation.","bag":{"kavram":["gizli-isi"],"soru":["S29"],"hesap":["gizli-isi"]}},{"id":"net-radiation","tr":"net ışınım","en":"net radiation","kisa":"Rn","tur":"olcu","es":["net radyasyon","yüzey net ışınımı","daily net radiation","net radyasyon akısı","R_n"],"tanim":["Gelen toplam radyasyon ile yüzeyden yansıyan ve yayılan radyasyon arasındaki fark.","W/m² birimiyle ölçülür; yaz mevsiminde günlük ortalama değeri tipik olarak 150–220 W/m² aralığında gerçekleşir.","Yüzey enerji bütçesinin ana girdisi olup buharlaşmanın alabileceği en yüksek üst sınırı belirler."],"tanim_en":"Difference between incidental and reflected radiation at the Earth surface.","bag":{"kavram":["gizli-isi"],"soru":["S29"],"hesap":["gizli-isi"]}},{"id":"sensible-heat-flux","tr":"duyulur ısı akısı","en":"sensible heat flux","kisa":"H","tur":"olcu","es":["hissedilir ısı akısı","sensible heat","H akısı","duyulur ısı akısı","Hissedilir ısı akısı","hissedilir ısı"],"tanim":["Yeryüzü ile atmosfer arasındaki sıcaklık farkı nedeniyle moleküler iletim ve türbülanslı taşınımla aktarılan ısı akısı.","Sembolü H olup birimi W/m² cinsinden ölçülür; yüzey sıcaklığı havanın sıcaklığından yüksek olduğunda yüzeyden atmosfere doğru akar.","Kitapta yüzey enerji dengesinde net radyasyon enerjisinin buharlaşmaya ayrılabilecek payını azaltan temel tüketim bileşenidir."],"tanim_en":"The turbulent heat transfer between the surface and the atmosphere driven by temperature difference without state transformation.","bag":{"kavram":["gizli-isi"],"soru":[],"hesap":["gizli-isi"]}},{"id":"warm-dry-air-advection","tr":"sıcak kuru hava adveksiyonu (vaha etkisi)","en":"advection of warm dry air (oasis effect)","kisa":"","tur":"surec","es":["sıcak adveksiyon","oasis effect","termal adveksiyon","vaha etkisi"],"tanim":["Çevredeki kurak ve sıcak arazilerden esen rüzgârın ıslak yüzey veya göl üzerine yatay ısı ve kuru hava taşıması süreci.","Taşınan duyulur ısı ters yönlü akıyla yüzeye aktarılarak buharlaşma gizli ısı akısının yerel net ışınım değerini aşmasına imkân verir.","Buharlaşma tavası ya da sulanan tarım alanlarında ölçülen buharlaşmanın yerel güneş enerjisi sınırının üzerine çıkmasını açıklar."],"tanim_en":"Horizontal transport of sensible heat from surrounding dry land into a moist area enhancing evaporation.","bag":{"kavram":["gizli-isi"],"soru":[],"hesap":[]}},{"id":"penman-monteith-method","tr":"Penman–Monteith yöntemi","en":"Penman–Monteith method","kisa":"PM","tur":"yontem","es":["Penman-Monteith denklemi","FAO-56 Penman-Monteith","Penman-Monteith yaklaşımı","FAO-56"],"tanim":["Net radyasyon, hava sıcaklığı, bağıl nem, rüzgâr hızı ile yüzey ve aerodinamik dirençleri birleştiren evapotranspirasyon hesaplama yöntemi.","FAO-56 standardı olarak referans çim yüzeyi için geliştirilmiş olup fiziksel tabanlı direnç ağını kullanır.","Doğrudan ölçümü pahalı ve güç olan gerçek evapotranspirasyonu meteorolojik verilerle güvenilir biçimde modellemede temel araçtır."],"tanim_en":"Method for estimating evapotranspiration by combining energy balance and aerodynamic transport with surface resistance.","bag":{"kavram":["gizli-isi","tava"],"soru":[],"hesap":["hazne-ay","tava","gizli-isi"]}},{"id":"cumulative-distribution-function","tr":"birikimli dağılım fonksiyonu","en":"cumulative distribution function","kisa":"CDF","tur":"kavram","es":["F(x)","cumulative probability function","birikimli olasılık dağılımı","cumulative probability","birikimli dağılım","aşılmama olasılığı"],"tanim":["Rassal bir değişkenin belirli bir sayısal değerden küçük veya ona eşit kalma olasılığını veren matematiksel fonksiyon.","Değerleri 0 ile 1 aralığında monoton artar; hidrolojide F(x) = P(X ≤ x) biçiminde aşılmama olasılığını gösterir.","Kitapta Gumbel dağılımına dayalı taşkın ve yağış tekerrür analizlerinde dönüş aralığı ile aşılmama olasılığı arasındaki bağıntıyı kurar."],"tanim_en":"The mathematical function giving the probability that a random variable will take a value less than or equal to a specified magnitude.","bag":{"kavram":["gumbel"],"soru":["S1","S2","S3","S4","S5","S6"],"hesap":[]}},{"id":"extreme-value-analysis","tr":"uç değer (ekstrem değer)","en":"extreme value analysis","kisa":"","tur":"kavram","es":["extreme value type I","ekstrem değer analizi","uç olay analizi","aşırı değer"],"tanim":["Hidrometeorolojik zaman serilerinde olağandışı şiddetteki yağış ve taşkın olaylarının büyüklük ile yinelenme sıklığını modelleyen istatistiksel analiz yöntemi.","Gözlenen yıllık maksimum serilere veya eşik aşım değerlerine Gumbel gibi teorik uç değer olasılık dağılımları uydurularak yürütülür.","Kitapta su yapılarının güvenli boyutlandırılmasında belirli dönüş aralıklarına karşılık gelen tasarım debisi ve yağışını belirlemek için kullanılır."],"tanim_en":"The statistical method modeling and estimating the recurrence probability of extreme hydrometeorological events like severe storms and floods.","bag":{"kavram":["gumbel"],"soru":[],"hesap":[]}},{"id":"partial-duration-series","tr":"kısmi süre serisi (eşik üstü seri)","en":"partial duration series","kisa":"PDS","tur":"kavram","es":["peaks-over-threshold series","POT","eşik aşım serisi","kısmi süre"],"tanim":["Belirlenen bir taban eşik seviyesini aşan tüm bağımsız olay büyüklüklerinin, yıl içindeki gerçekleşme sayısına bakılmaksızın dahil edildiği hidrolojik zaman serisi.","Bir yılda birden fazla taşkın yer alabileceği gibi kurak yıllarda hiçbir olay seriye girmeyebilir; 33 yıllık akımdan çoğu zaman 2–3 kat değer çıkar.","Kısa dönüş aralığında (T < 10 yıl) yıllık maksimum serisinden daha iyidir; T ≥ 10 yılda iki seri hemen hemen aynı dönüş aralığını verir."],"tanim_en":"A hydrologic data collection comprising all independent flood or rainfall events exceeding a selected threshold level regardless of their annual count.","bag":{"kavram":["taskin-frekansi","gumbel","idf"],"soru":["S27","S29"],"hesap":[]}},{"id":"euler-mascheroni-constant","tr":"Euler–Mascheroni sabiti (γ = 0,5772)","en":"Euler–Mascheroni constant","kisa":"γ","tur":"olcu","es":["Euler constant","Euler sabiti","0.5772","gamma","gamma sabiti","0,5772"],"tanim":["Harmonik seri ile doğal logaritma arasındaki farkın limit değeri olan matematiksel ve istatistiksel sabit.","Değeri yaklaşık 0,5772 olup boyutsuz bir büyüklüktür.","Gumbel I. tip uç değer dağılımında teorik ortalamayı konum ve ölçek parametrelerine bağlayan bağıntıda yer alır."],"tanim_en":"A mathematical constant defined as the limiting difference between the harmonic series and the natural logarithm, approximately equal to 0.5772.","bag":{"kavram":["gumbel"],"soru":[],"hesap":["gumbel"]}},{"id":"location-parameter","tr":"konum parametresi (Gumbel u)","en":"location parameter","kisa":"u","tur":"olcu","es":["Gumbel u","merkez parametresi","konum katsayısı","location parameter u","konum parametresi","u parametresi"],"tanim":["Olasılık dağılımının yatay eksendeki yerini ve mod değerini belirleyen dağılım parametresi.","Gumbel dağılımında incelenen hidrolojik değişkenle aynı birime sahiptir.","Kitapta yıllık maksimum taşkın ve yağış serilerinin uç değer analizinde dağılım merkezini tanımlamak için kullanılır."],"tanim_en":"A distribution parameter that determines the horizontal position and shift of a probability distribution along the abscissa.","bag":{"kavram":["gumbel"],"soru":[],"hesap":["gumbel"]}},{"id":"scale-parameter","tr":"ölçek parametresi (Gumbel α)","en":"scale parameter","kisa":"α","tur":"olcu","es":["Gumbel alpha","ölçek katsayısı","alfa","scale parameter alpha","ölçek parametresi","alfa parametresi"],"tanim":["Olasılık dağılımının yayılımını ve değişkenliğini kontrol eden istatistiksel parametre.","Gumbel dağılımında standart sapma ile doğrudan orantılıdır ve incelenen hidrolojik değişkenin biriminde.","Kitapta dönüş aralığına bağlı uç değer tahminlerinde frekans katsayısı ile birlikte çarpım faktörü olarak görev yapar."],"tanim_en":"A statistical parameter that determines the spread, width, and dispersion of a probability distribution.","bag":{"kavram":["gumbel"],"soru":[],"hesap":["gumbel"]}},{"id":"unit-cm-per-day","tr":"santimetre/gün","en":"centimetres per day","kisa":"cm/gün","tur":"birim","es":["cm/day","santimetre bölü gün","cm d⁻¹","cm/g"],"tanim":["Günde buharlaşan su katmanının düşey derinliğini gösteren hız birimi.","Hidrolojik hesaplarda 1 cm/gün değeri 10 mm/gün büyüklüğüne denk gelir.","Harbeck–Meyers kütle transferi bağıntısında göl buharlaşması derinliğinin doğrudan birimi olarak yer alır."],"tanim_en":"Hydrologic rate unit expressing depth of water evaporated or accumulated per day.","bag":{"kavram":["harbeck"],"soru":["S28"],"hesap":[]}},{"id":"unit-millibar","tr":"milibar","en":"millibar","kisa":"mb","tur":"birim","es":["mbar","basınç birimi mb","mb","hPa","basınç birimi"],"tanim":["Atmosfer basıncını ve buhar basıncını ifade etmekte kullanılan meteorolojik basınç birimi.","1 milibar tam olarak 1 hektopaskala ve 100 Paskala eşittir.","Kitapta kütle transferi buharlaşma formüllerinde ve atmosferdeki yağışa geçebilir su katman hesaplarında kullanılır."],"tanim_en":"A unit of atmospheric pressure equal to one hectopascal or one hundred pascals.","bag":{"kavram":["harbeck","pw"],"soru":["S8","S28"],"hesap":[]}},{"id":"eddy-diffusivity","tr":"türbülans difüzyon katsayısı (K kuramı)","en":"turbulent diffusion coefficient","kisa":"K_v","tur":"olcu","es":["eddy diffusivity","girdap difüzyon katsayısı","K katsayısı","türbülans katsayısı","eddy diffusion coefficient","K-teorisi"],"tanim":["Türbülanslı akışta korunan bir özelliğin girdaplar aracılığıyla difüzyonunu belirleyen değişim katsayısı.","M²/s birimiyle ifade edilir ve moleküler difüzyona kıyasla birkaç mertebe daha büyüktür.","Gradyan yaklaşımında düşey nem gradyanı ile çarpılarak türbülanslı buhar akısını Dalton ve Harbeck–Meyers kütle transferi formüllerine bağlar."],"tanim_en":"Exchange coefficient for the diffusion of a conservative property by eddies in a turbulent flow.","bag":{"kavram":["harbeck"],"soru":[],"hesap":["harbeck"]}},{"id":"sym-epsilon-mol-weight","tr":"molekül ağırlığı oranı (ε = 0,622)","en":"ratio of molecular weights of water vapour and dry air","kisa":"ε","tur":"olcu","es":["epsilon sabiti","0.622 oranı","0,622 oranı","moleküler ağırlık oranı","su buharı kuru hava molekül ağırlığı oranı"],"tanim":["Su buharının molekül ağırlığının kuru havanın molekül ağırlığına oranı.","Boyutsuz bir fiziksel sabit olup yaklaşık 0,622 değerini alır.","Kütle transferi buharlaşma bağıntısında buhar basıncından özgül nem hesabına geçişte çarpan olarak yer alır."],"tanim_en":"Dimensionless ratio of the molecular weight of water vapour to that of dry air, with an approximate value of 0,622.","bag":{"kavram":["harbeck"],"soru":["S12","S13"],"hesap":["optimum-olcer","harbeck"]}},{"id":"sym-specific-humidity","tr":"özgül nem","en":"specific humidity","kisa":"q","tur":"olcu","es":["özgül nem oranı","specific moisture content","q","specific humidity ratio"],"tanim":["Nemli havada bulunan su buharı kütlesinin, buharı içeren toplam nemli hava kütlesine oranıdır.","Birimi kg/kg olup atmosferde tipik değerleri 0,001 ile 0,02 kg/kg arasındadır; g/kg verildiğinde 1000 değerine bölünerek çevrilir.","Yağışa geçebilir su hesabında düşey kolon integrasyonunda ve yüzey buharlaşma akısı gradyanında temel nem değişkenidir."],"tanim_en":"Ratio of the mass of water vapour to the total mass of moist air containing the water vapour.","bag":{"kavram":["harbeck","pw"],"soru":["S8"],"hesap":["pw","harbeck"]}},{"id":"sym-u2-wind","tr":"2 m'de rüzgâr hızı","en":"wind speed at 2 m","kisa":"u₂","tur":"olcu","es":["2 metre rüzgârı","yüzey rüzgâr hızı","2m rüzgar sürati sembolü","u2","ölçüm yüksekliği","2 metre yüksekliği"],"tanim":["Su veya zemin yüzeyinden 2 metre standart referans yükseklikte ölçülen yatay rüzgâr hızı.","Birimi m/s olup anemometre ile ölçülür ve göl yüzeyinde türbülanslı hava karışımının büyüklüğünü temsil eder.","Kitapta Dalton ve Harbeck–Meyers kütle transferi yöntemlerinde buharlaşmayı artıran temel meteorolojik değişkendir."],"tanim_en":"Horizontal wind speed measured at the standard reference height of two metres above the surface.","bag":{"kavram":["harbeck"],"soru":["S28"],"hesap":["harbeck"]}},{"id":"tuning-constant","tr":"kütle transfer katsayısı","en":"mass-transfer coefficient (b)","kisa":"b","tur":"olcu","es":["ampirik Harbeck sabiti","empirical tuning constant","göl kütle transfer katsayısı","b katsayısı","Harbeck sabiti sembolü","tuning constant b"],"tanim":["Kütle transferi buharlaşma eşitliklerinde göl geometrisi ve atmosferik kararlılığı dikkate alan ampirik kalibrasyon katsayısı.","Harbeck–Meyers denkleminde birimi cm gün⁻¹ (m/s)⁻¹ mb⁻¹ olup göller için tipik değeri yaklaşık 0,0119 civarındadır.","Kitapta açık su yüzeyi buharlaşmasını rüzgâr hızı ve buhar basıncı farkından günlük derinlik cinsinden hesaplamak için kullanılır."],"tanim_en":"An empirical coefficient in mass-transfer evaporation equations calibrated to lake characteristics and measurement units.","bag":{"kavram":["harbeck"],"soru":[],"hesap":["harbeck"]}},{"id":"vapor-pressure","tr":"buhar basıncı","en":"vapour pressure","kisa":"e","tur":"olcu","es":["su buharı basıncı","aktüel buhar basıncı","vapor pressure","su buharı kısmi basıncı","water vapor pressure","Vapor pressure"],"tanim":["Atmosfer havası içindeki su buharı moleküllerinin uyguladığı kısmi gaz basıncı.","Birimi milibar (mb) veya hektopaskal (hPa) olup çiy noktası sıcaklığı ve psikrometre ölçümleriyle belirlenir.","Kitapta buharlaşmanın itici gücü olan buhar açığının ve yağışa geçebilir su miktarının belirlenmesinde temel büyüklüktür."],"tanim_en":"The partial pressure exerted by water vapour molecules in a volume of air.","bag":{"kavram":["harbeck","pw"],"soru":["S28"],"hesap":["harbeck","pw"]}},{"id":"vapor-pressure-gradient","tr":"buhar basıncı farkı (Δe = eₛ − e₂)","en":"vapour pressure deficit at the surface","kisa":"Δe","tur":"olcu","es":["buhar basıncı farkı","vapor pressure difference","buhar açığı","saturation deficit","VPD","buhar basıncı açığı"],"tanim":["Su yüzeyindeki doymuş buhar basıncı ile üstündeki havanın gerçek buhar basıncı arasındaki fark.","Birimi milibar (mb) olup su yüzeyi ile atmosfer arasındaki nem açığını gösterir.","Kitapta Dalton ve Harbeck–Meyers kütle transferi buharlaşma modellerinde buharlaşma hızını belirleyen ana termodinamik itici güçtür."],"tanim_en":"The difference between the saturation vapour pressure at the water surface and the actual vapour pressure of the air.","bag":{"kavram":["harbeck"],"soru":["S28"],"hesap":["harbeck"]}},{"id":"tetens-formula","tr":"Tetens formülü (doymuş buhar basıncı)","en":"Tetens formula","kisa":"eₛ(T)","tur":"yontem","es":["Tetens bağıntısı","Tetens denklemi","Magnus–Tetens formülü","Tetens equation"],"tanim":["Sıcaklığa bağlı olarak doymuş su buharı basıncını hesaplayan ampirik üstel bağıntı.","Sıcaklık °C alındığında sonucu milibar cinsinden verir; 0 °C için 6,112 mb ve 25 °C için 31,7 mb üretir.","Kütle transferi yönteminde su yüzeyi sıcaklığından doyma buhar basıncını bularak buharlaşma açığını hesaplamada kullanılır."],"tanim_en":"Empirical equation for computing saturation vapour pressure over water as a function of temperature.","bag":{"kavram":["harbeck"],"soru":[],"hesap":["harbeck"]}},{"id":"unit-m-per-yr","tr":"metre/yıl","en":"metres per year","kisa":"m/yıl","tur":"birim","es":["m/yr","metre bölü yıl","m/yıl","meters per year"],"tanim":["Hidrolojide yıllık su bütçesi bileşenlerinin su derinliği eşdeğerini gösteren akı birimi.","Mm/gün cinsinden değerlerin 365 ile çarpılıp 1000 değerine bölünmesiyle veya debinin yüzey alanına oranlanmasıyla elde edilir.","Hazne su bütçesinde farklı boyutlardaki yağış, buharlaşma ve akım terimlerini seviye değişimiyle uyumlu kılmak için kullanılır."],"tanim_en":"Unit of water depth equivalent over time, expressing annual rates of precipitation, evaporation, or reservoir water level change.","bag":{"kavram":["hazne","su-butcesi"],"soru":["S25"],"hesap":[]}},{"id":"bottom-outlet","tr":"dipsavak","en":"bottom outlet","kisa":"","tur":"cihaz","es":["dip savak","low-level outlet","dip tahliye","bottom sluice"],"tanim":["Baraj gövdesinin tabanına yakın bir kotta yer alan, kontrollü su tahliyesi ve hazne boşaltımı sağlayan hidrolik çıkış yapısı.","Vanalar veya kapaklarla kontrol edilir; dip sedimanının tahliyesi ve baraj mansabına çevre suyu bırakılması amacıyla kullanılır.","Hazne su bütçesinde kontrollü çıkış debisi Qout bileşenlerinden birini oluşturur."],"tanim_en":"Controlled opening near the base of a dam designed to discharge water, empty the reservoir, or flush sediment.","bag":{"kavram":["hazne"],"soru":[],"hesap":[]}},{"id":"dam","tr":"Baraj","en":"Dam","kisa":"","tur":"cihaz","es":["su bendi","baraj gövdesi","su yapısı"],"tanim":["Suyu depolamak veya su seviyesini yükseltmek amacıyla bir vadi boyunca inşa edilen engel.","Haznesinde depolanan su hacmini kontrol ederek mansaptaki taşkın riskini azaltır ve su temini sağlar.","Kitapta hazne su bütçesi hesabında depolama alanı ve su kotu değişiminin incelendiği hidrolik yapıdır."],"tanim_en":"Barrier constructed across a valley to store water or to raise the water level.","bag":{"kavram":["hazne"],"soru":["S7","S9","S24"],"hesap":["marshall-palmer"]}},{"id":"flood-control-dam","tr":"Taşkın kontrol barajı","en":"Flood control dam","kisa":"","tur":"cihaz","es":["taşkın önleme bendi","kuru baraj","taşkın önleme barajı","sel barajı"],"tanim":["Akarsu taşkın dalgalarını haznede geçici olarak depolayıp mansaba kontrollü hızda vermek amacıyla inşa edilen hidrolik yapı.","Mansap debisini yatak kapasitesi altında tutmak amacıyla su bütçesi denklemine göre savak ve dip savakla çıkış debisini sınırlar.","Kitapta yüzey akışını depolayarak mansaptaki taşkın piklerini sönümlemek üzere akarsu üstünde inşa edilen yapı olarak yer alır."],"tanim_en":"A barrier built across a stream to temporarily impound floodwater and attenuate downstream peak discharge.","bag":{"kavram":["hazne"],"soru":[],"hesap":[]}},{"id":"vertical-wall-assumption","tr":"düşey duvar kabulü (sabit yüzey alanı)","en":"vertical-wall (constant area) assumption","kisa":"","tur":"kavram","es":["sabit alan kabulü","düşey kenar yaklaşımı","constant area assumption","vertical wall hypothesis"],"tanim":["Hazne su bütçesi hesaplarında göl yüzey alanının su seviyesindeki değişimle değişmediğini varsayan basitleştirici kabul.","Hacim türevini dV/dt = A · dh/dt biçiminde doğrusal hale getirerek diferansiyel denklemin çözümünü kolaylaştırır.","Gerçek haznelerde vadi eğimi nedeniyle alan seviyeyle artsa da, küçük seviye salınımlarında hesap kolaylığı sağlayan geçerli bir yaklaşımdır."],"tanim_en":"Simplifying assumption in reservoir water balance taking lake surface area as constant regardless of water level fluctuation.","bag":{"kavram":["hazne"],"soru":[],"hesap":[]}},{"id":"inflow","tr":"giriş akımı","en":"inflow","kisa":"Qin","tur":"olcu","es":["giren debi","reservoir inflow","akarsu girişi","inflow hydrograph","kanal girişi","Inflow"],"tanim":["Bir göle, hazneye, akarsu yatağına ya da belirli bir kontrol hacmine dışarıdan giren su akışı.","Birimi saniyede metreküp (m³/s) ya da fit küp bölü saniye (cfs) olup, su bütçesinde yüzey alanına bölünerek derinlik cinsinden ifade edilir.","Hazne işletmesinde ve kanal taşkın ötelemesi modellerinde sisteme yukarı uçtan giren hidrograf girdisini oluşturur."],"tanim_en":"Flow of water into a receiving water body.","bag":{"kavram":["hazne","su-butcesi","clark"],"soru":["S25","S26","S35"],"hesap":["hazne","hazne-ay","clark","uzun-donem-et"]}},{"id":"outflow","tr":"çıkış akımı","en":"outflow","kisa":"Qout","tur":"olcu","es":["çıkan debi","reservoir outflow","tahliye debisi","outflow hydrograph","kanal çıkışı","hazne çıkışı"],"tanim":["Bir hidrosistemden, hazneden ya da akarsu kesitinden mansaba doğru çıkan su akımı.","Birimi m³/s ya da cfs cinsinden hacimsel debi olup akım gözlem istasyonlarıyla ya da savaklarla ölçülür.","Clark birim hidrografı ve kanal ötelemesi hesaplarında çıkış hidrografını belirlemede kullanılır."],"tanim_en":"Flow of water out of a hydrosystem, reservoir, or channel reach.","bag":{"kavram":["hazne","su-butcesi","clark"],"soru":["S25","S26"],"hesap":["hazne","hazne-ay","clark","uzun-donem-et"]}},{"id":"reservoir-release","tr":"bırakım (hazne çıkış debisi)","en":"reservoir release","kisa":"Q_out","tur":"olcu","es":["tahliye debisi","mansaba bırakılan su","release rate","hazneden bırakılan debi","salım","bırakım"],"tanim":["Bir hazneden, baraj gölünden veya kontrol yapısından mansap yatağına kapaklar, savak ya da türbin yoluyla planlı olarak boşaltılan su debisi.","Birimi m³/s veya cfs olup hazne seviyesinin sabit kalması durumunda giren debi ile yağış ve buharlaşma farkının alanla çarpımının toplamına eşittir.","Kitapta hazne su bütçesi modelinde Q_out sembolüyle yer alır ve kurak dönem işletmesi ile taşkın kontrolünde seviye yönetimini sağlar."],"tanim_en":"The discharge of water intentionally yielded or emptied from a reservoir into a downstream river channel.","bag":{"kavram":["hazne"],"soru":["S25","S26","S35","S42"],"hesap":["hazne","hazne-ay"]}},{"id":"reservoir-operation","tr":"hazne işletmesi","en":"reservoir operation","kisa":"","tur":"yontem","es":["baraj işletmesi","hazne yönetimi","reservoir management","baraj idaresi"],"tanim":["Baraj gölündeki su depolamasının taşkın koruma, su temini, sulama ve enerji amaçları doğrultusunda planlı yönetimi.","Giriş debileri, buharlaşma kayıpları ve seviye değişimleri takip edilerek çıkış yapılarından mansaba su bırakılmasıyla yürütülür.","Su dengesi denklemini kullanarak haznenin dolma süresini ve kurak dönem bırakım stratejilerini belirler."],"tanim_en":"Management of water storage and release in a dam reservoir to meet demands such as flood control, irrigation, and water supply.","bag":{"kavram":["hazne"],"soru":[],"hesap":["hazne","hazne-ay"]}},{"id":"stage-area-curve","tr":"seviye–alan (ve seviye–hacim) eğrisi","en":"stage–area (stage–storage) curve","kisa":"A(h)","tur":"yontem","es":["alan-seviye bağıntısı","stage-area relation","hazne alan eğrisi","göl alanı","su yüzeyi alanı","water surface area"],"tanim":["Bir haznede su seviyesi ile bu seviyeye karşılık gelen göl su yüzeyi alanı arasındaki topoğrafik ilişkiyi gösteren eğri.","Havza topoğrafik haritalarından planimetre veya CBS yardımıyla eşyükselti eğrilerinin alanları hesaplanarak oluşturulur.","Hazne su bütçesinde buharlaşma kaybını hesaplamak ve hacim değişimini su seviyesiyle ilişkilendirmek için A(h) fonksiyonu olarak kullanılır."],"tanim_en":"Curve defining the relationship between water surface elevation and reservoir surface area based on basin topography.","bag":{"kavram":["hazne"],"soru":["S27"],"hesap":["hazne","hazne-ay"]}},{"id":"basin-model","tr":"havza modeli","en":"basin model","kisa":"","tur":"cihaz","es":["HEC-HMS Basin Model","basin model components"],"tanim":["HEC-HMS hidrolojik modelleme sisteminde havzanın fiziksel yapısını, drenaj ağını ve hidrolojik elemanlarını temsil eden ana bileşen.","Alt havza, akarsu kesimi, kavşak, hazne ve çıkış noktası gibi elemanlar ile bunların akış bağlantılarını ve mekânsal parametrelerini içerir.","Kitapta simülasyonun mekânsal yapısını, yani nerede sorusunu kuran temel parça olarak tanımlanır."],"tanim_en":"The primary component in HEC-HMS that defines the physical watershed network and hydrologic elements such as subbasins, river reach segments, and junctions.","bag":{"kavram":["hec-hms"],"soru":["S37"],"hesap":[]}},{"id":"control-specifications","tr":"kontrol ayarları","en":"control specifications","kisa":"","tur":"cihaz","es":["HEC-HMS Control Specifications","kontrol özellikleri"],"tanim":["HEC-HMS benzetiminde simülasyonun zaman boyutunu, başlangıç ve bitiş tarihlerini ve hesaplama zaman adımını denetleyen modül.","Hesaplama zaman aralığı simülasyon gereksinimine göre saat ya da dk adımıyla tanımlanır.","Kitapta simülasyonun ne zaman ve hangi adımda çalışacağını belirleyen üç ana HEC-HMS bileşeninden biri olarak geçer."],"tanim_en":"A set of simulation run parameters in HEC-HMS defining the starting date, ending date, and time step.","bag":{"kavram":["hec-hms"],"soru":["S37"],"hesap":[]}},{"id":"hms-loss","tr":"Loss (HEC-HMS kayıp yöntemi)","en":"Loss method (HEC-HMS)","kisa":"Loss","tur":"cihaz","es":["kayıp adımı","kayıp yöntemi","HEC-HMS Loss","Loss seçeneği","kayıp bileşeni","HEC-HMS kayıp seçeneği (Loss)"],"tanim":["HEC-HMS modelinde toplam yağıştan tutulma, çukur depolaması ve sızma gibi kayıpları düşerek fazla yağışı (net yağışı) hesaplayan yöntem modülü.","Initial & Constant yönteminde başlangıç kaybı Iₐ ve sabit kayıp hızı f_c; SCS-CN yönteminde ise eğri numarası parametreleri kullanılır.","Kitapta yağışın ne kadarının akışa geçeceğini belirleyen alt havza hesap basamağı olarak yer alır."],"tanim_en":"The subbasin component in HEC-HMS that computes precipitation loss through infiltration and surface retention to yield excess rainfall.","bag":{"kavram":["hec-hms","ic-kayip","scs-cn"],"soru":["S34","S37"],"hesap":["ic-kayip","phi-deneme"]}},{"id":"junction","tr":"kavşak","en":"junction","kisa":"","tur":"cihaz","es":["birleşim noktası","river junction","HEC-HMS Junction"],"tanim":["İki veya daha fazla akarsu kolunun birleştiği nokta veya HEC-HMS havza modelinde yukarı akım hidrograflarını toplayan düğüm elemanı.","Mansap debisi, birleşen kolların zaman adımlarında gelen hidrograf ordinatlarının cebirsel toplamı alınarak hesaplanır.","Kitapta kollardan gelen ötelenmiş debilerin toplandığı ve mansaba aktarıldığı hidrograf birleşim yeri olarak geçer."],"tanim_en":"A node element in a river network or hydrological model where two or more upstream channel flows combine into a single downstream flow.","bag":{"kavram":["hec-hms"],"soru":["S37","S38","S39"],"hesap":[]}},{"id":"meteorologic-model","tr":"meteorolojik model","en":"meteorologic model","kisa":"","tur":"cihaz","es":["HEC-HMS Meteorologic Model","meteorologic model components"],"tanim":["HEC-HMS yazılımında yağış, buharlaşma ve kar erimesi gibi atmosferik girdileri hazırlayıp alt havzalara dağıtan bileşen.","İstasyon yağış ölçerleri, tasarım hiyetografları veya radar verilerini kullanarak yağışı alansal ve zamansal olarak dağıtır.","Kitapta simülasyona giren yağışın hacmini ve zamana yayılımını, yani ne kadar yağış sorusunu belirleyen temel yapı taşıdır."],"tanim_en":"The component in HEC-HMS that handles atmospheric boundary conditions by distributing precipitation and evapotranspiration data over subbasins.","bag":{"kavram":["hec-hms"],"soru":["S37"],"hesap":[]}},{"id":"mike-she","tr":"MIKE SHE (dağılı model)","en":"MIKE SHE","kisa":"MIKE SHE","tur":"cihaz","es":["MIKE SHE integrated hydrological modeling system"],"tanim":["Su döngüsünün yüzey akışı, doymamış bölge süzülmesi ve yeraltı suyu akımı gibi bileşenlerini ızgara hücrelerinde çözen tam dağılı ve fizik tabanlı hidrolojik modelleme sistemi.","Kısmi diferansiyel denklemlerle çalışır; yüksek mekânsal çözünürlüklü veri ve yoğun hesaplama gücü gerektirir.","Kitapta yarı-dağılı HEC-HMS modeline karşıt olarak tam dağılı (distributed) modeller sınıfında örnek verilir."],"tanim_en":"A physically based, distributed hydrological modeling system that simulates terrestrial components of the water cycle across grid cells.","bag":{"kavram":["hec-hms"],"soru":["S40"],"hesap":[]}},{"id":"reach","tr":"akarsu kesimi","en":"reach","kisa":"","tur":"cihaz","es":["kanal kesimi","river reach","routing reach"],"tanim":["Belirlenmiş iki en kesit arasında uzanan açık kanal veya akarsu yatağı uzunluğu.","Akış ötelemesinde giriş hidrografı mansaba aktarılırken gecikme süresi (Lag) veya Muskingum yöntemiyle sönümleme hesabı yapılır.","Kitapta HEC-HMS havza modelinde akımı yukarı uçtan aşağı uca ileten ve öteleyen kanal elemanı olarak kullanılır."],"tanim_en":"Length of open channel between two defined cross-sections.","bag":{"kavram":["hec-hms","oteleme"],"soru":["S37"],"hesap":["taban-akisi"]}},{"id":"subbasin","tr":"alt havza","en":"subbasin","kisa":"","tur":"cihaz","es":["alt drenaj alanı","subcatchment","subbasin element"],"tanim":["Ana drenaj havzası içinde belirli bir akarsu koluna veya düğüm noktasına su veren kendi su ayrım çizgisine sahip daha küçük havza birimi.","Sayısal yükseklik modellerinden D8 akış yönü ve akış birikimi algoritmalarıyla sınırları otomatik olarak çıkarılır.","Kitapta HEC-HMS yarı-dağılı modelinde kayıp (Loss), dönüştürme (Transform) ve taban akışı (Baseflow) hesap zincirinin koşturulduğu temel elemandır."],"tanim_en":"A subdivided drainage area within a larger watershed that drains to a specific tributary or confluence point.","bag":{"kavram":["hec-hms","gis-havza"],"soru":["S39","S40"],"hesap":["olcer-dagitim"]}},{"id":"topmodel","tr":"TOPMODEL","en":"TOPMODEL","kisa":"TOPMODEL","tur":"cihaz","es":["TOPMODEL hydrologic model","topoğrafik tabanlı model","topography-based hydrological model","topografik indeks modeli"],"tanim":["Havza topoğrafyasını ve değişken kaynak alanlarını kullanarak yüzey akışını simüle eden yarı dağılı, fizik tabanlı hidrolojik model.","Sayısal yükseklik modelinden türetilen topografik ıslaklık indeksi ln(a / tan β) dağılımıyla doymuş alanların mekânsal değişimini hesaplar.","Kitapta havzayı ızgara hücreleriyle temsil eden ve fiziksel süreçleri çözen dağılı modellere örnek olarak verilir."],"tanim_en":"A physically based semi-distributed hydrological model that simulates variable source area runoff through topographic wetness index distribution.","bag":{"kavram":["hec-hms","akis-mekanizma"],"soru":["S40"],"hesap":[]}},{"id":"tribs","tr":"tRIBS (dağılı model)","en":"tRIBS","kisa":"tRIBS","tur":"cihaz","es":["TIN-based Real-time Integrated Basin Simulator","tRIBS hydrologic model","tRIBS modeli","ağ tabanlı havza simülatörü"],"tanim":["Düzensiz üçgen ağ (TIN) geometrisi kullanarak havza topoğrafyasını ve hidrolojik süreçleri mekânsal olarak simüle eden tam dağılı hidrolojik model.","Yüzey akışı, sızma, yeraltı suyu dinamikleri ve enerji dengesini her üçgen eleman üzerinde çözerek gerçek zamanlı havza simülasyonu yapar.","Kitapta yüksek veri ve hesaplama gerektiren fizik tabanlı dağılı modellere örnek olarak verilir."],"tanim_en":"A fully distributed, physically based hydrological model that utilizes triangulated irregular networks to simulate catchment moisture and energy dynamics.","bag":{"kavram":["hec-hms"],"soru":[],"hesap":[]}},{"id":"black-box-model","tr":"kara kutu (ampirik) model","en":"black-box model","kisa":"","tur":"yontem","es":["sistem girdi-çıktı modeli","systems response approach","ampirik model","black-box hydrological model","karakutu modeli"],"tanim":["İçerideki fiziksel süreçlerin mekanizmasını dikkate almadan, yalnızca eşzamanlı girdi ve çıktı zaman serilerinin analizine dayanılarak geliştirilen model.","Yağış ile akış arasındaki ilişkiyi fiziksel yasalar yerine ampirik ve istatistiksel transfer fonksiyonlarıyla kurar.","Kitapta havza içi fiziksel dinamikleri çözmeyen toplu yaklaşımların temel mantığını tanımlamada geçer."],"tanim_en":"A model developed without consideration of internal physical process dynamics, based purely on the analysis of concurrent input and output time series.","bag":{"kavram":["hec-hms"],"soru":[],"hesap":["cfs-m3s"]}},{"id":"distributed-model","tr":"dağılı ve yarı dağılı model","en":"distributed / semi-distributed model","kisa":"","tur":"yontem","es":["dağılı parametreli model","grid-based distributed model","fizik tabanlı model","yarı dağılı parametreli model","semi-distributed hydrological model","yarı dağılı model"],"tanim":["Havzayı ızgara hücrelerine ya da alt havzalara bölerek yağış, toprak ve arazi örtüsü özelliklerinin mekânsal değişkenliğini hesaba katan hidrolojik model türü.","Yarı dağılı modeller alt havza ortalamalarını kullanırken tam dağılı modeller her hücrede fiziksel denklemleri ayrı ayrı çözer; yüksek veri ve hesaplama gücü gerektirir.","Kitapta TOPMODEL ve MIKE SHE gibi fizik tabanlı modeller ile CBS destekli D8 akış yönü analizleriyle birlikte ele alınır."],"tanim_en":"A hydrological model that accounts for the spatial variability of catchment characteristics and meteorological inputs by dividing the basin into discrete grid cells or subbasins.","bag":{"kavram":["hec-hms","gis-havza"],"soru":[],"hesap":["cfs-m3s","d8-egim"]}},{"id":"lumped-model","tr":"toplu model","en":"lumped model","kisa":"","tur":"yontem","es":["toplu parametreli model","kara kutu model","lumped parameter model","lumped parameters","a lumped, black-box model","karakutu model"],"tanim":["Havzayı mekânsal değişkenliği olmayan tek bir homojen bütün kabul eden ve hidrolojik süreçleri alansal ortalama parametrelerle temsil eden model.","Giriş olarak havza ortalaması yağış alır ve doğrudan havza çıkış noktasındaki debi hidrografını hesaplar; az veriyle hızlı sonuç verir.","Kitapta birim hidrograf, Clark yönlendirmesi ve HEC-HMS alt havza modelleme bileşenlerinde temel yaklaşım olarak anlatılır."],"tanim_en":"A hydrological model that treats an entire catchment as a single homogeneous unit, ignoring spatial variations in basin parameters and meteorological inputs.","bag":{"kavram":["hec-hms","birim-hidrograf","clark"],"soru":[],"hesap":["cfs-m3s","clark","birim-hidrograf"]}},{"id":"climate-change","tr":"İklim değişikliği","en":"Climate change","kisa":"","tur":"kavram","es":["iklimsel değişim","küresel iklim değişikliği","climate variability and change","global climate change"],"tanim":["İklim sisteminin iç dinamiklerindeki değişimler ya da doğal ve insan kaynaklı dış zorlamalar sonucu iklimin ortalama durumunda ve değişkenliğinde meydana gelen uzun süreli değişim.","Atmosferin ısınmasıyla birlikte havanın su buharı tutma kapasitesi Clausius-Clapeyron bağıntısına göre her 1 K ısınmada yaklaşık %7 artar ve hidrolojik döngüyü hızlandırır.","Kitapta küresel salınımlarla birlikte olası en büyük yağış (PMP) ve ekstrem taşkın kestirimlerini etkileyen temel etken olarak incelenir."],"tanim_en":"A long-term modification of climate conditions driven by internal system dynamics or external natural and anthropogenic forcing that alters hydrological extremes.","bag":{"kavram":["hershfield"],"soru":[],"hesap":[]}},{"id":"design-storm","tr":"Tasarım fırtınası","en":"Design storm","kisa":"","tur":"kavram","es":["proje fırtınası","tasarım yağışı","boyutlandırma yağışı","design rainfall"],"tanim":["Su yapılarının ve taşkın kontrol tesislerinin boyutlandırılmasına esas teşkil etmek üzere seçilen, gözlenmiş ya da sentetik yağmur fırtınası.","Belirli bir dönüş aralığına ve süreye karşılık gelen yağış derinliği ile zamansal dağılım hiyetografından oluşur; şiddet-süre-sıklık (IDF) bağıntılarıyla belirlenir.","Kitapta tasarım taşkını hidrografını türetmek için birim hidrograf ve yağış-akış modellerine girdi olarak verilir."],"tanim_en":"An observed or synthetic rainstorm of specified return period and duration used as the meteorological input for hydraulic structure sizing.","bag":{"kavram":["hershfield","idf"],"soru":[],"hesap":[]}},{"id":"probable-maximum-storm","tr":"olası en büyük fırtına","en":"Probable maximum storm","kisa":"PMS","tur":"kavram","es":["maksimum fırtına","PMP fırtınası","probable maximum precipitation storm","en büyük olası fırtına"],"tanim":["Belirli bir havzada, belirli bir süre ve mevsim için fiziksel olarak oluşabilecek en büyük yağışı (PMP) ve onun zaman içindeki dağılımını veren kuramsal fırtına.","Gözlenmiş büyük fırtınaların nem maksimizasyonu ve havzaya ötelenmesiyle ya da istatistik (Hershfield) yaklaşımla kurulur.","Yıkılması büyük can ve mal kaybına yol açacak barajların dolusavak tasarımında PMF'yi üretmek için kullanılır."],"tanim_en":"The theoretical greatest precipitation storm physically possible over a particular drainage basin for a given duration.","bag":{"kavram":["hershfield"],"soru":[],"hesap":[]}},{"id":"density-of-water","tr":"suyun yoğunluğu","en":"density of water","kisa":"ρ_w","tur":"olcu","es":["suyun özkütlesi","water density","saf su yoğunluğu","rho_w","su yoğunluğu"],"tanim":["Suyun birim hacminin kütlesi; standart hidrolojik hesaplarda saf su için 1000 kg/m³ olarak kabul edilir.","Hidrolojide 1 m² alana düşen 1 kg su kütlesinin tam olarak 1 mm derinliğe eşit olmasını sağlar.","Kitapta yağışa geçebilir su formülünde atmosferdeki buhar kütlesini sıvı su yüksekliğine çevirmede ve hidrostatik denge dönüşümlerinde paydada yer alır."],"tanim_en":"The mass per unit volume of liquid water, taken as 1000 kg/m³ in hydrological calculations to convert water mass to equivalent depth.","bag":{"kavram":["hershfield","pw","gizli-isi"],"soru":[],"hesap":["pw","hershfield","gizli-isi"]}},{"id":"population-standard-deviation","tr":"Hershfield standart sapmaları (σₙ ve σₙ₋₁)","en":"standard deviations of the full and truncated series (Hershfield)","kisa":"σₙ","tur":"olcu","es":["σn","tüm serinin standart sapması","Xm'siz serinin standart sapması","population standard deviation"],"tanim":["Hershfield yönteminde iki yayılım kullanılır: σₙ en büyük değer Xm dahil tüm serinin, σₙ₋₁ ise Xm çıkarıldıktan sonra kalan serinin standart sapmasıdır.","Alt simgeler seri uzunluğunu gösterir, bölen değildir; kitap hangi bölenin (kitle / örneklem) kullanıldığının yazılmasını ister (S22: 575 / 573 mm).","Km = (Xm − X̄ₙ₋₁) / σₙ₋₁ ile bulunur ve PMP = X̄ₙ + Km·σₙ'de σₙ ile çarpılır; kitap S22'de σₙ = 41,53 mm, σₙ₋₁ = 12,05 mm."],"tanim_en":"In the Hershfield method, σₙ is the standard deviation of the full annual-maximum series and σₙ₋₁ that of the series without its largest value.","bag":{"kavram":["hershfield"],"soru":["S22","S23"],"hesap":["optimum-olcer","hershfield"]}},{"id":"probable-maximum-flood","tr":"olası en büyük taşkın","en":"probable maximum flood","kisa":"PMF","tur":"olcu","es":["PMF","maksimum olası taşkın"],"tanim":["Bir havzada meteorolojik, hidrolojik ve topoğrafik etkenlerin tümü deterministik yaklaşımla birleştirildiğinde fiziksel olarak beklenebilecek en büyük taşkın debisi.","Birimi m³/s olup PMP tasarım fırtınasının havza yağış-akış modeliyle ötelenmesi sonucu elde edilir.","Kitapta büyük baraj dolusavakları ve nükleer tesisler gibi yıkılması felakete yol açacak yapılar için sıfır risk tasarım debisi olarak ele alınır."],"tanim_en":"Greatest flood that may be expected in a catchment taking into account all pertinent meteorological, hydrological and terrain factors in a deterministic manner.","bag":{"kavram":["hershfield","donus-risk"],"soru":[],"hesap":["risk","hershfield","gumbel"]}},{"id":"sample-standard-deviation","tr":"örneklem standart sapması (n − 1 bölenli)","en":"sample standard deviation","kisa":"σₙ₋₁","tur":"olcu","es":["σn-1","s","örnek standart sapması"],"tanim":["Sapmaların kareleri toplamı n − 1'e bölünerek bulunan standart sapma; örneklemden bütün kitlenin yayılımını yansız kestirir.","Kitapta optimum ölçer sayısında değişim katsayısı Cᵥ = 100·σₙ₋₁ / x̄ ile bu biçimde kullanılır (ör. σₙ₋₁ = 176,4, x̄ = 245 → Cᵥ = 72,0).","Dikkat: Hershfield bölümünde aynı σₙ₋₁ simgesi başka anlamdadır: en büyük değeri çıkarılmış serinin standart sapması (alt simge bölen değil, seri uzunluğu)."],"tanim_en":"Standard deviation computed with n − 1 in the denominator, an unbiased estimate of the population spread from a sample.","bag":{"kavram":["hershfield","gumbel","optimum-olcer"],"soru":["S22","S23"],"hesap":["optimum-olcer","hershfield","olcer-dagitim","gumbel"]}},{"id":"standard-deviation","tr":"standart sapma","en":"standard deviation","kisa":"σ","tur":"olcu","es":["sample standard deviation","population standard deviation","standart deviasyon","sigma","st. dev.","örnek standart sapması"],"tanim":["Bir veri kümesindeki değerlerin aritmetik ortalamadan ne kadar uzaklaştığını gösteren temel istatistiksel yayılım ölçüsü.","İncelenen hidrolojik değişkenle aynı birimi (mm, m³/s) taşır; varyansın karekökü alınarak bulunur.","Kitapta Gumbel taşkın frekans analizinde, Hershfield PMP bağıntısında ve yağış ölçer ağının optimum boyutlandırılmasında kullanılır."],"tanim_en":"Measure of the dispersion of a set of values from their arithmetic mean, calculated as the square root of variance.","bag":{"kavram":["hershfield","optimum-olcer","gumbel"],"soru":["S12","S13","S22","S23","S45"],"hesap":["optimum-olcer","hershfield","gumbel","olcer-dagitim"]}},{"id":"sym-km-hershfield","tr":"frekans katsayısı (Km, K_T)","en":"frequency factor (Hershfield Km, Gumbel K_T)","kisa":"Km","tur":"olcu","es":["K_m","uçluk katsayısı","maksimum frekans katsayısı","Km katsayısı","Hershfield factor Km","PMP frekans faktörü"],"tanim":["Uç değer analizinde belirli bir dönüş aralığına ya da en uç olaya karşılık gelen değerin ortalamadan kaç standart sapma uzaklıkta olduğunu belirten boyutsuz çarpan.","Boyutsuzdur; Hershfield Km hesabında serinin en büyük değeri ile kalan serinin ortalamasının farkı kalan serinin standart sapmasına bölünerek bulunur.","Kitapta PMP hesabında Hershfield Km katsayısı, T yıllık ekstrem taşkın ve yağış kestiriminde ise Gumbel K_T katsayısı olarak kullanılır."],"tanim_en":"Dimensionless factor defining the number of standard deviations by which a hydrological extreme value differs from the mean.","bag":{"kavram":["hershfield","gumbel"],"soru":["S22","S23","S45"],"hesap":["hershfield","gumbel"]}},{"id":"sym-mean-x-n","tr":"tüm serinin ortalaması","en":"mean of the full series","kisa":"X̄ₙ","tur":"olcu","es":["tüm seri ortalaması","X_bar_n","örneklem ortalaması","tüm veri ortalaması"],"tanim":["Bir hidrolojik gözlem serisindeki en büyük uç değer dahil olmak üzere n adet gözlemin tamamının aritmetik ortalaması.","İncelenen hidrolojik büyüklükle aynı birimi (mm) taşır; tüm gözlemlerin toplamının toplam gözlem sayısına bölünmesiyle hesaplanır.","Kitapta Hershfield PMP yönteminin ikinci adımında Km ve σₙ ile birlikte nihai PMP değerine ulaşmak için kullanılır."],"tanim_en":"Arithmetic mean of all n observations in a hydrological time series including the maximum observed event.","bag":{"kavram":["hershfield"],"soru":["S22","S23"],"hesap":["hershfield"]}},{"id":"sym-mean-x-n-minus-1","tr":"en büyük değer çıkarılmış serinin ortalaması","en":"mean of the series without the maximum","kisa":"X̄ₙ₋₁","tur":"olcu","es":["Xm'siz seri ortalaması","X_bar_n_minus_1","kısa seri","Xm'siz seri","sıradan yıllar","maksimumu çıkarılmış seri"],"tanim":["Bir hidrolojik zaman serisindeki en yüksek gözlem (Xm) dışarıda bırakılarak geriye kalan n − 1 adet sıradan gözlemin aritmetik ortalaması.","İncelenen hidrolojik değişkenle aynı birimi (mm) taşır; en büyük değerin ortalamayı yukarı çekmesini önleyerek sıradan yılların merkezini verir.","Kitapta Hershfield frekans katsayısının (Km) tarafsız ve abartısız kestirimi için pay kısmında referans olarak kullanılır."],"tanim_en":"Arithmetic mean of the remaining sample observations after removing the maximum observed value from the series.","bag":{"kavram":["hershfield"],"soru":["S15","S22","S23"],"hesap":["hershfield"]}},{"id":"sym-xm-hershfield","tr":"serinin en büyük değeri","en":"maximum observed value","kisa":"Xm","tur":"olcu","es":["seri maksimumu","X_m","en uç değer","örneklem maksimumu","en yüksek gözlem"],"tanim":["Bir hidrolojik gözlem serisinde ölçülen ve örneklem içerisindeki en yüksek büyüklüğe sahip olan tekil uç değer.","Ölçülen büyüklükle aynı birimi (mm, m³/s) taşır; serinin en uç olayını temsil eder.","Kitapta Hershfield PMP yönteminde frekans katsayısının (Km) hesabında başlangıç noktası ve aykırı uçluk göstergesi olarak kullanılır."],"tanim_en":"Highest single value observed within a hydrological sample series.","bag":{"kavram":["hershfield"],"soru":["S22","S23"],"hesap":["hershfield"]}},{"id":"urbanization-effect","tr":"kentleşme etkisi","en":"urbanization effect","kisa":"","tur":"surec","es":["kentleşme","urbanization","kentleşmenin hidrografa etkisi","urban runoff effect","urbanization impact","şehirleşme etkisi"],"tanim":["Doğal havza yüzeylerinin asfalt, beton ve binalarla kaplanması sonucu sızmanın azalıp yüzey akışının ve taşkın piklerinin belirgin biçimde artması süreci.","Toplanma süresini kısaltır, akış katsayısını ve eğri numarasını yükselterek hidrograf pikini erken zamana ve yüksek debiye taşır.","Kitapta havza tepkisini hızlandıran, kayıpları azaltan ve aynı yağışta beş kata varan akış artışına yol açan temel hidrolojik dönüşüm olarak incelenir."],"tanim_en":"Impact of watershed land development on hydrology through expanded impervious surface that accelerates runoff and elevates flood peaks.","bag":{"kavram":["hershfield","hidrograf","rasyonel"],"soru":["S24","S31","S41"],"hesap":[]}},{"id":"chow-frequency-factor-equation","tr":"Chow frekans denklemi","en":"Chow frequency factor equation","kisa":"","tur":"yontem","es":["genel frekans formülü","frequency formula","general frequency equation","Chow formülü","Chow frequency equation","Chow frekans bağıntısı"],"tanim":["Hidrolojik frekans analizinde T dönüş aralığına sahip bir ekstrem olayın büyüklüğünü örneklem ortalaması, standart sapma ve frekans katsayısı cinsinden ifade eden genel bağıntı.","X_T = X̄ + K·σ biçiminde yazılır; K katsayısı seçilen olasılık dağılım türüne ve dönüş aralığına göre türetilir.","Kitapta Gumbel dağılımına uyarlanmış biçimiyle taşkın frekans kestiriminde ve PMP hesabındaki Hershfield türetiminin temel çatısı olarak kullanılır."],"tanim_en":"General hydrological frequency equation expressing extreme quantiles as the mean plus the product of standard deviation and a frequency factor.","bag":{"kavram":["hershfield","gumbel"],"soru":["S45"],"hesap":["hershfield","gumbel"]}},{"id":"levee","tr":"set (taşkın seddesi) ve taşkın duvarı","en":"levee and flood wall","kisa":"","tur":"cihaz","es":["koruyucu set","dambur","taşkın seddesi","nehir seti","toprak set","Sedde"],"tanim":["Taşkın sularının yatak dışına taşarak komşu arazileri su altında bırakmasını önlemek amacıyla akarsu boyunca inşa edilen toprak set veya beton duvar.","Akarsu boy kesiti boyunca uzanan, belirli tekerrür debisine ait taşkın su kotuna serbest pay eklenerek boyutlandırılan koruma yapısı.","Kitapta akarsu taşkın kontrolünde suyun ana yatak içinde tutulmasını sağlayan boyuna koruma tesisi olarak yer alır."],"tanim_en":"An earthen embankment or concrete wall built along a watercourse to protect adjoining land from inundation.","bag":{"kavram":["hidrograf"],"soru":[],"hesap":[]}},{"id":"catchment-outlet","tr":"çıkış noktası","en":"catchment outlet","kisa":"","tur":"kavram","es":["havza çıkışı","basin outlet","outlet","mansap noktası","Havza çıkışı","Outlet"],"tanim":["Bir havzanın topladığı tüm yüzey ve yeraltı sularının havzayı terk ettiği en alçak mansap kesiti veya açıklığı.","Akım gözlem istasyonunun kurulduğu, debi ölçümlerinin ve hidrograf çizimlerinin referans alındığı kontrol noktası.","Kitapta sayısal yükseklik modelinden D8 akış yönü algoritmasıyla havza sınırlarının ayrılmasında ve su bütçesinin hesaplanmasında temel alınan uç noktadır."],"tanim_en":"The lowest point on a stream channel where water drained from a catchment leaves the basin.","bag":{"kavram":["hidrograf","gis-havza","su-butcesi"],"soru":["S30"],"hesap":[]}},{"id":"design-flood","tr":"Tasarım taşkını","en":"Design flood","kisa":"Qdes","tur":"kavram","es":["proje taşkını","hesap taşkını","boyutlandırma debisi","design discharge","tasarım taşkın debisi","Tasarım debisi"],"tanim":["Belirli bir su yapısının hidrolik boyutlandırılmasına ve güvenliğine temel alınan gözlenmiş veya sentetik taşkın debisi veya taşkın hidrografı.","Tasarım ömrü ve kabul edilen risk seviyesine göre dönüş aralığı veya olası en büyük taşkın (PMF) debisi olarak seçilir.","Kitapta baraj dolusavakları, köprüler ve taşkın kontrol bentlerinin boyutlandırılmasında rasyonel yöntem ve frekans analiziyle belirlenen debidir."],"tanim_en":"The flood hydrograph or peak discharge chosen as a basis for the hydraulic design of a structure.","bag":{"kavram":["hidrograf","hershfield","rasyonel"],"soru":[],"hesap":[]}},{"id":"flash-flood","tr":"Ani taşkın","en":"Flash flood","kisa":"","tur":"kavram","es":["ani sel","flash flooding","ani su baskını"],"tanim":["Şiddetli konvektif yağış veya baraj çökmesi sonucu kısa sürede oluşan, dik yükselme koluna ve çok yüksek tepe debisine sahip taşkın.","Yağışın başlamasından tepe debisine ulaşana kadar geçen süre genellikle birkaç saatten azdır; dar vadilerde ve kentleşmiş geçirimsiz alanlarda hızla gelişir.","Kitapta yüksek yağış şiddeti (i) ve küçük havza gecikmesiyle hızla doğrudan akışa dönüşen tehlikeli su baskını türü olarak ele alınır."],"tanim_en":"A sudden flood of short duration with a rapid flow surge and high peak discharge.","bag":{"kavram":["hidrograf","yagis-siddeti"],"soru":[],"hesap":[]}},{"id":"flood","tr":"taşkın","en":"flood","kisa":"","tur":"kavram","es":["su baskını","sel","taşkın olayı","inundation","Sel ve taşkın"],"tanim":["Bir akarsuyun veya su kütlesinin kabarıp normal yatak sınırlarını aşarak civardaki arazileri geçici olarak su altında bırakması.","Su seviyesi yüksekliği veya debi (m³/s) ile ölçülen, belirli dönüş aralığı (T) ve aşılma riskiyle değerlendirilen hidrolojik akış olayı.","Kitapta hidrograf analizi, doğrudan akış hacmi ve su yapılarının tasarım risk hesaplarında odak noktasıdır."],"tanim_en":"A temporary rise in water level resulting in inundation of land areas not normally submerged.","bag":{"kavram":["hidrograf","su-butcesi","donus-risk"],"soru":["S24"],"hesap":[]}},{"id":"flood-management","tr":"Taşkın yönetimi","en":"Flood management","kisa":"","tur":"kavram","es":["taşkın kontrolü","flood control","taşkın koruma","taşkın önleme"],"tanim":["Taşkın kaynaklı can ve mal kayıplarını en aza indirmek için suyun tutulması, ötelenmesi, yönlendirilmesi ve havza planlamasını birleştiren bütüncül süreç.","Taşkın kontrol barajları, seddeler ve derivasyon kanalları gibi yapısal tedbirler ile erken uyarı ve taşkın ovası zonlaması gibi yapısal olmayan tedbirleri içerir.","Kitapta akım hidrograflarının ötelenmesi, haznelerde depolama ve mansaptaki pik debinin düşürülmesi amacıyla incelenir."],"tanim_en":"The integrated application of structural and non-structural measures to mitigate flood risk and downstream inundation.","bag":{"kavram":["hidrograf"],"soru":[],"hesap":[]}},{"id":"hyetograph","tr":"hiyetograf","en":"hyetograph","kisa":"","tur":"kavram","es":["yağış şiddeti grafiği","storm hyetograph","excess rainfall hyetograph","yağış hiyetografı","hiyetogram","hiyetograf (yağış şiddeti grafiği)"],"tanim":["Yağış şiddetinin veya zaman aralıklarındaki yağış miktarının zamana göre değişimini gösteren sütun grafiği ya da zamansal dağılım grafiği.","Düşey eksende yağış şiddeti (mm/h) veya derinliği (mm), yatay eksende ise ayrık zaman aralıkları (saat, dk) bulunur.","Kitapta hidrografın üzerine çizilen girdi grafiğidir; φ-indeksiyle kayıplar düşülerek net yağış hiyetografı elde edilir ve akış evrişiminde kullanılır."],"tanim_en":"A graphical display of rainfall intensity or precipitation depth plotted over time.","bag":{"kavram":["hidrograf","phi-indeksi","yagis-siddeti"],"soru":[],"hesap":[]}},{"id":"recession-limb","tr":"Çekilme kolu","en":"Recession limb","kisa":"","tur":"kavram","es":["hidrograf çekilme eğrisi","düşüş kolu","alçalma kolu","falling limb","recession curve","taban akışı kuyruğu"],"tanim":["Akım hidrografında tepe debisinden sonra debinin azalarak taban akışına doğru geri çekildiği iniş bölümü.","Havzada yüzey depolaması, ara akış ve yeraltı suyunun boşalmasını yansıtır; yarı logaritmik çizimde eğim kırılmasıyla taban akışına geçişi gösterir.","Kitapta hidrografın tepe noktasından sonra gelen üçüncü evresidir; doğrudan akışın sona erdiği noktayı belirlemede temel alınır."],"tanim_en":"The descending portion of a hydrograph from peak discharge down to baseflow.","bag":{"kavram":["hidrograf","taban-akisi"],"soru":["S30"],"hesap":[]}},{"id":"rising-limb","tr":"yükselme kolu","en":"rising limb","kisa":"","tur":"kavram","es":["yükselen kol","the rising limb of the hydrograph","tırmanma kolu"],"tanim":["Bir akım hidrografında doğrudan akışın havza çıkışına ulaşmasıyla debinin taban akışından tepe debisine doğru yükseldiği tırmanma bölümü.","Eğimi fırtınanın şiddetine, yağışın havzadaki yayılımına ve havzanın geçirimsiz alan oranına bağlı olarak belirlenir.","Kitapta hidrografın ilk kısmı olarak geçer; yağış başlangıcından havzanın en çok alanının eşzamanlı akış ürettiği tepe debisine kadar sürer."],"tanim_en":"The ascending portion of a hydrograph from initial runoff up to the peak discharge.","bag":{"kavram":["hidrograf"],"soru":["S30"],"hesap":[]}},{"id":"lag-time","tr":"gecikme süresi","en":"lag time","kisa":"t_L","tur":"olcu","es":["basin lag","havza gecikmesi","gecikme","basin lag symbol","havza gecikmesi sembolü","yağış merkezi"],"tanim":["Net yağışın ağırlık merkezi ile akım hidrografının tepe debisi arasında geçen süre.","Saat (h) veya dk cinsinden ifade edilir; havza büyüklüğü, ana dere eğimi ve yüzey pürüzlülüğüne bağlı olarak değişir.","Kitapta havzanın akış tepki süresini ve kanal ötelemesinde taşkın dalgasının varış gecikmesini niteleyen temel büyüklüktür."],"tanim_en":"The time interval between the centroid of net precipitation and the peak runoff rate.","bag":{"kavram":["hidrograf","oteleme"],"soru":["S30","S32","S37","S38"],"hesap":["hidrograf","clark","birim-hidrograf"]}},{"id":"flood-forecasting","tr":"taşkın tahmini ve erken uyarı","en":"flood forecasting","kisa":"","tur":"yontem","es":["taşkın öngörüsü","flood prediction","taşkın tahmini","taşkın kestirimi"],"tanim":["Yağış veya kar erimesi sonucunda akarsuyun belirli bir kesitinde oluşacak su seviyesi, debi, doruk anı ve taşkın süresinin önceden kestirilmesi.","Hidrometeorolojik gözlemler, radar verileri ve havza modelleri birleştirilerek erken uyarı sistemleri işletilir.","Can ve mal kayıplarını önlemek amacıyla acil eylem planlarının yürürlüğe konmasında temel alınır."],"tanim_en":"Prediction of streamflow stage, discharge, arrival time, and duration resulting from precipitation or snowmelt.","bag":{"kavram":["hidrograf","hec-hms"],"soru":[],"hesap":["cfs-m3s","hidrograf","clark","birim-hidrograf"]}},{"id":"unit-cm","tr":"santimetre","en":"centimetre","kisa":"cm","tur":"birim","es":["centimeter","cm derinlik","santimetre derinlik","Centimeter","cm","santim"],"tanim":["Metrenin yüzde birine eşit olan metrik uzunluk birimi (0,01 m).","Hidrolojide yağış derinliği, buharlaşma tavası ölçümleri ve kar örtüsü kalınlığında kullanılır.","Kitapta yağış şiddeti sınıflamasında eşik değer birimi (cm/h) ve Horton derinlik–alan bağıntısında merkez yağış derinliği birimi olarak yer alır."],"tanim_en":"Metric unit of length equal to one hundredth of a metre, applied to rainfall depth and snow depth.","bag":{"kavram":["horton-da","zarf","tava"],"soru":["S9","S12","S19","S20","S21","S28"],"hesap":["yagis-siddeti","zarf"]}},{"id":"storm-centre","tr":"fırtına merkezi","en":"storm centre","kisa":"","tur":"kavram","es":["at the storm centre","fırtına göbeği","yağış merkezi","center of the rainstorm","Storm center","fırtına odağı"],"tanim":["Bir fırtına veya yağış sisteminde en yüksek yağış derinliğinin veya şiddetinin gözlendiği çekirdek bölge.","İzohiyet haritalarında en içteki kapalı eş yağış eğrisinin çevrelediği en yüksek değer noktasını temsil eder.","Horton derinlik–alan bağıntısında merkez kabul edilir ve bu noktadan uzaklaşıp alan büyüdükçe ortalama yağış derinliği üstel olarak azalır."],"tanim_en":"Core area of a precipitation storm characterized by the highest rainfall intensity and depth.","bag":{"kavram":["horton-da"],"soru":["S19","S20"],"hesap":["horton-da"]}},{"id":"areal-reduction-factor","tr":"alansal azaltma katsayısı","en":"areal reduction factor","kisa":"ARF","tur":"olcu","es":["ARF","alan azaltma katsayısı","alan azaltma","areal reduction","nokta değerinin alana indirgenmesi","point-to-area reduction"],"tanim":["Belirli bir süre ve dönüş aralığı için ortalama alansal yağışın, aynı alandaki ortalama nokta yağışına oranı (ARF ≤ 1).","Boyutsuz bir katsayı olup havza alanı büyüdükçe veya yağış süresi kısaldıkça değeri 1'den aşağı doğru düşer.","Nokta yağış gözlemlerini veya PMP değerlerini büyük havzalara uyarlamak için derinlik–alan–süre (DAD) analizlerinde kullanılır."],"tanim_en":"Ratio of mean areal rainfall depth to mean point rainfall depth for a given duration and return period over a watershed.","bag":{"kavram":["horton-da"],"soru":[],"hesap":["horton-da"]}},{"id":"storm-central-rainfall","tr":"Fırtına merkez yağışı","en":"Storm central rainfall","kisa":"Pm","tur":"olcu","es":["merkezdeki en yüksek yağış","highest rainfall at center","fırtına merkezi yağışı","P_m","merkez azami yağışı","merkez yağışı sembolü"],"tanim":["Bir fırtınanın merkez çekirdeğinde ölçülen veya alan sıfıra yaklaşırken ulaşılan en yüksek yağış derinliği (Pm).","Birimi genellikle cm veya mm cinsinden olup izohiyet haritasındaki en tepe değere karşılık gelir.","Horton derinlik–alan bağıntısında başlangıç katsayısıdır; log-log doğrusallaştırma adımlarında P = Pm değeri ln 0 tanımsızlığı nedeniyle doğrudan kullanılamaz."],"tanim_en":"Maximum rainfall depth measured at the center of a storm, representing the theoretical limit as area tends to zero.","bag":{"kavram":["horton-da"],"soru":["S19","S20"],"hesap":["horton-da"]}},{"id":"sym-k-horton","tr":"Horton derinlik–alan sabiti","en":"Horton depth–area constant","kisa":"k","tur":"olcu","es":["Horton k sabiti","azalma katsayısı","Horton k katsayısı","Horton sabiti k","derinlik-alan katsayısı k"],"tanim":["Horton derinlik–alan bağıntısında alansal ortalama yağışın merkezden uzaklaştıkça azalma hızını belirleyen ölçek katsayısı (k).","Birimi alan üssüne bağlı olarak km⁻²ⁿ cinsinden tanımlanır; tipik değer aralığı 10⁻⁴ ile 10⁻² arasında kalır.","Log-log ekseninde doğrusallaştırılan denklemde y-kesişiminden (ln k) elde edilir."],"tanim_en":"Empirical scale parameter in the Horton depth–area relation controlling the rate of rainfall depth reduction with increasing area.","bag":{"kavram":["horton-da"],"soru":[],"hesap":["horton-da"]}},{"id":"sym-n-horton","tr":"Horton derinlik–alan üssü","en":"Horton depth–area exponent","kisa":"n","tur":"olcu","es":["Horton n üssü","alan üssü","Horton üssü n","alan üs katsayısı","exponent n"],"tanim":["Horton derinlik–alan bağıntısında havza alanının kuvvetini temsil eden boyutsuz üs parametresi (n).","Değeri 0 ile 1 arasında bulunur; pratikte fırtınalar için tipik olarak 0,5 ile 0,8 aralığında değişir.","Çift logaritmik doğrusallaştırmada regresyon doğrusunun eğimini doğrudan belirler."],"tanim_en":"Dimensionless area exponent in the Horton depth–area equation representing the slope of the linearized log-log fit.","bag":{"kavram":["horton-da"],"soru":[],"hesap":["horton-da"]}},{"id":"depth-area-duration","tr":"derinlik–alan–süre","en":"depth–area–duration","kisa":"DAD","tur":"yontem","es":["DAD analizi","DAD curves","derinlik-alan-süre analizi","DAD","derinlik alan süre eğrileri"],"tanim":["Belirli bir fırtınada farklı süreler boyunca çeşitli büyüklükteki alanlara düşen en yüksek ortalama yağış derinliklerini inceleyen analiz yöntemi (DAD).","İzohiyet haritaları ve yağış kütle eğrilerinden elde edilen verilerle derinlik–alan–süre eğrileri ailesi çizilerek türetilir.","Baraj dolusavaklarının ve büyük su yapılarının taşkın tasarımında olası en büyük yağış (PMP) hesaplamalarında temel oluşturur."],"tanim_en":"Hydrologic procedure relating maximum precipitation depth to catchment area across various storm durations.","bag":{"kavram":["horton-da"],"soru":[],"hesap":["horton-da"]}},{"id":"constant-loss-rate","tr":"sabit kayıp hızı","en":"constant loss rate","kisa":"fc","tur":"olcu","es":["sabit sızma kaybı","nihai sızma hızı","constant rate","sabit kayıp oranı","sabit sızma hızı","a constant rate of 0.1 in/h"],"tanim":["Başlangıç kaybı karşılandıktan sonra yağış süresince toprağa sızarak kaybolan sabit hızlı su kaybı parametresi (fc).","Birimi mm/h ya da in/h cinsinden ifade edilir; fiziksel olarak toprağın doygun hidrolik iletkenliğine karşılık gelir.","HEC-HMS Initial & Constant modelinde başlangıç kaybı (Ia) aşıldıktan sonraki her zaman adımında yağıştan düşülerek fazla yağış elde edilir."],"tanim_en":"Constant rate of water infiltration into the soil profile after satisfying initial abstraction.","bag":{"kavram":["ic-kayip","phi-indeksi","akis-mekanizma"],"soru":["S34","S38","S42"],"hesap":["ic-kayip","phi-deneme"]}},{"id":"excess-rainfall","tr":"fazla yağış","en":"excess rainfall","kisa":"Pe","tur":"olcu","es":["etkili yağış","rainfall excess","effective rainfall","excess rainfall hyetograph","etkin yağış","fazla yağış (etkili yağış)"],"tanim":["Toplam yağıştan tutulma, çukur depolaması ve sızma kayıpları düşüldükten sonra doğrudan yüzey akışına katılan yağış bölümü.","Birimi mm olup toplam yağış ile hidrolojik kayıpların farkı alınarak hesaplanır.","Havza modellemesinde birim hidrograf yöntemiyle birleştirilerek doğrudan akış hidrografının elde edilmesinde temel girdi olarak yer alır."],"tanim_en":"The part of rainfall which contributes directly to surface runoff.","bag":{"kavram":["ic-kayip","clark","birim-hidrograf"],"soru":["S34","S40","S43"],"hesap":["ic-kayip","phi-deneme","birim-hidrograf","clark"]}},{"id":"initial-abstraction","tr":"SCS başlangıç kaybı (Ia = 0,2 S)","en":"initial abstraction (SCS)","kisa":"Ia","tur":"olcu","es":["başlangıç tutulması","ilk kayıp derinliği","initial abstraction ratio","Ia = 0.2 S","ilk kayıp","başlangıç kaybı (Ia, SCS)"],"tanim":["Yağış başladığında yüzey akışı meydana gelmeden önce bitkilerde tutulan, çukurlarda biriken ve toprağa ilk sızan su payıdır.","SCS yönteminde potansiyel tutma parametresine ampirik olarak bağlanır ve Ia = 0,2 S bağıntısıyla hesaplanır.","Birikimli yağış miktarı Ia değerini aşmadığı sürece havzada net yüzey akışı oluşmaz."],"tanim_en":"Total amount of precipitation intercepted, retained in depression storage, and infiltrated prior to the onset of surface runoff.","bag":{"kavram":["ic-kayip","scs-cn"],"soru":["S34","S38","S41"],"hesap":["ic-kayip","scs-cn"]}},{"id":"initial-loss","tr":"Initial & Constant başlangıç kaybı","en":"initial loss","kisa":"Ia","tur":"olcu","es":["initial abstraction","ilk kayıp","Ia","başlangıç tutması"],"tanim":["Fırtınanın başında bitki tutması, çukur depolaması ve ilk zemin ıslanması ile tutulan ve yüzey akışına geçmeyen yağış miktarı.","Birimi mm ya da inç olup bu eşik dolana kadar havzada yüzey akışı oluşmaz.","Initial & Constant kayıp yönteminde fazla yağış hesabının başlaması için aşılması gereken ilk depolama eşiği olarak tanımlanır."],"tanim_en":"The amount of precipitation at the beginning of a storm before surface runoff begins, absorbed by interception and surface depression storage.","bag":{"kavram":["ic-kayip"],"soru":["S34","S37","S38","S41"],"hesap":["ic-kayip","scs-cn"]}},{"id":"culvert","tr":"menfez","en":"culvert","kisa":"","tur":"cihaz","es":["culvert design","menfez hidroliği","yol geçiş menfezi","drenaj menfezi","yol menfezi"],"tanim":["Karayolu, demiryolu ya da kanal gibi bir yapının altından yüzey drenaj suyunun geçişini sağlayan kapalı su iletim yapısı.","Genellikle 10–25 yıllık dönüş aralığına sahip taşkın debilerine göre boyutlandırılır.","Küçük havzalarda rasyonel yöntemle hesaplanan pik debinin güvenle tahliye edilmesinde kullanılır."],"tanim_en":"A closed conduit for the free passage of surface drainage water under an embankment or road.","bag":{"kavram":["idf","donus-risk","rasyonel"],"soru":["S18"],"hesap":[]}},{"id":"annual-maximum-series","tr":"yıllık maksimum serisi","en":"annual maximum series","kisa":"AMS","tur":"kavram","es":["yıllık 1 günlük maksimum serisi","annual maximum 1-day rainfall","yıllık en büyükler serisi","yıllık uç değer serisi","annual maxima","annual maximum daily rainfall"],"tanim":["Bir gözlem istasyonunda her takvim yılı içinde gözlenen en büyük tekil değerlerden derlenen veri dizisi.","Taşkın için her yılın en büyük günlük ortalama debisi alınır: n yıl = n değer; günlük ortalama sivri tepeyi yumuşatır.","Taşkın frekans analizinde (sırala → P = m/(n + 1)), Gumbel ve Hershfield yöntemlerinde girdi seridir."],"tanim_en":"A hydrological sequence formed by taking the single largest observed value from each calendar year.","bag":{"kavram":["taskin-frekansi","idf","hershfield","gumbel"],"soru":["S45"],"hesap":[]}},{"id":"rainfall-duration","tr":"süre","en":"duration","kisa":"t","tur":"olcu","es":["yağış süresi","storm duration","design duration","fırtına süresi","Yağış süresi","Rainfall duration"],"tanim":["Belirli bir noktada veya havzada yağışın kesintisiz sürdüğü ya da tasarım fırtınasının geçerli olduğu zaman aralığı.","Birimi dk, saat veya gün olup süre uzadıkça beklenen ortalama yağış şiddeti azalır.","IDF eğrilerinde şiddetin belirlenmesinde ve rasyonel yöntemde toplanma süresine eşit tasarım yağışının seçiminde temel değişkendir."],"tanim_en":"The period of time during which precipitation occurs at a given point or area.","bag":{"kavram":["idf","zarf","yagis-siddeti"],"soru":["S3","S4","S8","S9","S15","S16"],"hesap":["kalis-suresi","akis-derinlik","yagis-siddeti","idf-ab"]}},{"id":"sym-a-idf","tr":"IDF ölçek sabiti","en":"IDF scale constant","kisa":"a","tur":"olcu","es":["kısa süre IDF sabiti a","IDF constant a","yerel parametre a","IDF parametresi a","şiddet katsayısı a"],"tanim":["Kısa süreli IDF bağıntısında yağış şiddeti düzeyini ve eğrinin düşey konumunu belirleyen ampirik ölçek parametresi.","Birimi mm·dk/h olup dönüş aralığı T büyüdükçe değeri artar ve eğriyi yukarı öteler.","Geçmiş yağış gözlemlerine hiperbolik denklem uydurularak elde edilen yerel bir katsayıdır."],"tanim_en":"An empirical scale parameter in short-duration rainfall intensity equations that elevates the curve as return period lengthens.","bag":{"kavram":["idf"],"soru":[],"hesap":["idf-ab","idf-cn","rasyonel-idf"]}},{"id":"sym-b-idf","tr":"IDF süre öteleme sabiti","en":"IDF duration-shift constant","kisa":"b","tur":"olcu","es":["kısa süre IDF sabiti b","IDF constant b","yerel parametre b","IDF parametresi b","süre katsayısı b"],"tanim":["Kısa süreli IDF bağıntısında paydada süreye eklenen ve çok küçük sürelerde şiddetin sonsuza gitmesini önleyen ampirik sabit.","Birimi süre birimiyle aynı (genellikle dk) olup yerel fırtına özelliklerine göre türetilir.","Küçük havzalarda toplanma süresi çok kısa olduğunda fizik dışı yüksek şiddetlerin hesaplanmasını engeller."],"tanim_en":"An empirical duration-shift parameter added to storm duration in rainfall intensity formulas to avoid infinite intensity at zero duration.","bag":{"kavram":["idf"],"soru":[],"hesap":["idf-ab","idf-cn","rasyonel-idf"]}},{"id":"time-of-concentration","tr":"toplanma süresi","en":"time of concentration","kisa":"Tc","tur":"olcu","es":["havza toplanma süresi","concentration time","konsantrasyon süresi","basin Tc","t_c","toplanma süresi sembolü"],"tanim":["Havzanın hidrolik yönden en uzak noktasından çıkan yüzey akışının havza çıkış noktasına ulaşması için gereken süre.","Birimi dk veya saat olup havza uzunluğu, eğimi ve pürüzlülüğüne göre hesaplanır.","Rasyonel yöntemde pik debiye yol açan kritik tasarım yağış süresini tanımlar ve Clark birim hidrografında öteleme parametresi olarak kullanılır."],"tanim_en":"The period of time required for storm runoff to flow to the outlet from the point of a drainage basin having the longest travel time.","bag":{"kavram":["idf","rasyonel","clark"],"soru":["S31","S32","S38"],"hesap":["rasyonel-idf","idf-ab","idf-cn","rasyonel"]}},{"id":"log-log-linearization","tr":"log–log doğrusallaştırma","en":"log–log linearization","kisa":"","tur":"yontem","es":["çift logaritmik dönüşüm","logarithmic transformation","çift logaritmik Horton biçimi","ln ln doğrusal biçim","Horton doğrusal biçimi","Horton linearized form"],"tanim":["Değişkenler arasındaki üslü veya kuvvet bağıntılarını iki eksenin logaritmasını alarak doğrusal denkleme dönüştürme yöntemi.","Dönüşüm sonrası en küçük kareler regresyonu uygulanarak katsayılar ve üs parametreleri kestirilir.","Hidrolojide Horton derinlik–alan bağıntısı ve dünya yağış zarf eğrisi parametrelerinin bulunmasında kullanılır."],"tanim_en":"A mathematical method that converts power-law relationships into linear form by taking logarithms of both variables.","bag":{"kavram":["idf","horton-da","zarf"],"soru":[],"hesap":["idf-ab","idf-cn","horton-da","zarf"]}},{"id":"power-law-idf","tr":"üslü IDF bağıntısı (i = C·t⁻ⁿ)","en":"power-law IDF relation","kisa":"C, n","tur":"yontem","es":["uzun süre IDF bağıntısı","i = C/t^n","uzun süre IDF sabiti C","IDF constant C","IDF sabiti C","ampirik katsayı C"],"tanim":["Yağış şiddetinin süre arttıkça bir kuvvet yasasına göre azaldığını ifade eden ve orta ile uzun süreli fırtınalarda uygulanan IDF denklemi.","I = C·t⁻ⁿ biçiminde gösterilir; C dönüş aralığına bağlı ölçek parametresi, n ise havza yapısını yansıtan üs katsayısıdır.","Süre birimi genellikle saat olarak alınır ve logaritmik koordinatlarda doğrusal eğilim gösteren tasarım fırtınalarında kullanılır."],"tanim_en":"A rainfall intensity equation expressing intensity as a power-law function of storm duration.","bag":{"kavram":["idf","horton-da"],"soru":["S17"],"hesap":["idf-ab","idf-cn","horton-da","rasyonel-idf"]}},{"id":"short-duration-idf","tr":"kesirli IDF bağıntısı (i = a/(t + b))","en":"Talbot-type IDF relation","kisa":"a, b","tur":"yontem","es":["hiperbolik IDF formülü","i = a/(t + b)","kısa süre IDF bağıntısı","iki parametreli IDF","IDF rasyonel biçimi","IDF rational formulation"],"tanim":["Kısa süreli fırtınalarda yağış şiddeti ile süre arasındaki ilişkiyi tanımlayan hiperbolik kesirli bağıntı.","Genellikle 5–120 dk arasındaki süreler için a ve b yerel sabitleriyle i = a / (t + b) biçiminde hesaplanır.","Kitapta kısa süreli fırtınalar için IDF eğrilerini türetmede ve tasarım yağışı şiddetini belirlemede kullanılır."],"tanim_en":"An empirical hyperbolic equation relating rainfall intensity to storm duration for short time intervals.","bag":{"kavram":["idf"],"soru":["S16","S32"],"hesap":["idf-ab","idf-cn","rasyonel-idf"]}},{"id":"gis-software","tr":"CBS (Coğrafi Bilgi Sistemi)","en":"GIS (geographic information system)","kisa":"GIS","tur":"cihaz","es":["CBS","GIS","Coğrafi Bilgi Sistemleri","coğrafi bilgi sistemi yazılımı"],"tanim":["Coğrafi ve konumsal verileri toplama, depolama, işleme, analiz etme ve haritalama olanağı sunan bilgisayar tabanlı sistem.","Sayısal yükseklik modelleri üzerinden akış yönü, akış birikimi ve eğim gibi topoğrafik katmanları üretir.","Kitapta havza sınırlarının belirlenmesi, alt havzaların ayrılması ve izohiyet şerit alanlarının ölçülmesinde kullanılır."],"tanim_en":"A computer-based framework that provides the ability to capture, store, analyze, and display geographically referenced information.","bag":{"kavram":["izohiyet","gis-havza"],"soru":["S39"],"hesap":[]}},{"id":"planimeter","tr":"Planimetre","en":"Planimeter","kisa":"","tur":"cihaz","es":["alan ölçer","mekanik planimetre","dijital planimetre","polar planimetre"],"tanim":["İki boyutlu düzlemde sınırları çizilmiş düzensiz bir alanın çevresi izlenerek alanını mekanik ya da elektronik olarak ölçen alet.","Harita ölçeğine göre kalibre edilen hareketli koluyla kapalı çevre boyunca dolaşılarak alan büyüklüğünü doğrudan verir.","Kitapta izohiyet yöntemiyle alansal ortalama yağış hesabı yapılırken komşu izohiyetler arasındaki şerit alanlarını bulmak için kullanılır."],"tanim_en":"A mechanical or electronic instrument designed to measure the area of an arbitrary two-dimensional plane figure.","bag":{"kavram":["izohiyet"],"soru":[],"hesap":[]}},{"id":"isohyetal-zone","tr":"izohiyet şeridi (eş yağış eğrileri arası)","en":"isohyetal band","kisa":"","tur":"kavram","es":["eş yağış alanı","eşyağış bölgesi","izohiyet haritası","eşdeğer harita","kontur haritası","izoplet haritası"],"tanim":["Bir izohiyet haritasında birbirini izleyen iki eş yağış eğrisi arasında kalan coğrafi alan parçası.","Bu şerit içindeki ortalama yağış yüksekliği iki sınır izohiyetin aritmetik ortalaması alınarak yaklaşıklanır.","Kitapta havzanın alansal ortalama yağışını yamuk kuralı ve alan ağırlıklı toplamla hesaplamada temel alt alan birimi olarak kullanılır."],"tanim_en":"The geographical area enclosed between two consecutive isohyets on a precipitation contour map.","bag":{"kavram":["izohiyet","optimum-olcer"],"soru":[],"hesap":[]}},{"id":"orography","tr":"Orografi","en":"Orography","kisa":"","tur":"kavram","es":["orografik etki","dağ etkisi","orografik yağış","orographic enhancement","orographic effect","dağ topoğrafyası"],"tanim":["Yeryüzü şekillerinin, özellikle dağların ve yükseltilerin coğrafi yapısı ve kabartı dağılımı.","Nemli hava kütlelerinin dağ yamacı boyunca yükselip adyabatik soğumasıyla yoğunlaşmayı ve yağış miktarını artırır.","Kitapta düz arazide Thiessen yöntemi yeterliyken engebeli ve dağlık havzalarda izohiyet yönteminin tercih edilme gerekçesini oluşturur."],"tanim_en":"The branch of physical geography dealing with the nature and formation of mountains and relief features.","bag":{"kavram":["izohiyet","thiessen"],"soru":["S11"],"hesap":[]}},{"id":"trapezoidal-rule","tr":"Yamuk kuralı","en":"Trapezoidal rule","kisa":"","tur":"yontem","es":["trapez yöntemi","yamuk yaklaşımı","trapezoidal integration","yamuk kuralı integrasyonu"],"tanim":["Eğri altındaki alanı ardışık noktaları birleştiren doğru parçaları ve yamuk dilimleri yardımıyla hesaplayan sayısal integral yöntemi.","İki sınır değeri arasındaki integrali dilim genişliği ile sınır değerlerin aritmetik ortalamasının çarpımıyla yaklaşıklanır.","Kitapta iki izohiyet çizgisi arasındaki şeritte değişen yağış miktarının ortalamasını sınırların ortalaması biçiminde hesaplamada kullanılır."],"tanim_en":"A numerical integration method that approximates the integral of a function by computing the area under linear segments forming trapezoids.","bag":{"kavram":["izohiyet"],"soru":[],"hesap":["izohiyet"]}},{"id":"peak-error","tr":"yüzde tepe hatası","en":"peak percent error","kisa":"","tur":"olcu","es":["tepe debisi hatası","peak flow error","tepe akımı bağıl hatası","percent error in peak flow"],"tanim":["Hidrolojik model benzetiminde hesaplanan en yüksek debi ile arazide gözlenen en yüksek debi arasındaki farkın gözlenen tepe değerine oranı.","Yüzde cinsinden hesaplanır; sıfıra yakın değerler iyi tepe eşleşmesini, pozitif değerler aşırı kestirimi, negatif değerler eksik kestirimi gösterir.","Kitapta HEC-HMS model kalibrasyonunda modelin taşkın tepe debisini yakalama başarısını denetleyen anahtar bir performans ölçütüdür."],"tanim_en":"The relative difference between simulated and observed peak discharge expressed as a percentage of the observed peak value.","bag":{"kavram":["kalibrasyon"],"soru":["S38"],"hesap":["kalibrasyon"]}},{"id":"model-validation","tr":"model doğrulaması","en":"model validation","kisa":"","tur":"yontem","es":["doğrulama","validation period","model verification","model geçerleme"],"tanim":["Belirli bir alana özgü modelin yeterli doğrulukta tahmin veya öngörü sağlama yeteneğinin değerlendirilmesi.","Kalibrasyonda kullanılan verilerden tamamen bağımsız, farklı bir dönemdeki yağış ve akım verileriyle model çıktılarının sınanmasıyla yapılır.","Kitapta kalibre edilmiş hidrolojik modelin genel geçerliğini ve aşırı parametre uyumundan kaçındığını kanıtlamada kullanılır."],"tanim_en":"Evaluation of the capability of a site-specific model to provide a sufficiently accurate prediction or forecast.","bag":{"kavram":["kalibrasyon"],"soru":[],"hesap":["kalibrasyon"]}},{"id":"steady-state","tr":"Kararlı durum","en":"Steady state","kisa":"dh/dt = 0","tur":"kavram","es":["kararlı rejim","denge durumu","steady-state condition","yatışkın hal","sabit seviye bırakımı","denge bırakımı"],"tanim":["Bir kontrol hacminde ya da hidrolojik depoda depolanan kütlenin veya su düzeyinin zamanla değişmediği denge hali.","Kütle korunumu gereği birim zamanda giren toplam akı ile çıkan toplam akının birbirine eşit olmasıyla (dW/dt = 0 ya da dh/dt = 0) belirlenir.","Kitapta atmosferdeki suyun kalış süresi hesabında, hazne su bütçesinde ve rasyonel yöntemin en yüksek debi kabullerinde temel alınır."],"tanim_en":"A condition in which the physical properties or state of a hydrologic system remain constant over time.","bag":{"kavram":["kalis-suresi","hazne","su-butcesi"],"soru":["S25"],"hesap":["hazne"]}},{"id":"unit-m-inv4","tr":"metre üzeri eksi dört","en":"per quartic metre","kisa":"m⁻⁴","tur":"birim","es":["m-4","1/m4","Per meter to the fourth","Per meter to the fourth power","m⁻⁴","per quartic meter"],"tanim":["Birim hacim başına ve birim damla yarıçapı aralığı başına düşen yağmur damlası sayısını ifade eden türetilmiş birim.","Boyut analiziyle damla sayısı bölü (hacim × uzunluk) = 1/(m³ · m) = m⁻⁴ şeklinde türetilir.","Kitapta Marshall–Palmer damla boyut dağılımının yarıçap biçimindeki kesişim parametresi (N₀) ve sayı yoğunluğu için kullanılır."],"tanim_en":"A derived unit representing the number of raindrops per unit volume per unit drop radius increment.","bag":{"kavram":["marshall-palmer"],"soru":["S7","S12"],"hesap":[]}},{"id":"exponential-decay","tr":"Üstel azalma","en":"Exponential decay","kisa":"","tur":"kavram","es":["sönümlenme","üstel sönüm","decay exponentially","üstel azalmak","sönümlenmek","decay"],"tanim":["Bir büyüklüğün değerinin mevcut miktarıyla orantılı bir hızla zamanla ya da mesafeyle sürekli küçülmesidir.","Bağımsız değişken arttıkça fonksiyon sıfıra asimptotik olarak yaklaşır.","Kitapta Marshall–Palmer damla dağılımında, Horton derinlik–alan bağıntısında ve doğrusal hazne taban akışı çekilmesinde kullanılır."],"tanim_en":"A reduction in the value of a quantity at a rate proportional to its current value over time or distance.","bag":{"kavram":["marshall-palmer","horton-da","taban-akisi"],"soru":[],"hesap":[]}},{"id":"mean-drop-radius","tr":"Ortalama damla yarıçapı","en":"Mean drop radius","kisa":"r_bar","tur":"olcu","es":["ortalama yarıçap","mean radius","r_bar","r̄"],"tanim":["Yağış hacmindeki tüm damlaların yarıçaplarının damla boyut dağılımı üzerinden alınan beklenen değeridir.","Marshall–Palmer dağılımında eğim parametresinin tersine (1/Λ) eşit olur ve milimetre cinsinden ifade edilir.","Kitapta yağış şiddeti arttıkça ortalama yarıçapın büyümesi ve iri damla payının yükselmesi biçiminde yer alır."],"tanim_en":"The expected value of raindrop radii calculated over the raindrop size distribution.","bag":{"kavram":["marshall-palmer"],"soru":[],"hesap":["marshall-palmer"]}},{"id":"sym-drop-radius","tr":"damla yarıçapı","en":"drop radius","kisa":"r","tur":"olcu","es":["damla yarıçapı sembolü","r"],"tanim":["Bir yağmur damlasının küresel kabul edilen geometrik merkezinden yüzeyine olan uzaklığıdır.","Uluslararası birim sisteminde metre veya milimetre cinsinden belirtilir.","Kitapta Marshall–Palmer dağılımında bağımsız değişken olarak yer alır ve formüllere metre cinsinden girilmesi gerekir."],"tanim_en":"The linear distance from the center of a spherical raindrop to its outer surface.","bag":{"kavram":["marshall-palmer"],"soru":["S7"],"hesap":["marshall-palmer"]}},{"id":"sym-marshall-palmer-lambda","tr":"eğim parametresi (Marshall–Palmer)","en":"slope parameter (Marshall–Palmer)","kisa":"Λ","tur":"olcu","es":["Marshall-Palmer eğimi","slope parameter","dağılım eğim katsayısı","Lambda","Λ"],"tanim":["Marshall–Palmer damla boyut dağılımının yarı logaritmik grafikteki eğimini belirleyen parametredir.","Birim hacimdeki damla yarıçapı biçiminde m⁻¹ veya çap biçiminde mm⁻¹ birimiyle ifade edilir; yağış şiddeti arttıkça değeri küçülür.","Kitapta yağış şiddeti ile ilişkilendirilerek damla tayfının dikliğini ve ortalama damla yarıçapını (1/Λ) belirlemede kullanılır."],"tanim_en":"The slope parameter of the Marshall–Palmer exponential raindrop size distribution that governs the rate of decrease in drop concentration with size.","bag":{"kavram":["marshall-palmer"],"soru":["S7"],"hesap":["marshall-palmer"]}},{"id":"sym-marshall-palmer-n0","tr":"kesişim parametresi (Marshall–Palmer)","en":"intercept parameter (Marshall–Palmer)","kisa":"N₀","tur":"olcu","es":["intercept parameter","başlangıç damla yoğunluğu","sıfır çap damla yoğunluğu","No","N0","damla konsantrasyonu"],"tanim":["Marshall–Palmer damla boyut dağılımı eğrisinin sıfır damla boyutu eksenini kestiği kuramsal damla konsantrasyonudur.","Yarıçap biçiminde 1,6×10⁷ m⁻⁴ ve çap biçiminde 8000 m⁻³ mm⁻¹ sabit tipik değeriyle kabul edilir.","Kitapta yağış şiddetinden bağımsız sabit bir katsayı olarak damla boyutu dağılımının düşey konumunu sabitler."],"tanim_en":"The theoretical raindrop concentration per unit volume at zero drop dimension in the Marshall–Palmer distribution.","bag":{"kavram":["marshall-palmer"],"soru":["S7","S14","S15","S16","S17","S19"],"hesap":["marshall-palmer"]}},{"id":"raindrop-breakup","tr":"Damla parçalanması","en":"Raindrop collision and breakup","kisa":"","tur":"surec","es":["damla çarpışması ve bölünmesi","drop breakup","collision-induced breakup"],"tanim":["Büyük yağmur damlalarının hidrodinamik kararsızlık veya damlalar arası çarpışma neticesinde daha küçük damlacıklara ayrılması sürecidir.","Damla çapı yaklaşık 5 mm sınırını aştığında aerodinamik sürtünme yüzey gerilimini yenerek parçalanmayı tetikler.","Kitapta damla boyutu dağılımının üst sınırını dengeleyen ve aşırı büyük damlaların oluşumunu kısıtlayan bir fiziksel süreç olarak geçer."],"tanim_en":"The fragmentation of large raindrops into smaller droplets caused by aerodynamic instability or collisions.","bag":{"kavram":["marshall-palmer"],"soru":[],"hesap":[]}},{"id":"arithmetic-mean","tr":"aritmetik ortalama (x̄, X̄)","en":"arithmetic mean","kisa":"x̄","tur":"yontem","es":["simple arithmetic mean","simple average","basit ortalama","sample mean","seri ortalaması","X bar ortalaması"],"tanim":["Gözlem serisindeki tüm değerlerin toplamının gözlem sayısına bölünmesiyle elde edilen merkezi eğilim ölçüsüdür.","Havzadaki ölçerler düzenli dağılmışsa ve topoğrafik yükseklik farkları azsa alansal yağış hesabında doğrudan kullanılır.","Kitapta alansal yağış hesabında, eksik veri tamamlamada komşu istasyon normalleri %10 içinde kaldığında ve Gumbel analizinde yer alır."],"tanim_en":"The sum of a collection of numerical values divided by the count of the values in the collection.","bag":{"kavram":["normal-oran","thiessen","gumbel"],"soru":["S10","S12","S13","S44"],"hesap":["thiessen","optimum-olcer","normal-oran","izohiyet"]}},{"id":"automatic-rain-gauge","tr":"Otomatik yağışölçer","en":"Automatic rain gauge","kisa":"","tur":"cihaz","es":["plüviyograf","yazıcı yağışölçer","yazıcı plüviyometre","otomatik istasyon"],"tanim":["Yağış miktarını ve şiddetini insan müdahalesine gerek duymadan kesintisiz olarak ölçen alettir.","Devrilen kovalı, tartılı ya da optik mekanizmalarla çalışır; yağış şiddetini mm/h cinsinden üretir.","Kitapta optimum ölçer ağlarının planlanmasında ve şiddet–süre analizlerinde temel veri kaynağı olarak rol oynar."],"tanim_en":"An instrument designed to determine rainfall depth and rainfall rate continuously without manual intervention.","bag":{"kavram":["optimum-olcer","yagis-siddeti"],"soru":[],"hesap":[]}},{"id":"network-density","tr":"Ölçüm ağı yoğunluğu","en":"Network density","kisa":"","tur":"kavram","es":["ağ yoğunluğu","istasyon yoğunluğu","gauge density","raingauge network density","Ağ yoğunluğu","istasyon sıklığı"],"tanim":["Belirli meteorolojik veya hidrolojik amaçlar için kurulan bir gözlem ağındaki istasyonların birbirine yakınlığının ölçüsüdür.","İstasyon başına düşen kilometrekare (km²/istasyon) veya birim alandaki istasyon sayısı olarak tanımlanır.","Kitapta havza yağışını hedeflenen hata payı içinde temsil edebilmek için gereken optimum ölçer sayısının belirlenmesinde esas alınır."],"tanim_en":"A measure of the proximity of observing stations in an observational network established for meteorological or hydrological investigations.","bag":{"kavram":["optimum-olcer"],"soru":[],"hesap":[]}},{"id":"code-dsi","tr":"DSİ (Devlet Su İşleri)","en":"State Hydraulic Works (Türkiye)","kisa":"DSİ","tur":"kod","es":["Devlet Su İşleri","DSI","D.S.İ."],"tanim":["Türkiye'deki su kaynaklarının planlanması, korunması, geliştirilmesi ve işletilmesinden sorumlu ana kamu kurumudur.","Akarsu akım gözlem istasyonlarını kurup işletir ve hidrolojik ölçüm verilerini derler.","Kitapta ölçüm ağı tasarımı ve baraj haznelerinin işletilmesinde yetkili ulusal kurum olarak anılır."],"tanim_en":"The primary government agency responsible for the development, management, and hydrological monitoring of water in Türkiye.","bag":{"kavram":["optimum-olcer"],"soru":[],"hesap":[]}},{"id":"world-meteorological-organization","tr":"Dünya Meteoroloji Örgütü","en":"World Meteorological Organization","kisa":"WMO","tur":"kod","es":["WMO","DMÖ"],"tanim":["Hava durumu, iklim ve su kaynakları alanlarında uluslararası iş birliğini ve standartları koordine eden Birleşmiş Milletler uzmanlık kuruluşu.","Hidrometeorolojik ölçüm ağlarının planlanması ve asgari istasyon yoğunluğu için kılavuz standartlar yayımlar.","Kitapta yağış ölçüm ağı tasarımı için düz ılıman alanlarda 600–900 km², dağlık arazide 100–250 km² başına bir ölçer önerisiyle yer alır."],"tanim_en":"A specialized agency of the United Nations responsible for international cooperation and standard setting in meteorology, climatology, and operational hydrology.","bag":{"kavram":["optimum-olcer"],"soru":[],"hesap":[]}},{"id":"allowable-error","tr":"kabul edilen hata (ε, x)","en":"allowable error","kisa":"ε","tur":"olcu","es":["hata payı","kabul edilebilir hata","hata payı ε","izin verilen hata","ortalama yağış hata sınırı","allowable variance"],"tanim":["Havza alansal ortalama yağışının kestiriminde örneklem ortalamasının kabul edilebilir göreli hata sınırı.","Yüzde olarak ifade edilir; hidrolojik çalışmalarda tipik değeri %5 ile %10 arasındadır.","Gereken optimum istasyon sayısını karesel etkiler; izin verilen hata yarıya indiğinde gereken ölçer sayısı 4 katına çıkar."],"tanim_en":"The acceptable relative margin of error in estimating the areal mean precipitation of a catchment.","bag":{"kavram":["optimum-olcer"],"soru":["S12","S13"],"hesap":["optimum-olcer","olcer-dagitim"]}},{"id":"coefficient-of-variation","tr":"değişim katsayısı","en":"coefficient of variation","kisa":"Cᵥ","tur":"olcu","es":["varyasyon katsayısı","CV","Cvn","örneklem varyasyon katsayısı","Cvn — örneklem değişim katsayısı","Cvn — sample coefficient of variation"],"tanim":["Standart sapmanın aritmetik ortalamaya oranını belirten boyutsuz bağıl değişkenlik ölçüsü.","Yüzde cinsinden belirtilir; yağış ölçümlerinde n − 1 serbestlik dereceli örneklem standart sapması kullanılır.","Düz arazilerde tipik olarak %10–30, dağlık engebeli arazilerde ise %40 ve üzerinde değerler alır."],"tanim_en":"A dimensionless measure of relative dispersion defined as the ratio of standard deviation to the arithmetic mean.","bag":{"kavram":["optimum-olcer","hershfield","gumbel"],"soru":["S12","S13"],"hesap":["optimum-olcer","olcer-dagitim","hershfield","gumbel"]}},{"id":"standard-error","tr":"Standart hata","en":"Standard error","kisa":"σ_xbar","tur":"olcu","es":["ortalamanın standart hatası","standard error of mean"],"tanim":["Bir istatistiğin örnekleme dağılımının standart sapması.","Örneklem standart sapmasının istasyon sayısının kareköküne (√N) bölünmesiyle hesaplanır.","Havza yağış ortalamasının güvenilirliğini gösterir ve optimum ölçer sayısı bağıntısının teorik temelini oluşturur."],"tanim_en":"The standard deviation of the sampling distribution of a statistic, most commonly of the sample mean.","bag":{"kavram":["optimum-olcer"],"soru":[],"hesap":["optimum-olcer","olcer-dagitim"]}},{"id":"sym-spatial-corr","tr":"ortalama mekânsal korelasyon","en":"mean spatial correlation","kisa":"ρ̄","tur":"olcu","es":["uzaysal korelasyon katsayısı"],"tanim":["Farklı konumlardaki yağışölçerler arasındaki yağış değerlerinin karşılıklı doğrusal bağımlılığını belirten ortalama korelasyon katsayısı.","İstasyonlar arası mesafe arttıkça azalır; 0 ile 1 arasında pozitif değerler aldığında ölçümlerin birbirinden bağımsız olmadığını gösterir.","Ölçerler arası pozitif ilişki (ρ̄ > 0), ortalamanın varyansını bağımsız durumdaki σ²/N değerinin üzerine çıkararak gereken ölçer sayısını artırır."],"tanim_en":"The average correlation coefficient quantifying spatial statistical dependence between measurements across a gauge network.","bag":{"kavram":["optimum-olcer"],"soru":[],"hesap":["optimum-olcer","olcer-dagitim"]}},{"id":"variance","tr":"Varyans","en":"Variance","kisa":"Var","tur":"olcu","es":["değişinti","örneklem varyansı","mekansal varyans","istasyonlar arası yağış varyansı","v","Yağışın alansal varyansı"],"tanim":["Bir istatistiksel dağılımın ortalamaya göre ikinci merkezi momenti.","Gözlemlerin aritmetik ortalamadan sapmalarının karelerinin ortalamasıdır; standart sapmanın karesine eşittir.","Havza yağışında istasyonlar arası yayılımı veya akım modellemesinde gözlem değişkenliğini belirler."],"tanim_en":"Second central moment of a statistical distribution.","bag":{"kavram":["optimum-olcer"],"soru":[],"hesap":["optimum-olcer","olcer-dagitim"]}},{"id":"diversion-channel","tr":"Derivasyon kanalı","en":"Diversion channel","kisa":"","tur":"cihaz","es":["taşkın çevirme kanalı","taşkın derivasyon kanalı","Çevirme kanalı"],"tanim":["Taşkın sularını veya fazla akımı yerleşim alanlarından, ana yataktan ya da bir yapıdan başka bir su yoluna veya hazneye yönlendirmek için açılan yapay kanal.","Kanal kapasitesi hidrolojik tasarım debisine göre boyutlandırılır ve kapaklı ya da savaklı giriş yapılarıyla denetlenir.","Kitapta taşkın zararlarını önleme yapıları ve kanal ötelemesi bağlamında fazla suyun uzaklaştırılması yöntemi olarak yer alır."],"tanim_en":"An artificial waterway constructed to divert flood water away from protected land into another river or reservoir.","bag":{"kavram":["oteleme","hazne"],"soru":[],"hesap":[]}},{"id":"prism-storage","tr":"prizma depolaması","en":"prism storage","kisa":"K·O","tur":"kavram","es":["taban depolaması"],"tanim":["Bir akarsu kesiminde kararlı akış durumunda mevcut olan ve mansap çıkış debisi ile doğrudan orantılı kabul edilen su hacmi.","Muskingum kanal öteleme yönteminde K·O formülasyonu ile temsil edilir; burada K depolama sabitidir.","Giriş ve çıkış debileri eşit olduğunda kanal içindeki toplam su depolamasını tek başına oluşturur."],"tanim_en":"The volume of water stored in a river reach under steady-state flow conditions, proportional to the outflow discharge.","bag":{"kavram":["oteleme"],"soru":[],"hesap":[]}},{"id":"wedge-storage","tr":"kama depolaması","en":"wedge storage","kisa":"KX(I-O)","tur":"kavram","es":["taşkın önü depolaması"],"tanim":["Taşkın dalgasının ilerleyişi sırasında akarsu kesimine giren ve çıkan debi farkından doğan kama şeklindeki geçici su hacmi.","Yükselme kolunda giriş debisi çıkıştan büyük olduğunda pozitif, çekilme kolunda ise negatif değer alarak depolamayı azaltır.","Muskingum yönteminde KX(I − O) terimiyle ifade edilir; X ağırlık katsayısı kamanın sönüm ve öteleme dengesini belirler."],"tanim_en":"The wedge-shaped volume of temporary water storage in a river reach caused by the difference between inflow and outflow.","bag":{"kavram":["oteleme"],"soru":[],"hesap":[]}},{"id":"sym-k-muskingum","tr":"Muskingum depolama sabiti","en":"Muskingum storage constant","kisa":"K","tur":"olcu","es":["Muskingum K","travel time constant"],"tanim":["Muskingum kanal öteleme yönteminde taşkın dalgasının akarsu kesimindeki seyahat süresini temsil eden depolama sabiti.","Zaman boyutundadır ve saat cinsinden ifade edilir; yaklaşık olarak taşkın dalgasının kesim boyunca akış süresine eşittir.","Toplam kanal depolamasını prizma ve kama bileşenleriyle ilişkilendiren temel çarpan parametresidir."],"tanim_en":"A storage parameter in Muskingum channel routing representing the travel time of a flood wave through the reach.","bag":{"kavram":["oteleme"],"soru":[],"hesap":[]}},{"id":"sym-x-muskingum","tr":"Muskingum ağırlık katsayısı","en":"Muskingum weighting factor","kisa":"X","tur":"olcu","es":["Muskingum X","weighting parameter","Muskingum ağırlık faktörü","kama depolama katsayısı"],"tanim":["Muskingum taşkın öteleme yönteminde kama depolamasının giriş ve çıkış debilerine göre göreli ağırlığını belirleyen boyutsuz parametre.","Doğal akarsu yataklarında değeri genellikle 0,1 ile 0,3 aralığında değişir; kuramsal üst sınırı 0,5 değeridir.","Kanal boyunca ilerleyen taşkın dalgasındaki sönüm oranını belirler; katsayı sıfır olduğunda hazne depolamasını, 0,5 olduğunda sönümsüz saf ötelemeyi ifade eder."],"tanim_en":"Dimensionless parameter in the Muskingum routing method that determines the relative influence of inflow and outflow on reach storage.","bag":{"kavram":["oteleme"],"soru":[],"hesap":[]}},{"id":"attenuation","tr":"sönüm","en":"attenuation","kisa":"","tur":"surec","es":["tepenin alçalması","peak attenuation","flood wave attenuation","sönümleme"],"tanim":["Taşkın dalgasının akarsu kesimi veya hazne boyunca mansaba ilerlerken kanal depolaması etkisiyle tepe debisinin alçalması süreci.","Çıkış hidrografının tabana yayılması ve en yüksek akış değerinin düşmesiyle nicelendirilir.","Kitapta Clark birim hidrografındaki doğrusal hazne mekanizmasında ve Muskingum kanal ötelemesinde taşkın pikinin düşüşünü açıklamak için kullanılır."],"tanim_en":"Reduction in the peak discharge of a flood wave as it travels downstream through a channel reach or reservoir.","bag":{"kavram":["oteleme","clark"],"soru":["S37"],"hesap":[]}},{"id":"translation","tr":"öteleme","en":"translation","kisa":"","tur":"surec","es":["zamanda ileri alma","pure translation","öteleme dalgası","saf öteleme"],"tanim":["Akış hidrografının biçimi ve tepe debisi değişmeksizin akarsu kesimi boyunca zamanda ileriye taşınması süreci.","Depolama etkisi ihmal edildiğinde çıkış hidrografı giriş hidrografının belirli bir gecikme süresi kadar ötelenmesiyle hesaplanır.","Kitapta Clark birim hidrografındaki zaman–alan histogramında ve HEC-HMS Lag kanal öteleme yönteminde dalga hareketini modellemek için kullanılır."],"tanim_en":"Movement of a flood hydrograph downstream along a reach without change in shape or peak magnitude.","bag":{"kavram":["oteleme"],"soru":["S33","S35","S37","S43"],"hesap":["clark"]}},{"id":"river-improvement","tr":"Akarsu yatak ıslahı","en":"River improvement","kisa":"","tur":"yontem","es":["yatak genişletme","channel improvement","dere ıslahı","yatak düzenlemesi","nehir ıslahı","Akarsu ıslahı"],"tanim":["Taşkın zararlarını önlemek amacıyla akarsu yatağının kesitini genişletme, derinleştirme veya kaplama yoluyla akış kapasitesini artırma mühendislik uygulaması.","Akış hızını yükseltip hidrolik pürüzlülüğü azaltarak su seviyesini düşürür, ancak mansaba iletilen tepe debisini büyütebilir.","Kitapta mevcut kanal iletim kapasitesini artırmaya yönelik taşkın koruma yöntemleri arasında yer alır."],"tanim_en":"Engineering work carried out on a river channel to enhance conveyance capacity and mitigate flood hazard.","bag":{"kavram":["oteleme"],"soru":[],"hesap":[]}},{"id":"sym-delta-t","tr":"zaman adımı","en":"time step","kisa":"Δt","tur":"olcu","es":["aralık süresi","çubuk genişliği","dt","zaman adımı","zaman aralığı","bütçe periyodu"],"tanim":["Hidrolojik hesaplamalarda, sayısal modelleme adımlarında veya ölçüm dizilerinde iki ardışık durum arasındaki ayrık zaman aralığı.","Hesabın ölçeğine göre saniye, saat veya gün cinsinden tanımlanır; hiyetograf grafiklerinde yağış çubuğunun genişliğidir.","Kitapta su bütçesinde depo değişim hızının paydasında ve φ-indeksi hesabında net yağış hacmini bulmak için kullanılır."],"tanim_en":"Discrete time interval between successive computational points or observations in hydrologic modeling.","bag":{"kavram":["phi-indeksi","birim-hidrograf","akis-birim"],"soru":["S2","S4","S25","S26","S35","S37"],"hesap":["uzun-donem-et","havza-butcesi","akis-derinlik","hazne-ay"]}},{"id":"w-index","tr":"W-indeksi","en":"W-index","kisa":"W","tur":"olcu","es":["the W-index of the storm","average loss rate","ortalama kayıp hızı","sabit kayıp hızı","fi katsayısı","phi-index"],"tanim":["Bir fırtına boyunca gerçekleşen toplam kaybın fırtınanın toplam yağış süresine bölünmesiyle elde edilen ortalama sızma ve tutulma hızı.","Birimi mm/h cinsindendir; hesaplanmasında yağış şiddetinin kayıp hızının altında kaldığı aralıklar da süreye dahil edilir.","Kitapta φ-indeksi ile karşılaştırma amacıyla verilir ve zayıf yağış aralıklarını dışarıda bırakmadığı için φ değerinden daima küçük çıkar."],"tanim_en":"Average infiltration and loss rate obtained by dividing total hydrologic abstraction by the total duration of a storm.","bag":{"kavram":["phi-indeksi"],"soru":["S42"],"hesap":["phi-deneme"]}},{"id":"unit-g-per-kg","tr":"gram/kilogram","en":"grams per kilogram","kisa":"g/kg","tur":"birim","es":["g/kg","kg/kg","kilogram/kilogram","kilograms per kilogram","gram bölü kilogram"],"tanim":["Bir kilogram nemli hava kütlesi içinde bulunan su buharı miktarını gram cinsinden belirten boyutsuz oran birimi.","Meteorolojide özgül nem ve karışma oranı değerlerini ifade etmede yaygın kullanılır; 1 g/kg = 0,001 kg/kg değerine karşılık gelir.","Kitapta atmosferik katmanlardaki özgül nem verilerini tanımlamak ve yağışa geçebilir su (PW) miktarını hesaplamak için kullanılır."],"tanim_en":"Unit of proportion expressing the amount of water vapour in grams per kilogram of moist air.","bag":{"kavram":["pw"],"soru":["S8"],"hesap":[]}},{"id":"unit-hpa","tr":"hektopaskal","en":"hectopascal","kisa":"hPa","tur":"birim","es":["hPa","milibar","mb"],"tanim":["Uluslararası Birimler Sisteminde (SI) 100 paskala (10² Pa) eşit olan ve CGS sistemindeki milibara tam denk gelen basınç birimi.","Meteoroloji uygulamalarında atmosfer basıncını, standart izobar yüzeylerini ve atmosferik katman kalınlıklarını belirtmede temel standarttır.","Kitapta atmosferik katman kalınlıklarını (dp) belirlemede ve yağışa geçebilir su integrali sınırlarında kullanılır."],"tanim_en":"Unit of pressure in the International System of Units equal to 100 pascals and equivalent to one millibar.","bag":{"kavram":["pw"],"soru":["S8"],"hesap":[]}},{"id":"unit-kelvin","tr":"kelvin","en":"kelvin","kisa":"K","tur":"birim","es":["K","mutlak sıcaklık","mutlak sıcaklık birimi"],"tanim":["Suyun üçlü noktasının termodinamik sıcaklığının 1/273,16 kesrine eşit olan temel SI mutlak sıcaklık birimi (sembolü K).","Sıfır noktası mutlak sıfırı (−273,15 °C) gösterir; sıcaklık farkı aralığı santigrat derece ile tamamen özdeştir.","Kitapta termodinamik hesaplarda, atmosferik buhar basıncı ilişkilerinde ve Clausius–Clapeyron bağıntısında mutlak sıcaklığı belirtmede yer alır."],"tanim_en":"Unit of thermodynamic temperature in the International System of Units defined as a fraction of the triple point of water.","bag":{"kavram":["pw"],"soru":["S1","S2","S3","S4","S5","S6"],"hesap":[]}},{"id":"unit-pa","tr":"paskal","en":"pascal","kisa":"Pa","tur":"birim","es":["Pa","newton bölü metrekare","N/m²"],"tanim":["Bir metrekarelik alana dik ve düzgün biçimde etki eden 1 newtonluk kuvvetin oluşturduğu temel SI basınç birimi (1 Pa = 1 N/m²).","0,01 hPa veya 0,01 milibara eşittir; hidrostatik denklemlerde ve dinamik akış formüllerinde temel tutarlı basınç birimidir.","Kitapta yağışa geçebilir su integralindeki basınç kalınlığı dp büyüklüğünün formüle yerleştirilmesinde doğrudan kullanılır."],"tanim_en":"Unit of pressure in the International System of Units equal to one newton per square metre.","bag":{"kavram":["pw"],"soru":["S3","S7","S8","S10","S11","S12"],"hesap":[]}},{"id":"gnss-receiver","tr":"GNSS alıcısı","en":"GNSS receiver","kisa":"GNSS","tur":"cihaz","es":["küresel navigasyon uydu sistemi","GPS","GPS alıcısı","küresel konumlama alıcısı"],"tanim":["Uydu takımyıldızlarından yayılan radyo dalgalarını alarak konum, zaman ve atmosferik gecikme verisi üreten elektronik cihaz.","Radyo sinyalinin troposferden geçerken uğradığı gecikme miktarından yararlanılarak düşey doğrultudaki toplam su buharı kestirilir.","Kitapta yağışa geçebilir su miktarının uzaktan izlenmesi ve olası en büyük yağış analizlerinde nem maksimizasyonunda yer alır."],"tanim_en":"An electronic device that captures radio signals from satellite navigation constellations for positioning and atmospheric delay measurement.","bag":{"kavram":["pw"],"soru":[],"hesap":[]}},{"id":"radiosonde","tr":"Radyosonda","en":"Radiosonde","kisa":"","tur":"cihaz","es":["meteoroloji balonu","atmosferik sonda","radyosond"],"tanim":["Atmosfer boyunca bir balonla taşınan, basınç, sıcaklık ve nem gibi meteorolojik değişkenleri ölçen ve bu verileri radyo vericisiyle yer istasyonuna ileten cihaz.","Yükselme boyunca düşey atmosfer profilini doğrudan yerinde (in-situ) ölçer.","Kitapta yağışa geçebilir su hesabı için basınç katmanlarındaki nem profilini sağlamada ve olası en büyük yağış için nem maksimizasyonunda kullanılır."],"tanim_en":"An instrument carried by a balloon through the atmosphere to measure meteorological variables and transmit data to a ground station by radio.","bag":{"kavram":["pw"],"soru":[],"hesap":[]}},{"id":"weather-satellite","tr":"Meteoroloji uydusu","en":"Weather satellite","kisa":"","tur":"cihaz","es":["uydu","satellite","hava durumu uydusu","meteorolojik uydu"],"tanim":["Dünya yörüngesinde dönerek atmosferi ve yeryüzünü optik, kızılötesi ve mikrodalga algılayıcılarla uzaktan izleyen uzay aracı.","Bulut tepe parlaklık sıcaklığı, yağış şiddeti ve atmosferik nem alanlarını geniş coğrafi kapsama ile ölçer.","Kitapta yağış ölçer bulunmayan alanlarda yağış şiddeti kestirimi ve yağışa geçebilir su miktarının belirlenmesinde kullanılır."],"tanim_en":"An artificial satellite designed to observe and monitor Earth's atmosphere and weather systems from orbit.","bag":{"kavram":["pw","yagis-siddeti"],"soru":["S16"],"hesap":[]}},{"id":"hydrostatic-equilibrium","tr":"Hidrostatik denge","en":"Hydrostatic equilibrium","kisa":"","tur":"kavram","es":["hidrostatik denklem","hydrostatic balance","hidrostatik denge durumu"],"tanim":["Düşey basınç gradyanı kuvveti ile yerçekimi kuvvetinin birbirini tam olarak dengelediği akışkan durumu.","Bu kabul altında atmosferde dp = −ρ g dz bağıntısı geçerli olup yükseklik koordinatı yerine basınç koordinatı kullanılır.","Kitapta atmosferik nem sütunu integralinde geometrik yükseklik yerine basınç aralığı kullanılarak yağışa geçebilir suyun hesaplanmasını sağlar."],"tanim_en":"A state of balance in a fluid where the upward pressure gradient force equals the downward gravitational force.","bag":{"kavram":["pw"],"soru":[],"hesap":[]}},{"id":"brightness-temperature","tr":"Parlaklık sıcaklığı","en":"Brightness temperature","kisa":"Tb","tur":"olcu","es":["ışıma sıcaklığı","radyasyon sıcaklığı","Tb"],"tanim":["Bir cismin belirli bir dalga boyunda yaydığı ışıma şiddetine eşit ışıma yapan kara cismin Planck fonksiyonuna göre eşdeğer sıcaklığı.","Birimi kelvin (K) olup meteoroloji uydularının kızılötesi ve mikrodalga radyometreleriyle ölçülür.","Kitapta bulut tepe sıcaklığının belirlenmesinde, konvektif fırtınaların izlenmesinde ve nem kestiriminde kullanılır."],"tanim_en":"The temperature of a blackbody that emits the same radiant intensity as a given body at a specific wavelength.","bag":{"kavram":["pw"],"soru":[],"hesap":["pw"]}},{"id":"dewpoint-temperature","tr":"çiy noktası sıcaklığı","en":"Dewpoint temperature","kisa":"Td","tur":"olcu","es":["çiğ noktası","dewpoint","Td","çiğ noktası sıcaklığı sembolü","dew point temperature"],"tanim":["Sabit basınç ve sabit nem içeriğinde, havanın doymuş hale gelmesi için soğutulması gereken sıcaklık.","Birimi santigrat derece (°C) olup psikrometre ile ölçülür; doymuş havada hava sıcaklığına eşit olur (T = Td).","Kitapta buharlaşma hesaplarında havanın buhar basıncının bulunması ve yağışa geçebilir su kestiriminde kullanılır."],"tanim_en":"The temperature to which a parcel of air must cool at constant pressure and moisture content to become saturated with water vapour.","bag":{"kavram":["pw","harbeck"],"soru":[],"hesap":["pw","harbeck"]}},{"id":"mixing-ratio","tr":"Karışma oranı","en":"Mixing ratio","kisa":"w","tur":"olcu","es":["water vapour mixing ratio","su buharı karışma oranı","nem karışma oranı","karışım oranı"],"tanim":["Nemli bir hava parselindeki su buharı kütlesinin, bu buharla birlikte bulunan kuru havanın kütlesine oranı.","Boyutsuz bir oran olup genellikle gram bölü kilogram (g/kg) veya kilogram bölü kilogram (kg/kg) birimiyle ifade edilir.","Kitapta atmosferik sütundaki nem miktarının belirlenmesinde ve yağışa geçebilir su hesabında özgül neme yakın bir büyüklük olarak yer alır."],"tanim_en":"The ratio of the mass of water vapour to the mass of dry air in a given volume of moist air.","bag":{"kavram":["pw"],"soru":[],"hesap":["pw"]}},{"id":"relative-humidity","tr":"Bağıl nem","en":"Relative humidity","kisa":"RH","tur":"olcu","es":["nisbi nem","oransal nem","percent humidity","RH"],"tanim":["Belirli bir basınç ve sıcaklıkta havadaki gerçek buhar basıncının, aynı koşullardaki doymuş buhar basıncına yüzdesel oranı.","Yüzde (%) veya 0 ile 1 arasında ondalık kesir olarak ifade edilir; psikrometre veya higrometre ile ölçülür.","Kitapta göl buharlaşması hesabında 2 m seviyesindeki buhar basıncını belirlemek için kullanılır (e₂ = bağıl nem × eₛ)."],"tanim_en":"The percentage ratio of the actual vapour pressure of moist air to the saturation vapour pressure at the same temperature and pressure.","bag":{"kavram":["pw","harbeck"],"soru":["S28"],"hesap":["harbeck","pw"]}},{"id":"saturation-vapour-pressure","tr":"Doymuş buhar basıncı","en":"Saturation vapour pressure","kisa":"e_s","tur":"olcu","es":["doygunluk buhar basıncı","doygun buhar basıncı","saturation vapor pressure","e_s","Doygun buhar basıncı","Saturation vapor pressure"],"tanim":["Belirli bir sıcaklıkta düz bir saf su yüzeyi ile termodinamik dengede bulunan su buharının uyguladığı kısmi basınç.","Birimi milibar (mb) veya hektopaskal (hPa) olup sıcaklığın artmasıyla üstel olarak artar; Tetens denklemi ile hesaplanır.","Kitapta su yüzeyi buharlaşması formüllerinde buhar açığı ve net buharlaşma hızını belirlemede kullanılır."],"tanim_en":"The maximum vapour pressure exerted by water vapour in equilibrium with a plane surface of pure water at a given temperature.","bag":{"kavram":["pw","harbeck"],"soru":["S28"],"hesap":["harbeck","pw"]}},{"id":"sym-gravitational-acceleration","tr":"yerçekimi ivmesi","en":"gravitational acceleration","kisa":"g","tur":"olcu","es":["yerçekimi","gravity","g","standart yerçekimi ivmesi"],"tanim":["Yerkürenin kütleçekim kuvveti ile dönmesinden doğan merkezkaç kuvvetinin bileşkesi sonucu birim kütleye uygulanan ivme.","Birimi m/s² olup standart değeri 9,81 m/s² olarak alınır.","Kitapta hidrostatik denge dönüşümünde basınç farkını birim alandaki kütleye çevirmede ve yağışa geçebilir su bağıntısında bölen olarak yer alır."],"tanim_en":"The acceleration produced by the mutual attraction of Earth and an object combined with Earth's rotation.","bag":{"kavram":["pw"],"soru":[],"hesap":["pw"]}},{"id":"sym-pressure-differential","tr":"basınç aralığı (dp, Δp)","en":"pressure interval","kisa":"dp","tur":"olcu","es":["p_s yüzey basıncı","p_t üst sınır basıncı","Δp","dp","basınç farkı","pressure differential"],"tanim":["Atmosferde düşey doğrultuda iki basınç seviyesi arasındaki farkı veya katman kalınlığını temsil eden diferansiyel basınç aralığıdır.","Birimi paskal (Pa) olup hesaplamalarda hektopaskal (hPa) değeri 100 ile çarpılarak Pa birimine çevrilir.","Yağışa geçebilir su (PW) integralinde düşey katmandaki havanın birim alana düşen kütlesini (Δp/g) ve buhar miktarını belirlemede kullanılır."],"tanim_en":"The vertical pressure difference between two atmospheric levels used in column water integration.","bag":{"kavram":["pw"],"soru":["S8"],"hesap":["pw"]}},{"id":"wet-bulb-temperature","tr":"yaş termometre sıcaklığı","en":"Wet bulb temperature","kisa":"Tw","tur":"olcu","es":["ıslak termometre sıcaklığı","wet-bulb temp","Tw","yaş hazne sıcaklığı"],"tanim":["Doğrudan güneş ışınımından korunan ve havaya maruz bırakılan ıslak hazneli bir termometreden okunan sıcaklıktır.","Su buharlaşmasının sağladığı soğuma nedeniyle kuru termometre sıcaklığına eşit veya ondan düşüktür; bağıl nem yüzde 100 olduğunda kuru termometre sıcaklığıyla çakışır.","Psikrometre ile hava neminin, buharlaşma potansiyelinin ve atmosferik nem içeriğinin belirlenmesinde kullanılır."],"tanim_en":"The temperature measured by a wet-bulb thermometer ventilated and shielded from direct solar radiation.","bag":{"kavram":["pw","harbeck"],"soru":[],"hesap":["pw","harbeck"]}},{"id":"moisture-convergence","tr":"Nem yakınsaması","en":"Moisture convergence","kisa":"","tur":"surec","es":["low-level moisture convergence","nem akışı yakınsaması","nem birikimi","moisture flux convergence"],"tanim":["Yatay rüzgâr alanı ve hava akımlarının etkisiyle belirli bir bölgeye su buharının taşınarak net nem girişi oluşması sürecidir.","Birim alandaki yatay nem akısı diverjansının negatifi olarak ifade edilir ve konvektif fırtınaların beslenmesinde ana mekanizmadır.","Fırtınanın yerel sütundaki mevcut yağışa geçebilir su miktarından kat kat daha fazla yağış üretmesini açıklar."],"tanim_en":"The horizontal net accumulation of water vapour into a region driven by wind fields.","bag":{"kavram":["pw","hershfield"],"soru":[],"hesap":[]}},{"id":"clausius-clapeyron-relation","tr":"Clausius–Clapeyron bağıntısı","en":"Clausius–Clapeyron relation","kisa":"","tur":"yontem","es":["Clausius-Clapeyron denklemi","Clausius–Clapeyron denklemi","Clausius–Clapeyron equation","Clausius-Clapeyron equation","doyma buhar basıncı sıcaklık bağıntısı"],"tanim":["Saf bir maddenin iki fazı arasındaki denge durumunda doymuş buhar basıncının sıcaklıkla değişim oranını veren termodinamik denklemdir.","Atmosfer koşullarında doymuş buhar basıncının her 1 K sıcaklık artışında yaklaşık yüzde 7 oranında yükseldiğini ifade eder.","Isınan iklimde atmosferin nem tutma kapasitesini, yağışa geçebilir su miktarını ve aşırı yağış potansiyelini kestirmede temel alınır."],"tanim_en":"Thermodynamic relationship describing how saturation vapour pressure varies with temperature.","bag":{"kavram":["pw","harbeck"],"soru":[],"hesap":["pw","harbeck"]}},{"id":"moisture-maximization","tr":"Nem maksimizasyonu","en":"Moisture maximization","kisa":"","tur":"yontem","es":["nem büyütme faktörü","moisture adjustment","moisture maximization factor","nem maksimizasyon oranı"],"tanim":["Gözlenmiş bir fırtınanın ürettiği yağışı, fırtına anındaki çiğ noktası nemi ile bölgede fiziksel olarak gerçekleşebilecek en yüksek çiğ noktası nemi oranına göre büyütme yöntemidir.","Olası en büyük yağış (PMP) hesaplarında meteorolojik fırtına modellemesinin temel bileşenidir ve fırtına büyütme çarpanı olarak uygulanır.","Yağışa geçebilir su oranlarını kullanarak gözlenen fırtına derinliğini kuramsal üst sınırına taşımaya yarar."],"tanim_en":"A method of scaling observed storm rainfall by the ratio of maximum precipitable water to storm precipitable water.","bag":{"kavram":["pw","hershfield"],"soru":[],"hesap":["pw","hershfield"]}},{"id":"unit-in-h","tr":"inç / saat","en":"inches per hour","kisa":"in/h","tur":"birim","es":["in/hr","inch per hour","inç bölü saat","in/h","İnç bölü saat","Inches per hour"],"tanim":["İngiliz birim sisteminde birim zamanda yüzeye düşen yağış derinliğini veya sızma kaybı hızını belirten şiddet birimidir.","1 in/h yaklaşık 25,4 mm/h değerine denktir; rasyonel yöntemde 1 in/h yağış şiddeti 1 akre alana uygulandığında yaklaşık 1 cfs tepe debisi üretir.","Rasyonel yöntem, kayıp yöntemleri ve şiddet–süre–sıklık (IDF) bağıntılarında standart şiddet ölçüsü olarak kullanılır."],"tanim_en":"An imperial unit of rainfall intensity or infiltration rate equal to one inch of water depth per hour.","bag":{"kavram":["rasyonel","ic-kayip","phi-indeksi"],"soru":["S33","S34"],"hesap":["rasyonel-ing"]}},{"id":"detention-basin","tr":"bekletme haznesi","en":"detention basin","kisa":"","tur":"cihaz","es":["geciktirme haznesi","detention pond","stormwater detention basin","taşkın geciktirme havuzu","kuru bekletme havuzu"],"tanim":["Geçici depolama yoluyla bir akarsuyun veya kentsel drenaj ağının tepe taşkın debisini düşüren taşkın kontrol haznesidir.","Gelen taşkın dalgasını hacminde biriktirip kontrollü bir çıkış yapısıyla zamana yayarak mansaptaki taşkın hasarını önler.","Kentsel hidrolojide rasyonel yöntemle boyutlandırılan ve hazne su bütçesi denklemleriyle ötelenen temel mühendislik yapısıdır."],"tanim_en":"A flood control reservoir designed to reduce peak streamflow through temporary storage.","bag":{"kavram":["rasyonel","hazne"],"soru":[],"hesap":[]}},{"id":"impervious-surface","tr":"geçirimsiz yüzey","en":"impervious surface","kisa":"","tur":"kavram","es":["geçirimsiz alan","percent impervious","impervious area","geçirimsizlik","geçirimsiz yüzey (alan)","pervious area"],"tanim":["Suyun toprağa sızmasını engelleyen çatı, asfalt yol, beton ve kaldırım gibi insan yapısı veya sıkışmış doğal yüzeylerdir.","Yüzey sızmasını sıfıra yaklaştırarak yağışın neredeyse tamamını doğrudan akışa dönüştürür ve toplanma süresini kısaltır.","Rasyonel yöntemde yüksek akış katsayısı (C ≈ 0,9) ve SCS yönteminde yüksek eğri numarası (CN ≈ 98) ile temsil edilir."],"tanim_en":"A ground surface such as pavement or roofing that prevents the natural infiltration of water into the soil.","bag":{"kavram":["rasyonel","ic-kayip","scs-cn"],"soru":[],"hesap":[]}},{"id":"peak-discharge","tr":"tepe debisi","en":"peak discharge","kisa":"Qp","tur":"olcu","es":["tepe akımı","I tasarım şiddeti ile Qp = CIA/360","doruk debisi","maksimum debi","peak flow","doruk akımı"],"tanim":["Belirli bir hidrolojik olay sırasında akarsu kesitinden geçen en yüksek anlık akım debisi.","Hidrografta tepe noktasının ordinatını oluşturur; m³/s ya da cfs birimiyle ifade edilir.","Rasyonel yöntemde küçük havzaların tasarım debisi olarak hesaplanır ve hidrolik yapıların boyutlandırılmasında temel alınır."],"tanim_en":"Maximum instantaneous discharge of a given stream for a specific hydrologic event as shown on a hydrograph.","bag":{"kavram":["rasyonel","hidrograf","birim-hidrograf"],"soru":["S30","S32","S33"],"hesap":["rasyonel","rasyonel-idf","rasyonel-ing","idf-ab"]}},{"id":"weighted-runoff-coefficient","tr":"ağırlıklı akış katsayısı","en":"weighted runoff coefficient","kisa":"C̄","tur":"olcu","es":["ortalama akış katsayısı","composite runoff coefficient","C̄","bileşik akış katsayısı","alan ağırlıklı C"],"tanim":["Farklı arazi örtüsü ve geçirimsizlik özelliklerine sahip kompozit bir havzada, her alt alanın kendi akış katsayısıyla alan ağırlıklı ortalaması alınarak türetilen tekil katsayıdır.","Boyutsuz olup 0 ile 1 aralığında değer alır; bağıntısı C̄ = Σ(Aᵢ·Cᵢ) / ΣAᵢ biçiminde hesaplanır.","Rasyonel yöntemde karma arazi yapısına sahip havzaların tek bir tepe debisi hesabı altında modellenmesini sağlar."],"tanim_en":"An area-weighted average runoff coefficient used in the rational method for catchments with mixed land use.","bag":{"kavram":["rasyonel"],"soru":["S32"],"hesap":["rasyonel-idf","rasyonel","rasyonel-ing"]}},{"id":"antecedent-moisture-condition","tr":"önceki nem durumu (öncül nem)","en":"antecedent moisture condition","kisa":"AMC","tur":"kavram","es":["AMC II","wet antecedent conditions","öncül nem koşulu","AMC","öncül nem"],"tanim":["Yağış fırtınası başlamadan hemen önce havza toprağının içerdiği nem düzeyidir.","SCS yönteminde son 5 günlük yağış toplamına göre kuru (AMC I), normal (AMC II) ve ıslak (AMC III) olmak üzere üç sınıfa ayrılır.","Havzanın eğri numarasını (CN) belirlemede ve akışa geçecek yağış payını hesaplamada temel girdidir."],"tanim_en":"Degree of wetness or moisture content of a catchment prior to a precipitation event.","bag":{"kavram":["scs-cn"],"soru":[],"hesap":[]}},{"id":"land-cover","tr":"arazi örtüsü","en":"land cover","kisa":"","tur":"kavram","es":["land cover change","land use and land cover","arazi kullanımı","örtü tipi"],"tanim":["Yeryüzünü kaplayan bitki örtüsü, su kütleleri, çıplak kaya ve yapay yapıların fiziksel durumudur.","Hidrolojide sızma, tutulma ve yüzey pürüzlülüğü özelliklerini belirleyerek suyun akışa dönüşme oranını etkiler.","SCS-CN yönteminde toprak grubu ve öncül nem ile birlikte eğri numarasını (CN) belirleyen temel girdidir."],"tanim_en":"Physical material and vegetation covering the surface of the earth.","bag":{"kavram":["scs-cn"],"soru":["S41"],"hesap":[]}},{"id":"hydrologic-soil-group","tr":"hidrolojik toprak grubu (A–D)","en":"hydrologic soil group","kisa":"HSG","tur":"kod","es":["soil group A to D","HSG","toprak grubu","hidrolojik toprak sınıfı","kumlu toprak","Group A soil"],"tanim":["Toprakların derinlik, doku ve su iletim özelliklerine göre sızma ve akış potansiyeli bakımından A, B, C ve D olarak dört sınıfa ayrılmasıdır.","A grubu yüksek sızma kapasiteli kumlu toprakları, D grubu ise sızması çok düşük killi veya sığ toprakları gösterir.","SCS-CN yönteminde arazi örtüsüyle birleştirilerek havzanın CN değerini türetmek için kullanılır."],"tanim_en":"Classification of soils into four groups (A, B, C, D) based on their minimum infiltration rate and runoff potential.","bag":{"kavram":["scs-cn"],"soru":[],"hesap":[]}},{"id":"potential-maximum-retention","tr":"potansiyel en büyük tutma","en":"potential maximum retention","kisa":"S","tur":"olcu","es":["havza tutma kapasitesi","potansiyel tutma","potential maximum retention S","maximum potential retention","S parametresi","tutma parametresi"],"tanim":["Yağış anında toprak profilinin ve zemin yüzeyinin tutabileceği teorik en büyük su derinliğidir.","SCS yönteminde eğri numarasına bağlı olarak S = (25400 / CN) − 254 formülüyle milimetre cinsinden hesaplanır.","Havzanın başlangıç kaybını ve akışa geçmeyen tutulma kapasitesini belirler."],"tanim_en":"Theoretical maximum capacity of a catchment to retain water through infiltration and surface storage during a storm.","bag":{"kavram":["scs-cn"],"soru":[],"hesap":["scs-cn"]}},{"id":"hydrologic-loss","tr":"kayıp (hidrolojik)","en":"hydrologic loss (abstraction)","kisa":"L","tur":"surec","es":["loss method","loss rate","infiltration loss","yağış kaybı","total storm loss","toplam kayıp derinliği"],"tanim":["Toplam yağışın sızma, tutulma ve yüzey çukurlarında birikme yoluyla doğrudan yüzey akışına katılmayan bölümüdür.","Yağış hiyetografından kayıplar çıkarıldığında net akışı oluşturan fazla yağış hiyetografı elde edilir.","HEC-HMS modelinde SCS-CN, φ-indeksi veya Initial and Constant gibi yöntemlerle hesaplanır."],"tanim_en":"Portion of total precipitation failing to become direct runoff due to interception, infiltration, and depression storage.","bag":{"kavram":["scs-cn","phi-indeksi","ic-kayip"],"soru":["S5","S31","S34","S42"],"hesap":["ic-kayip","phi-deneme"]}},{"id":"aquifer","tr":"Akifer","en":"Aquifer","kisa":"","tur":"kavram","es":["confined aquifer","unconfined aquifer","su taşıyan formasyon","su taşıyan katman"],"tanim":["İşletilebilir miktarda suyu depolayabilen, iletebilen ve kuyulara ya da kaynaklara veren jeolojik formasyondur.","Yağış olmayan kurak dönemlerde dere yataklarına yavaş ve sürekli su vererek taban akışını besler.","Hidrolojide doğrusal bir yeraltı haznesi olarak modellenir ve çekilme eğrisi üstel azalmayla temsil edilir."],"tanim_en":"Geological formation capable of storing, transmitting, and yielding exploitable quantities of water.","bag":{"kavram":["su-butcesi","taban-akisi"],"soru":["S5"],"hesap":[]}},{"id":"catchment","tr":"havza","en":"catchment (drainage basin, watershed)","kisa":"","tur":"kavram","es":["drainage basin","watershed","su toplama havzası","akaçlama havzası"],"tanim":["Yüzey akışını ortak tek bir çıkış noktasına doğru akaçlayan yüzey alanıdır.","Sınırları topoğrafik su ayrım çizgisiyle belirlenir ve hidrolojik su bütçesi hesaplarının temel kontrol hacmini oluşturur.","Karstik arazilerde yer altı su ayrımı topoğrafik sınırdan sapabilir ve bütçe dengesini değiştirebilir."],"tanim_en":"Area having a common outlet for its surface runoff.","bag":{"kavram":["su-butcesi","gis-havza","thiessen"],"soru":["S1","S2","S4","S10","S11","S12"],"hesap":["uzun-donem-et","havza-butcesi","akis-derinlik","thiessen"]}},{"id":"closed-basin","tr":"Kapalı havza","en":"Closed basin","kisa":"","tur":"kavram","es":["doğal kapalı havza","endorheic basin"],"tanim":["Yüzey sularının açık deniz veya okyanuslara ulaşmayıp kapalı göllerde ya da çöküntü alanlarında toplandığı endoreik akaçlama alanıdır.","Dışarıya yüzeysel akarsu çıkışı bulunmadığından giren su kütlesi yalnızca buharlaşma ve yer altı sızmasıyla uzaklaşır.","Su bütçesinde yüzey akışı çıkış terimi sıfır alınarak denge buharlaşma ve depo değişimi üzerinden kurulur."],"tanim_en":"Catchment area in which surface drainage collects in sinks or terminal lakes without any outflow to the ocean.","bag":{"kavram":["su-butcesi"],"soru":[],"hesap":[]}},{"id":"control-volume","tr":"Kontrol hacmi","en":"Control volume","kisa":"CV","tur":"kavram","es":["denetim hacmi","bütçe sınırı","hidrolojik kontrol hacmi","Hidrolojik kontrol hacmi","Hydrologic control volume"],"tanim":["Kütle ve enerji dengelerinin incelendiği, sınırlarından madde ve akı geçişine açık uzaysal bölgedir.","Hidrolojide havza sınırları, baraj hazneleri veya toprak tabakaları için bütçe korunum denklemlerinin uygulandığı temel hacimdir.","Giren akılar ile çıkan akıların farkı kontrol hacmi içindeki depolama değişimine eşittir."],"tanim_en":"Fixed region in space selected for hydrologic water balance calculation.","bag":{"kavram":["su-butcesi","hazne"],"soru":[],"hesap":[]}},{"id":"drainage-divide","tr":"Su ayrım çizgisi","en":"Drainage divide","kisa":"","tur":"kavram","es":["topographic divide","water divide","havza sınırı","watershed divide","su bölümü çizgisi","su ayrımı"],"tanim":["Komşu drenaj havzalarını birbirinden ayıran ve yüzeysel akışı farklı akarsu kollarına paylaştıran sırt çizgisi.","Sayısal yükseklik modelinde en dik iniş yönlerini belirleyen D8 akış yönü algoritması ve topoğrafik tepe noktaları izlenerek elde edilir.","Kitapta hidrolojik su bütçesi kontrol hacminin yüzey sınırını tanımlar; Thiessen ve izohiyet yöntemlerinde yağış alanını kapatır."],"tanim_en":"A drainage divide is a ridge or boundary line separating adjacent drainage basins.","bag":{"kavram":["su-butcesi","gis-havza"],"soru":[],"hesap":[]}},{"id":"drought","tr":"kuraklık","en":"drought","kisa":"","tur":"kavram","es":["hidrolojik kuraklık","meteorolojik kuraklık","tarımsal kuraklık","water deficit"],"tanim":["Yağışın uzun süre belirgin biçimde normalin altında kalması sonucu ciddi hidrolojik dengesizliğe yol açan doğal olay.","Yağış açığıyla başlayan meteorolojik evre, toprak neminin tükenmesiyle tarımsal, akarsu ve yeraltı suyunun azalmasıyla hidrolojik evreye dönüşür.","Kitapta su bütçesinde yağış girdisinin düşmesi ve depolamanın sürekli boşalması bağlamında incelenir."],"tanim_en":"Drought is a prolonged absence or marked deficiency of precipitation leading to hydrological deficit.","bag":{"kavram":["su-butcesi"],"soru":[],"hesap":[]}},{"id":"drought-management","tr":"Kuraklık yönetimi","en":"Drought management","kisa":"","tur":"kavram","es":["kuraklık kontrolü","kuraklık planlaması","drought mitigation","drought preparedness"],"tanim":["Kuraklık durumlarına ve su kıtlığı riskine karşı uygulanan teknik, idari, yasal ve ekonomik önlemler bütünü.","İzleme indisleri (SPI, PDSI), erken uyarı sistemleri, hazneler arası su aktarımı ve kademeli su kullanım kısıtlamalarıyla yürütülür.","Kitapta su bütçesi bileşenlerinin kurak dönemlerde tükenmesini engellemek ve baraj depolamasını korumak amacıyla ele alınır."],"tanim_en":"Drought management involves technical and institutional actions taken to mitigate drought impact.","bag":{"kavram":["su-butcesi"],"soru":[],"hesap":[]}},{"id":"groundwater","tr":"Yeraltı suyu","en":"Groundwater","kisa":"G","tur":"kavram","es":["groundwater storage","groundwater recharge","taban suyu","yeraltı akımı","groundwater table","net yeraltı akısı"],"tanim":["Yeraltında su tablasının altında kalan doygun bölgedeki gözenek ve kayaç çatlaklarını dolduran su.","Topraktan derine süzülme (perkolasyon) ile beslenir; akiferlerde birikir ve akarsulara taban akışı olarak drene olur.","Kitapta su bütçesi denklemindeki tek çift işaretli terim (±G) ve doğrusal hazne çekilmesini besleyen ana kaynaktır."],"tanim_en":"Groundwater is subsurface water occupying the saturated zone of an aquifer.","bag":{"kavram":["su-butcesi","taban-akisi","hazne"],"soru":["S2","S5"],"hesap":[]}},{"id":"karst","tr":"Karst","en":"Karst","kisa":"","tur":"kavram","es":["kireçtaşı havza","karstik akifer","karstik arazi","karst topography"],"tanim":["Kireçtaşı, jips ve dolomit gibi eriyebilen kayaçların yeraltı sularınca çözünmesiyle oluşan düden, mağara ve obruk gibi yapılar içeren arazi.","Yüzey akışının çatlak ve düdenlerden hızla yeraltına süzülmesi ve karmaşık yeraltı kanallarından akmasıyla karakterizedir.","Kitapta topoğrafik havza sınırları ile hidrolojik yeraltı havzası sınırlarının örtüşmediği ve su bütçesinin standart biçimde kapanmadığı özel durum olarak işlenir."],"tanim_en":"Karst is a terrain formed by the dissolution of soluble rock, characterized by sinkholes and subterranean drainage.","bag":{"kavram":["su-butcesi"],"soru":[],"hesap":[]}},{"id":"soil-moisture","tr":"Toprak nemi","en":"Soil moisture","kisa":"SM","tur":"kavram","es":["soil moisture deficit","antecedent soil moisture","toprak suyu","toprak su içeriği","soil water content","toprak nem açığı"],"tanim":["Su tablasının üzerindeki doymamış (havalanma) zonunda toprak gözeneklerinde kılcallıkla tutulan su ve su buharı.","Graviteye karşı tutulur; tarla kapasitesi ile solma noktası arasındaki miktar bitkilerce terleme amacıyla tüketilir.","Kitapta su bütçesinin depolama teriminin dinamik bir parçasını oluşturur; sızma hızını ve yüzey akışının başlama anını denetler."],"tanim_en":"Soil moisture is water contained in the portion of soil above the water table, including water vapour in soil pores.","bag":{"kavram":["su-butcesi","su-yolu","akis-mekanizma"],"soru":["S2","S5","S29"],"hesap":[]}},{"id":"stomata","tr":"Stoma","en":"Stomata","kisa":"","tur":"kavram","es":["stomata açıklıkları","yaprak gözenekleri","stomatae","stoma açıklıkları","stoma gözenekleri"],"tanim":["Bitki yapraklarının ve yeşil gövdelerinin epidermis tabakasında yer alan, gaz alışverişini ve terlemeyi düzenleyen mikroskobik gözenekler.","Kilit hücrelerinin turgor basıncıyla kontrol edilir; ışık, bağıl nem ve su stresine göre açılıp kapanarak yüzey direncini ayarlar.","Kitapta su bütçesi çıktılarından biri olan terleme akısının bitkisel kontrol mekanizması olarak geçer."],"tanim_en":"Stomata are microscopic openings on plant leaves that regulate transpiration and gas exchange.","bag":{"kavram":["su-butcesi"],"soru":[],"hesap":[]}},{"id":"topographic-basin","tr":"topoğrafik ve hidrolojik havza","en":"topographic vs hydrologic (groundwater) basin","kisa":"","tur":"kavram","es":["yüzey topoğrafya sınırı","yeraltı su havzası","Hidrolojik havza","Hydrologic basin","topoğrafik havza"],"tanim":["Topoğrafik havza yüzey sırt çizgisiyle sınırlanan drenaj alanıdır; hidrolojik havza ise yeraltı suyu akış yönlerinin belirlediği beslenme alanıdır.","Genellikle iki sınır birbiriyle örtüşür ancak eğimli tabakalı veya karstik yapılarda yeraltı su tablası yüzey su ayrım çizgisini kesebilir.","Kitapta kireçtaşı arazilerde topoğrafik havza ile hidrolojik havzanın çakışmaması ve bu nedenle su bütçesinin kapanmaması bağlamında incelenir."],"tanim_en":"A topographic basin is bounded by surface divide lines whereas a hydrologic basin is defined by groundwater flow.","bag":{"kavram":["su-butcesi","gis-havza"],"soru":[],"hesap":[]}},{"id":"global-precipitation-climatology-project","tr":"Küresel Yağış Klimatolojisi Projesi","en":"Global Precipitation Climatology Project","kisa":"GPCP","tur":"kod","es":["GPCP veri seti","GPCP","GPCP yağış analizi"],"tanim":["Dünya İklim Araştırma Programı (WCRP) çatısı altında uydu ve yer yağışölçer verilerini birleştirerek küresel yağış haritaları üreten proje.","Mikrodalga ve kızılötesi uydu gözlemleri ile istasyon verilerini bir araya getirerek 1979'dan günümüze küresel ızgara yağış alanları üretir.","Kitapta yerküre su bütçesi bileşenlerinin ve atmosferik su buharı taşınımının küresel ölçekte değerlendirilmesinde temel veri kaynağıdır."],"tanim_en":"The Global Precipitation Climatology Project provides merged satellite and rain gauge precipitation data on a global scale.","bag":{"kavram":["su-butcesi","pw"],"soru":[],"hesap":[]}},{"id":"actual-evapotranspiration","tr":"gerçek evapotranspirasyon","en":"Actual evapotranspiration","kisa":"ETa","tur":"olcu","es":["fiili buharlaşma","actual ET","gerçek buharlaşma ve terleme","ETa"],"tanim":["Belirli bir arazi yüzeyinde ve mevcut toprak nemi koşullarında topraktan ve bitki örtüsünden atmosfere fiilen aktarılan su buharı miktarı.","Birimi mm/gün veya mm/yıl olup lizimetre, girdap kovaryansı ya da su bütçesi artık terimi olarak hesaplanır.","Kitapta su bütçesinin ölçülmesi en zor çıktısı olarak tanımlanır; toprak nemi azaldığında potansiyel değerin oldukça altına iner."],"tanim_en":"Actual evapotranspiration is the quantity of water vapour evaporated from the soil and plants under existing moisture conditions.","bag":{"kavram":["su-butcesi","tava"],"soru":[],"hesap":["uzun-donem-et","havza-butcesi","kalis-suresi","hazne-ay"]}},{"id":"evaporation","tr":"buharlaşma","en":"evaporation","kisa":"E","tur":"surec","es":["lake evaporation","pan evaporation","açık su buharlaşması","buharlaşma derinliği","open-water evaporation","evaporasyon"],"tanim":["Suyun kaynama noktasının altındaki sıcaklıkta sıvı fazdan buhar fazına dönüşmesi.","Birimi genellikle mm ya da mm/gün olup buharlaşma tavası veya kütle transferi bağıntılarıyla belirlenir.","Havza su bütçesinde temel çıktı bileşenlerinden biridir ve atmosferdeki su buharının ana kaynağını oluşturur."],"tanim_en":"Process by which liquid water transforms into water vapour at temperatures below boiling point.","bag":{"kavram":["su-butcesi","tava","harbeck"],"soru":["S1","S2","S3","S25","S26","S27"],"hesap":["uzun-donem-et","havza-butcesi","hazne","hazne-ay"]}},{"id":"evapotranspiration","tr":"buharlaşma + terleme (evapotranspirasyon)","en":"evapotranspiration","kisa":"ET","tur":"surec","es":["buharlaşma ve terleme","actual evapotranspiration","potential evapotranspiration","potansiyel ET","buharlaşma-terleme","evapotranspirasyon"],"tanim":["Toprak ve açık yüzeylerden buharlaşma ile bitki örtüsünden terleme yoluyla atmosfere su transferinin birleşik süreci.","Birimi mm ya da mm/yıl olup havza su bütçesinde doğrudan ölçülmesi en zor terimdir.","Yıllık su bütçesinde depolama değişimi sıfıra yaklaştığında yağış ile akış arasındaki fark olarak hesaplanır."],"tanim_en":"Combined process by which water is transferred to the atmosphere from the soil by evaporation and from vegetation by transpiration.","bag":{"kavram":["su-butcesi","tava"],"soru":["S1","S2","S3","S27","S29"],"hesap":["uzun-donem-et","havza-butcesi"]}},{"id":"hydrologic-cycle","tr":"hidrolojik döngü (su döngüsü)","en":"hydrologic cycle (water cycle)","kisa":"","tur":"surec","es":["su döngüsü","water cycle","hidrolojik döngü","hydrologic cycle","Su döngüsü","Water cycle"],"tanim":["Suyun atmosferden yeryüzüne inmesi ve buharlaşma, yoğuşma, yağış, sızma ve akış gibi aşamalardan geçerek yeniden atmosfere dönmesi süreci.","Atmosferdeki suyun ortalama kalış süresi yaklaşık 9 gün olup küresel döngüde su sürekli hareket eder.","Hidrometeoroloji ve havza su bütçesi denklemlerinin temel kavramsal çerçevesini oluşturur."],"tanim_en":"Continuous cycle in which water moves from the atmosphere to the Earth through precipitation and returns to the atmosphere through evaporation.","bag":{"kavram":["su-butcesi","kalis-suresi"],"soru":[],"hesap":[]}},{"id":"precipitation","tr":"yağış","en":"precipitation","kisa":"P","tur":"surec","es":["yağış derinliği","rainfall depth","yağış miktarı","yağmur"],"tanim":["Bulutlardan sıvı ya da katı halde yere düşen veya havadan yere çöken su buharı yoğuşma ve süblimleşme ürünleri.","Derinlik birimi mm cinsinden ölçülür; kar ve katı türler su eşdeğeri olarak ifade edilir.","Havza su bütçesinin ana girdisi olup yüzey akışını, sızmayı ve yeraltı suyu beslenimini başlatır."],"tanim_en":"Liquid or solid products of water vapour condensation falling from clouds or deposited from the atmosphere onto the ground.","bag":{"kavram":["su-butcesi","yagis-siddeti","akis-birim"],"soru":["S1","S2","S3","S4","S5","S6"],"hesap":["uzun-donem-et","havza-butcesi","kalis-suresi","akis-derinlik"]}},{"id":"streamflow","tr":"debi (akım)","en":"discharge (streamflow)","kisa":"Q","tur":"surec","es":["akım","river discharge","streamflow","nehir debisi","akarsu debisi"],"tanim":["Bir akarsu veya kanal kesitinden birim zamanda geçen su hacmi.","Birimi m³/s cinsindendir; havza alanına bölünerek akış derinliği (mm) karşılığı da ifade edilir.","Havza çıkışında hidrograf eğrisiyle izlenir; doğrudan akış ile taban akışının toplamından oluşur."],"tanim_en":"Volume of water flowing through a river or channel cross-section per unit time.","bag":{"kavram":["su-butcesi","hidrograf","akis-birim"],"soru":["S1","S2","S4","S26","S30","S32"],"hesap":["uzun-donem-et","havza-butcesi","akis-derinlik","cfs-m3s"]}},{"id":"sublimation","tr":"Süblimleşme","en":"Sublimation","kisa":"","tur":"surec","es":["kardan buharlaşma","buz süblimleşmesi","süblimasyon","katıdan buhara geçiş"],"tanim":["Suyun sıvı faza uğramadan doğrudan katı (buz veya kar) fazdan buhar fazına (ya da tersine) geçişi.","Kar örtüsü ve buzul alanlarından atmosfere su buharı transferinde soğuk, kuru ve rüzgârlı koşullarda önem taşır.","Hidrometeorolojide kar örtüsünün kütle kaybı hesaplarında buharlaşma terimi içinde ya da ayrı bir kayıp bileşeni olarak yer alır."],"tanim_en":"Direct transition of water from solid ice or snow into water vapour without entering the liquid state.","bag":{"kavram":["su-butcesi"],"soru":[],"hesap":[]}},{"id":"transpiration","tr":"terleme (transpirasyon)","en":"transpiration","kisa":"T","tur":"surec","es":["transpirasyon","plant transpiration","bitki terlemesi","bitkisel terleme","terleme derinliği","T"],"tanim":["Bitkilerin kökleriyle topraktan aldığı suyun yaprak gözeneklerinden buhar halinde atmosfere iletilmesi süreci.","Birimi mm cinsinden olup hidrolojik döngüde bitki örtüsünün büyüme mevsiminde en yüksek değerine ulaşır.","Havza su bütçesinde buharlaşma ile birleştirilerek evapotranspirasyon (ET) terimi altında ele alınır."],"tanim_en":"Process by which water from vegetation is transferred into the atmosphere as vapour.","bag":{"kavram":["su-butcesi","tava"],"soru":["S1"],"hesap":["uzun-donem-et","havza-butcesi"]}},{"id":"depression-storage","tr":"Çukur depolaması","en":"Depression storage","kisa":"Ds","tur":"kavram","es":["surface depression storage","yüzey çukuru depolaması","yüzey çukur depolaması","yüzey çukur kaybı","arazi çukur depolaması","Yüzey çukur tutması"],"tanim":["Yere ulaşan yağış suyunun zemin eğimindeki çukurluklarda ve mikro engebelerde birikerek tutulması.","Birimi mm cinsinden olup düz tarım arazilerinde büyük (tipik 1–5 mm), geçirimsiz beton yüzeylerde ise sıfıra yakındır.","Yağışın akışa dönüşümünde tutulmadan sonraki aşamayı oluşturur; çukurlar dolmadan ve başlangıç kaybı aşılmadan yüzey akışı başlamaz."],"tanim_en":"Water from precipitation trapped in small ground depressions and irregularities before surface runoff begins.","bag":{"kavram":["su-yolu","ic-kayip"],"soru":["S5"],"hesap":[]}},{"id":"water-table","tr":"Yeraltı su tablası","en":"Water table","kisa":"","tur":"kavram","es":["serbest su düzeyi","freatik yüzey","groundwater table","yeraltı su seviyesi","Su tablası","su tablası"],"tanim":["Doymamış üst toprak katmanı ile doymuş alt katmanı ayıran ve hidrostatik basıncın atmosfer basıncına eşit olduğu yüzey.","Yağış sızmasıyla yükselir, kurak dönemde akarsu taban akışını besleyerek veya derin süzülmeyle alçalır.","Dunne mekanizmasında su tablası yüzeye ulaştığında toprak alttan doyar ve zayıf yağışlar bile doğrudan akış üretir."],"tanim_en":"The surface separating the upper layer of non-saturated soil and the lower layer of saturated soil.","bag":{"kavram":["su-yolu","taban-akisi","akis-mekanizma"],"soru":[],"hesap":[]}},{"id":"direct-runoff","tr":"Doğrudan akış","en":"Direct runoff","kisa":"Pe","tur":"surec","es":["fırtına akışı","fazla yağış akışı","net akış","artık yağış","direct runoff depth","doğrudan akış debisi"],"tanim":["Yağış olayının ardından gecikme olmaksızın akarsu yatağına ulaşan ve yüzey akışı ile hızlı ara akıştan oluşan su akımı.","Birimi derinlik olarak mm veya debi olarak m³/s cinsindendir; hidrograftan taban akışı çıkarılarak hesaplanır.","Taşkın hidrografı analizinde, birim hidrograf üretiminde ve akış katsayısı hesabında temel alınan bileşendir."],"tanim_en":"Water flow that enters a watercourse after precipitation without delay.","bag":{"kavram":["su-yolu","akis-birim","phi-indeksi"],"soru":["S26","S30","S41","S42","S43"],"hesap":["hidrograf","phi-deneme"]}},{"id":"interflow","tr":"Ara akış","en":"Interflow","kisa":"","tur":"surec","es":["subsurface stormflow","throughflow","yanal akış","yüzey altı akışı","interflow","yüzeyaltı fırtına akışı"],"tanim":["Toprağa sızan suyun yeraltı su tablasına ulaşmadan, yüzeyin altındaki üst katmanlarda yanal hareket ederek akarsu yatağına boşalan bölümü.","Akış hızı yüzey akışından yavaş, taban akışından hızlıdır; fırtına sırasında geçici doygunluk kuşaklarından kaynaklanır.","Hidrografta tepe noktasından hemen sonraki çekilme kolunda yer alır ve gecikmeli doğrudan akış bileşenini oluşturur."],"tanim_en":"Portion of precipitation that infiltrates the soil and discharges into stream channels as lateral subsurface flow without reaching the regional water table.","bag":{"kavram":["su-yolu","hidrograf","akis-mekanizma"],"soru":["S5"],"hesap":[]}},{"id":"percolation","tr":"Derine süzülme","en":"Percolation","kisa":"","tur":"surec","es":["perkolasyon","deep percolation","akifere süzülme"],"tanim":["Suyun doymamış gözenekli ortamda veya toprak profilinde yerçekimi etkisiyle aşağı doğru düşey hareketi.","Toprağın tarla kapasitesini aşan sızıntı suyunun kök bölgesinden geçerek doymuş bölgeye ve akifere ulaşmasını sağlar.","Yağışın su bütçesinde yüzey sızmasından sonraki aşamayı oluşturur ve yeraltı suyu besleniminin temel mekanizmasıdır."],"tanim_en":"Downward flow of water through an unsaturated porous medium or soil layer under the force of gravity toward the water table.","bag":{"kavram":["su-yolu","su-butcesi","akis-mekanizma"],"soru":["S5"],"hesap":[]}},{"id":"snowmelt","tr":"Kar erimesi","en":"Snowmelt","kisa":"","tur":"surec","es":["kar erime suyu","snowmelt runoff"],"tanim":["Kar örtüsünün termal enerji alarak katı fazdan sıvı suya dönüşmesi veya bu dönüşümle açığa çıkan su.","Hava sıcaklığı, güneş radyasyonu, rüzgâr ve yoğuşma gizli ısısı etkisiyle gerçekleşir; derece-gün yöntemi veya enerji bütçesiyle hesaplanır.","Havza su bütçesinde ilkbahar akışlarını belirler ve taşkın hidrograflarında gecikmeli tepe debilerine yol açar."],"tanim_en":"Transformation of snow into liquid water or the runoff produced by melting.","bag":{"kavram":["su-yolu","su-butcesi"],"soru":[],"hesap":[]}},{"id":"confined-aquifer","tr":"Basınçlı akifer","en":"Confined aquifer","kisa":"","tur":"kavram","es":["tazyikli akifer","artesian aquifer"],"tanim":["Üstten ve alttan geçirimsiz veya yarı geçirimsiz jeolojik formasyonlarla sınırlandırılmış yeraltı suyu tabakası.","İçindeki suyun basıncı atmosfer basıncından yüksek olup pyezometrik seviyesi akifer tavanının üzerinde yer alır.","Doğrusal hazne çekilmesinde akarsuyu uzun vadeli ve kararlı taban akışıyla besleyen derin yeraltı rezervuarıdır."],"tanim_en":"Aquifer bounded above and below by impermeable or semi-impermeable layers with water under hydrostatic pressure.","bag":{"kavram":["taban-akisi"],"soru":[],"hesap":[]}},{"id":"perennial-stream","tr":"sürekli (daimi) akarsu","en":"perennial stream","kisa":"","tur":"kavram","es":["daimi akarsu","yıl boyu akan dere"],"tanim":["Kurak mevsimler de dahil olmak üzere yıl boyunca kesintisiz olarak yüzey akımı taşıyan akarsu.","Yatak tabanı yeraltı su tablasının altında yer aldığından sürekli taban akışıyla beslenir.","Hidrografında hiçbir zaman sıfır debi görülmez; taban akışı ayrımında kalıcı akım bileşenini temsil eder."],"tanim_en":"Stream that flows continuously throughout the year because its bed lies below the water table.","bag":{"kavram":["taban-akisi","hidrograf"],"soru":[],"hesap":[]}},{"id":"unconfined-aquifer","tr":"Serbest akifer","en":"Unconfined aquifer","kisa":"","tur":"kavram","es":["serbest tabanlı akifer","phreatic aquifer"],"tanim":["Üst sınırı atmosfer basıncına açık serbest bir su tablasından oluşan geçirimli yeraltı suyu formasyonu.","Yağış sızması ve derine süzülmeyle doğrudan beslenir; su tablası mevsimsel su bütçesine göre serbestçe alçalıp yükselir.","Doğrusal hazne yaklaşımında derelerin taban akışını en hızlı ve doğrudan destekleyen ana akifer tipidir."],"tanim_en":"Aquifer containing an unconfined water table at atmospheric pressure that serves as its upper boundary.","bag":{"kavram":["taban-akisi"],"soru":[],"hesap":[]}},{"id":"half-life","tr":"yarılanma süresi","en":"half-life","kisa":"t1/2","tur":"olcu","es":["çekilme yarılanma süresi","half-life of recession"],"tanim":["Üstel azalan bir büyüklüğün (ör. çekilmedeki taban akışı) başlangıç değerinin yarısına inmesi için geçen süre.","Doğrusal haznede Q = Q₀·e^(−t/k) olduğundan t½ = k·ln 2 ≈ 0,693·k; kitap S36'daki k = 70 h için t½ ≈ 48,5 h.","Hazne sabiti büyük olan geniş akiferlerde yarılanma uzun sürer, kuyruk uzar. WMO sözlüğünde aynı terim radyoaktif bozunma için de kullanılır."],"tanim_en":"Time needed for an exponentially decaying quantity, such as baseflow during recession, to fall to half of its initial value; for a linear reservoir t½ = k ln 2.","bag":{"kavram":["taban-akisi"],"soru":[],"hesap":["taban-akisi"]}},{"id":"recession-constant","tr":"çekilme sabiti","en":"recession constant","kisa":"k","tur":"olcu","es":["taban akışı çekilme sabiti","baseflow recession constant","hazne sabiti","boşalma zaman sabiti","çekilme sabiti"],"tanim":["Doğrusal hazne çekilme modelinde taban akışının üstel azalma hızını belirleyen zaman sabiti.","Birimi genellikle saat veya gündür; t = k anında akarsu debisi başlangıçtaki Q₀ değerinin yaklaşık %36,8'ine (1/e) düşer.","Akiferin büyüklüğüne ve iletim kapasitesine bağlıdır; k büyüdükçe hidrolojik boşalma yavaşlar ve hidrograf kuyruğu uzar."],"tanim_en":"Time constant in the linear reservoir model governing the exponential decay rate of baseflow discharge.","bag":{"kavram":["taban-akisi","clark"],"soru":["S36"],"hesap":["taban-akisi","clark"]}},{"id":"sym-q0-baseflow","tr":"başlangıç debisi","en":"initial discharge","kisa":"Q₀","tur":"olcu","es":["initial baseflow","başlangıç debisi"],"tanim":["Çekilme döneminin başlangıç anında (t = 0) akarsu yatağında gözlenen veya modellenen ilk taban akışı debisi.","Birimi metreküp bölü saniyedir (m³/s); akifer boşalmasının başlangıç sınır koşulunu oluşturur.","Doğrusal hazne modelinde üstel azalma eğrisinin başlangıç genliğini tanımlar."],"tanim_en":"Initial baseflow discharge at the beginning of the recession period representing the starting condition for exponential decay.","bag":{"kavram":["taban-akisi"],"soru":["S36"],"hesap":["taban-akisi"]}},{"id":"aquifer-recharge","tr":"Akifer beslenimi","en":"Aquifer recharge","kisa":"","tur":"surec","es":["groundwater recharge","yeraltı suyu beslenmesi"],"tanim":["Suyun doğal süzülme ya da yapay yöntemlerle bir akiferin doymuş bölgesine girmesi ve depolanması süreci.","Yağış sızması, kar erimesi, yüzey suları ve derine süzülmeyle gerçekleşir; birimi milimetre/gün veya debi cinsindendir.","Havzanın yeraltı suyu rezervini yenileyerek kurak dönemde akarsulara sürekli taban akışı desteği sağlar."],"tanim_en":"Natural or artificial entry of water into the saturated zone of an aquifer to replenish groundwater storage.","bag":{"kavram":["taban-akisi","su-yolu"],"soru":[],"hesap":[]}},{"id":"unit-mm-d-1","tr":"milimetre/gün","en":"millimetres per day","kisa":"mm/gün","tur":"birim","es":["mm/gün","mm/day","milimetre bölü gün","mm d⁻¹"],"tanim":["Birim zamanda birim yatay alandan buharlaşan su derinliği hızı birimi.","Günde bir milimetre su kalınlığına karşılık gelir ve günlük hidrolojik akıları belirtir.","Kitapta tava buharlaşması ile göl buharlaşması hesaplarında günlük kayıp şiddetini m/yıl birimine çevirmede kullanılır."],"tanim_en":"A unit of rate expressing the depth of liquid water evaporated from a unit surface area in one day.","bag":{"kavram":["tava","harbeck","hazne"],"soru":["S25","S26","S27","S28","S29"],"hesap":[]}},{"id":"psychrometer","tr":"Psikrometre","en":"Psychrometer","kisa":"","tur":"cihaz","es":["ıslak kuru termometre","sling psychrometer"],"tanim":["Biri kuru, diğeri saf su veya ince ıslak bezle kaplı iki özdeş termometreden oluşan ve atmosfer nemini ölçen alet.","Islak haznenin buharlaşma yoluyla soğuması sonucu iki termometre arasındaki sıcaklık farkından buhar basıncı ve bağıl nem türetilir.","Kitapta hava sıcaklığı ve buhar basıncını belirleyerek açık su buharlaşması hesaplarına girdi sağlamada adı geçer."],"tanim_en":"An instrument used to measure atmospheric humidity, consisting of a dry-bulb and a wet-bulb thermometer.","bag":{"kavram":["tava","pw"],"soru":[],"hesap":[]}},{"id":"stilling-well","tr":"durgunlaştırma kuyusu","en":"stilling well","kisa":"","tur":"cihaz","es":["durgunluk tüpü","tava ölçüm kuyusu","ölçüm kuyusu"],"tanim":["Su tablasındaki dalgalanma ve çalkantıları sönümleyerek su seviyesinin hassas ölçülmesini sağlayan düşey kuyu düzeneği.","A sınıfı buharlaşma tavası içinde kancalı ölçer ile su yüzeyi seviyesini hatasız okumak için kullanılır.","Kitapta buharlaşma tavası donanımları arasında tavadaki su kaybını sakin ortamda belirleme aracı olarak geçer."],"tanim_en":"A vertical chamber designed to dampen water surface fluctuations for accurate water level measurement.","bag":{"kavram":["tava"],"soru":[],"hesap":[]}},{"id":"potential-evaporation","tr":"potansiyel buharlaşma / evapotranspirasyon (E₀, PET)","en":"potential evaporation (potential evapotranspiration)","kisa":"PET","tur":"olcu","es":["açık su buharlaşma potansiyeli","potential lake evaporation","tava potansiyeli","potansiyel ET","open water evaporation","potansiyel buharlaşma"],"tanim":["Su sınırı olmayan (sürekli ıslak) bir yüzeyden, o anki atmosfer koşullarında (ışınım, sıcaklık, nem, rüzgâr) olabilecek en büyük buharlaşma ya da evapotranspirasyon.","Mm/gün ya da mm/yıl ile verilir; açık su yüzeyi buharlaşması (tava × tava katsayısı), kütle transferi ya da Penman–Monteith gibi yöntemlerle kestirilir.","Gerçek evapotranspirasyon toprak nemiyle sınırlıdır; kurak dönemde potansiyelin çok altına iner."],"tanim_en":"The maximum quantity of water vapour that can evaporate from an unrestricted pure water surface under existing atmospheric conditions.","bag":{"kavram":["tava","gizli-isi","su-butcesi"],"soru":["S27"],"hesap":["uzun-donem-et","havza-butcesi","kalis-suresi","hazne-ay"]}},{"id":"open-water-evaporation","tr":"açık su (göl) buharlaşması","en":"open-water (lake) evaporation","kisa":"E","tur":"surec","es":["serbest yüzey buharlaşması","göl buharlaşması","göl yüzeyi buharlaşması","open-water evaporation","doğal göl buharlaşması","doğal su yüzeyi buharlaşması"],"tanim":["Göl, gölet, hazne ve açık su yüzeylerinden atmosfere aktarılan su buharı miktarı ve süreci.","Derinlik ve ısı depolama etkileri nedeniyle tava ölçümünden farklılık gösterir; tava katsayısı (Kp) veya kütle transferi formülleriyle hesaplanır.","Kitapta hazne su bütçesinde yaz aylarının en büyük su kaybı kalemi olarak yer alır."],"tanim_en":"The quantity of water vapour transferred to the atmosphere from an open lake or reservoir surface.","bag":{"kavram":["tava","harbeck","hazne"],"soru":["S26","S27","S28"],"hesap":["hazne"]}},{"id":"perpendicular-bisector","tr":"Orta dikme","en":"Perpendicular bisector","kisa":"","tur":"kavram","es":["kenar orta dikme","orta dikmeler","Kenar orta dikme"],"tanim":["Bir doğru parçasını tam orta noktasından dik olarak kesen ve üzerindeki her noktası doğru parçasının iki uç noktasına eşit uzaklıkta bulunan geometrik doğru.","Hidrolojide Thiessen çokgenlerinin kenarlarını oluşturmak için komşu yağış istasyonlarını birleştiren doğruların ortasından çizilir.","Kitapta havzayı en yakın ölçer etki alanlarına bölerek Thiessen alan ağırlıklarını kurmada temel geometrik yöntemdir."],"tanim_en":"A straight line perpendicular to a line segment at its midpoint, forming the equidistant boundary between two gauge locations.","bag":{"kavram":["thiessen"],"soru":[],"hesap":[]}},{"id":"point-rainfall","tr":"Nokta yağışı","en":"Point rainfall","kisa":"P_1d","tur":"kavram","es":["noktasal ölçüm","point measurement","noktasal yağış","istasyon yağışı","Noktasal yağış","point precipitation"],"tanim":["Belirli bir coğrafi noktada veya tek bir yağışölçer konumunda ölçülen toplam yağış derinliği.","Ölçüm birimi mm olup, alan ölçeğine genişletildiğinde noktasal temsil hatası barındırır.","Kitapta alansal ortalama yağış yöntemlerinin, IDF eğrilerinin ve dünya zarf eğrisi rekorlarının temel girdisini oluşturur."],"tanim_en":"The precipitation depth measured at a single geographic point or individual rain gauge over a given duration.","bag":{"kavram":["thiessen","izohiyet","horton-da"],"soru":["S21"],"hesap":[]}},{"id":"sym-station-rainfall","tr":"istasyon yağışı","en":"gauge rainfall","kisa":"Pᵢ","tur":"olcu","es":["ölçer yağışı","nokta yağış değeri","observed rainfall at neighbour","komşu yağış ölçümü","Pi","Pᵢ — komşu istasyonun gözlenen yağışı"],"tanim":["Belirli bir i numaralı gözlem istasyonunda veya yağışölçerinde ölçülen yağış derinliği değeri.","Birimi mm olup, standart bir ölçer kabında belirli bir zaman aralığında biriken su yüksekliğidir.","Kitapta Thiessen çokgenleri alan ağırlıklı ortalamasında ve normal oran yöntemiyle eksik veri tamamlamada temel değişken olarak yer alır."],"tanim_en":"The observed precipitation depth measured at a specific rainfall gauge i over a given duration.","bag":{"kavram":["thiessen","normal-oran"],"soru":[],"hesap":["thiessen","izohiyet","hidrograf","normal-oran"]}},{"id":"sym-subbasin-area","tr":"alt alan","en":"sub-area","kisa":"Aᵢ","tur":"olcu","es":["poligon alanı","şerit alanı","havza içi alan","Ai"],"tanim":["Bir havzanın Thiessen çokgeni veya iki ardışık izohiyet eğrisi arasında kalan parçasının yüzölçümü.","Genellikle km² birimiyle ifade edilir; dış istasyonların çokgenleri havza sınırıyla kesilerek yalnızca havza içi parçası hesaba katılır.","Kitapta alansal ortalama yağış hesabında istasyon veya şerit yağışlarına alan ağırlığı vermede pay terimi olarak kullanılır."],"tanim_en":"The surface area of an individual sub-zone or polygon partition located entirely within the catchment boundary.","bag":{"kavram":["thiessen","izohiyet"],"soru":["S10","S11"],"hesap":["thiessen","izohiyet","olcer-dagitim"]}},{"id":"area-weighted-average","tr":"Alan ağırlıklı ortalama","en":"Area-weighted average","kisa":"w_i","tur":"yontem","es":["ağırlıklı ortalama","weighted average","alan ağırlık faktörü","Thiessen ağırlığı","Thiessen weight","Alan ağırlığı"],"tanim":["Bir havzadaki noktasal değerlerin, temsil ettikleri alt alanların toplam alana oranıyla ağırlıklandırılarak birleştirildiği istatistiksel ortalama yöntemi.","Her alt parçanın alanı toplam alana bölünerek ağırlık katsayısı (Aᵢ / ΣAᵢ) bulunur ve ağırlıkların toplamı 1 değerini verir.","Kitapta Thiessen ve izohiyet yöntemleriyle havza ortalama yağışını belirlemede ve karma arazilerde tek bir akış katsayısı türetmede kullanılır."],"tanim_en":"A method of computing a representative spatial mean by weighting local values in proportion to their respective sub-areas.","bag":{"kavram":["thiessen","izohiyet"],"soru":["S32"],"hesap":["thiessen","izohiyet"]}},{"id":"gage-weights","tr":"Ölçer ağırlıkları","en":"Gage weights","kisa":"","tur":"yontem","es":["istasyon ağırlıkları","HEC-HMS gage weights","gauge weights","yağışölçer ağırlıkları"],"tanim":["Bir havzadaki farklı yağış ölçerlerin alansal temsil payını belirten boyutsuz katsayılardır.","Her istasyonun temsil ettiği alanın havza toplam alanına oranıyla hesaplanır ve katsayılar toplamı 1,0 değerine eşittir.","Kitapta Thiessen çokgenleri yöntemiyle ve HEC-HMS meteorolojik modelinde alt havza yağışını ağırlıklandırmak için kullanılır."],"tanim_en":"Coefficients that define the spatial contribution of individual precipitation gauges to a catchment.","bag":{"kavram":["thiessen","hec-hms"],"soru":[],"hesap":["cfs-m3s","thiessen","izohiyet"]}},{"id":"unit-cm-per-hour","tr":"santimetre/saat","en":"centimetres per hour","kisa":"cm/h","tur":"birim","es":["cm/h","cm/hr","cm/saat","Santimetre bölü saat","Centimeters per hour","cm/hr — santimetre bölü saat"],"tanim":["Birim zamanda yüzeye düşen yağış derinliğini santimetre cinsinden ifade eden hidrolojik şiddet birimidir.","1 cm/h değeri 10 mm/h değerine eşittir; hidrolojik hesaplarda yağış ve sızma hızlarını sınıflandırmada kullanılır.","Kitapta yağış şiddeti sınıflamasında eşik birim olarak geçer: 0,5 cm/h altı düşük, 0,5–2,5 cm/h arası orta, 2,5 cm/h üzeri yüksek şiddettir."],"tanim_en":"A metric unit of rainfall intensity expressing the depth of water accumulated per hour in centimetres.","bag":{"kavram":["yagis-siddeti","zarf","idf"],"soru":["S9","S21"],"hesap":["yagis-siddeti"]}},{"id":"unit-mm-per-hour","tr":"milimetre/saat","en":"millimetres per hour","kisa":"mm/h","tur":"birim","es":["mm/h","mm/hr","mm/saat","millimeters per hour","mm per hour","milimetre bölü saat"],"tanim":["Bir saatte birim alana düşen yağış derinliğini milimetre cinsinden veren standart hidrolojik yağış şiddeti birimidir.","Yağış ölçerlerden elde edilen derinliğin süreye bölünmesiyle veya radar yansıtıcılık bağıntılarıyla doğrudan hesaplanır.","Kitapta radar Z–R bağıntılarında (RR), IDF eğrilerinde, rasyonel yöntemde ve kayıp analizlerinde temel şiddet birimidir."],"tanim_en":"A standard unit of rainfall intensity representing the depth of precipitation falling per hour in millimetres.","bag":{"kavram":["yagis-siddeti","zr","idf"],"soru":["S6","S7","S9","S16","S17","S30"],"hesap":["rasyonel"]}},{"id":"rain-gauge","tr":"Yağış ölçeri","en":"Rain gauge","kisa":"","tur":"cihaz","es":["plüviyometre","yağış istasyonu","pluviometer","yağış ölçeği","yağış ölçer","raingage"],"tanim":["Belirli bir noktaya düşen yağışın su derinliğini ölçmek için kullanılan standart alettir.","Toplama hunisi ve dereceli ölçüm silindirinden oluşur; ABD standart ölçeri 203 mm (8 inç) ağız çapına sahiptir.","Kitapta nokta yağış verisi toplama, Thiessen çokgenleri ile havza ortalaması alma ve optimum ölçüm ağı yoğunluğunu belirleme konularında temel gözlem aracıdır."],"tanim_en":"An instrument for measuring the depth of water from precipitation reaching the ground at a point.","bag":{"kavram":["yagis-siddeti","optimum-olcer","thiessen"],"soru":["S12","S13"],"hesap":["optimum-olcer"]}},{"id":"tipping-bucket-rain-gauge","tr":"Devrilen kovalı yağış ölçeri","en":"Tipping-bucket rain gauge","kisa":"","tur":"cihaz","es":["yazıcı yağış ölçer","devirmeli plüviyograf","tipping bucket gauge","otomatik yağışölçer","devirmeli yağışölçer"],"tanim":["Yağış suyunu küçük iki bölmeli bir terazi mekanizmasına toplayarak yağış miktarını ve zaman dağılımını ölçen alettir.","Her kova dolduğunda devrilir; her bir devrilme WMO standardına göre 0,2 mm (ABD uygulamasında 0,01 inç) yağışa karşılık gelir.","Kitapta yağış şiddetinin ve zamanla biriken kütle eğrilerinin elde edilmesinde temel otomatik ölçüm cihazı olarak ele alınır."],"tanim_en":"A rainfall measuring instrument where a small bucket tips and empties alternately for each calibrated increment of precipitation.","bag":{"kavram":["yagis-siddeti"],"soru":[],"hesap":[]}},{"id":"convective-cloud","tr":"konvektif bulut ve konvektif yağış","en":"convective cloud and convective precipitation","kisa":"","tur":"kavram","es":["kümülüs bulutu","konveksiyon bulutu","konvektif hareketler","düşey konveksiyon","Konvektif hava hareketleri","Convective air motions"],"tanim":["Güneşle ısınan nemli havanın atmosferik kararsızlık sonucu düşey olarak yükselmesi ve soğuyarak yoğunlaşmasıyla oluşan bulut ve bu buluttan düşen yağıştır.","Kümülüs veya kümülonimbus yapısında gelişir; kısa süreli, dar alanda etkili ve yüksek şiddetli sağanaklar üretir.","Kitapta yerel ani taşkınlara zemin hazırlayan yüksek şiddetli yağış mekanizması olarak incelenir."],"tanim_en":"A cloud and resulting precipitation formed by vertical thermal convection of unstable moist air.","bag":{"kavram":["yagis-siddeti"],"soru":[],"hesap":[]}},{"id":"mass-curve","tr":"yağış kütle eğrisi (birikimli yağış)","en":"rainfall mass curve","kisa":"","tur":"kavram","es":["birikimli yağış eğrisi","cumulative rainfall curve","birikimli toplam","accumulated rainfall","birikimli yağış","cumulative rainfall"],"tanim":["Başlangıç anından itibaren biriken toplam yağış derinliğinin zamana bağlı değişimini gösteren birikimli grafiktir.","Eğrinin herhangi bir noktadaki teğetinin eğimi, o andaki yağış şiddetini verir; sabit şiddette doğru çizgisi oluşturur.","Kitapta fırtına içi şiddet değişimini izlemede, sızma kayıplarının hesaplanmasında ve çift kütle analiziyle istasyon tutarlılığını denetlemede kullanılır."],"tanim_en":"A graphic representation of cumulative rainfall plotted against time.","bag":{"kavram":["yagis-siddeti","cift-kutle"],"soru":["S34"],"hesap":[]}},{"id":"severe-thunderstorm","tr":"Şiddetli oraj","en":"Severe thunderstorm","kisa":"","tur":"kavram","es":["gök gürültülü fırtına","şiddetli fırtına","gök gürültülü sağanak","severe storm"],"tanim":["Şimşek, gök gürültüsü, şiddetli sağanak, büyük çaplı dolu veya yıkıcı rüzgâr hamleleri üreten güçlü konvektif fırtınadır.","AMS ve WMO ölçütlerine göre en az 2 cm veya 5 mm üzeri çaplı dolu ve yüksek rüzgâr hamlesi üreten fırtınalar bu sınıfa girer.","Kitapta kısa süreli en yüksek yağış şiddetlerini ve ani havza taşkınlarını tetikleyen aşırı hava olayı olarak geçer."],"tanim_en":"An intense convective storm accompanied by lightning, thunder, high winds, and heavy precipitation or large hail.","bag":{"kavram":["yagis-siddeti"],"soru":[],"hesap":[]}},{"id":"snow","tr":"Kar","en":"Snow","kisa":"","tur":"kavram","es":["kar yağışı","snowfall","buz kristalleri","kar kristalleri","hafif kar","kar serpintisi"],"tanim":["Atmosferden yeryüzüne düşen veya yerde gevşek bir örtü oluşturan dallanmış altıgen buz kristallerinden meydana gelen katı yağıştır.","Yoğunluğu taze karda yaklaşık 0,1 g/cm³ olarak kabul edilir; su eşdeğeri kar yastığı gibi aletlerle sıvı derinliğe çevrilerek ifade edilir.","Kitapta havza su bütçesinde yüzey depolama (S) bileşeni olarak yer alır ve eriyene kadar akışa geçmeyen gecikmeli su kaynağıdır."],"tanim_en":"Atmospheric precipitation of branched hexagonal ice crystals falling to the ground in solid form.","bag":{"kavram":["yagis-siddeti","zr"],"soru":["S3","S4","S5","S6","S12","S25"],"hesap":["kalis-suresi","cfs-m3s","hazne"]}},{"id":"supercooled-water","tr":"Aşırı soğumuş su","en":"Supercooled water","kisa":"","tur":"kavram","es":["aşırı soğuk su damlacıkları","aşırı soğumuş su damlaları","supercooled droplets"],"tanim":["Donma noktasının (0 °C) altına indiği halde kristalleşmeyip sıvı halde kalmayı sürdüren sudur.","Havada buz çekirdeği bulunmadığında eksi 40 °C seviyesine kadar sıvı kalabilir; bir yüzeye çarptığında anında donar.","Kitapta donan yağmur ve donan çiseleme mekanizmasını açıklayan kritik fiziksel evre olarak yer alır."],"tanim_en":"Water existing in liquid state below the normal freezing point without crystallization.","bag":{"kavram":["yagis-siddeti"],"soru":[],"hesap":[]}},{"id":"tropical-storm","tr":"tropikal fırtına (tropikal siklon)","en":"tropical storm (tropical cyclone)","kisa":"","tur":"kavram","es":["tropik kasırga","tropik siklon","tropical cyclone"],"tanim":["Sıcak tropikal denizler üzerinde oluşan, belirgin bir alçak basınç merkezine ve organize konveksiyon yapısına sahip sıcak çekirdekli siklonik fırtına.","Şiddetli rüzgâr ve yüksek birikimli yağış üreterek kıyı havzalarında sellere yol açar.","Kitapta ekstrem yağış ve taşkın oluşturan başlıca meteorolojik fırtına tipleri arasında geçer."],"tanim_en":"A warm-core non-frontal synoptic-scale cyclone originating over tropical waters with organized deep convection and cyclonic surface wind circulation.","bag":{"kavram":["yagis-siddeti"],"soru":[],"hesap":[]}},{"id":"snow-water-equivalent","tr":"Kar su eşdeğeri","en":"Snow water equivalent","kisa":"SWE","tur":"olcu","es":["su eşdeğeri","SWE","Su eşdeğeri","Water equivalent","kar örtüsü kalınlığı","kar kalınlığı"],"tanim":["Belirli bir alandaki kar örtüsünün tamamen erimesi durumunda sağlayacağı su tabakasının derinliği.","Birimi mm olup kar derinliği ile kar yoğunluğunun çarpılmasıyla ya da tartılı kar yastığı düzenekleriyle belirlenir.","Kitapta kar yağışının sıvı yağış eşdeğerine çevrilmesi ve su bütçesinde doğrudan P terimi olarak kullanılması için temel ölçüdür."],"tanim_en":"The depth of water that would theoretically result if the entire snowpack melted instantly.","bag":{"kavram":["yagis-siddeti"],"soru":[],"hesap":["yagis-siddeti","zarf"]}},{"id":"cloudburst","tr":"bulut patlaması (ani sağanak)","en":"cloudburst","kisa":"","tur":"surec","es":["aşırı sağanak","şiddetli sağanak","ani sağanak","torrential rain"],"tanim":["Çok kısa sürede olağanüstü yüksek şiddette düşen ve genellikle yerel konvektif fırtınalarla bağlantılı olan aşırı yağmur.","Kısa sürede onlarca milimetre su bırakarak toprak sızma kapasitesini hızla aşar ve ani yüzey taşkınlarına yol açar.","Kitapta sağanak türleri arasında en yüksek anlık yağış şiddetine ulaşan aşırı fırtına olayı olarak yer alır."],"tanim_en":"A rainstorm of extraordinary intensity and relatively short duration.","bag":{"kavram":["yagis-siddeti"],"soru":[],"hesap":[]}},{"id":"drizzle","tr":"çiseleme","en":"drizzle","kisa":"","tur":"surec","es":["light drizzle","çisenti","ince yağmur","Çisenti"],"tanim":["Birbirine çok yakın ve damla çapı 0,5 mm değerinden küçük ince su damlacıklarından oluşan tekdüze yağış.","Genellikle stratus bulutlarından düşer; tipik şiddeti 1 mm/h altında kalır ve havada asılı gibi yavaşça süzülür.","Kitapta damla boyutu sınırıyla (0,5 mm) yağmurdan ayrılan ve en düşük şiddetli sıvı yağış türü olarak yer alır."],"tanim_en":"Fairly uniform precipitation consisting of fine water droplets with diameters smaller than 0.5 mm.","bag":{"kavram":["yagis-siddeti"],"soru":["S9"],"hesap":[]}},{"id":"freezing-rain","tr":"Donan yağmur","en":"Freezing rain","kisa":"","tur":"surec","es":["glaze","buzlanma yağmuru","aşırı soğumuş yağmur","aşırı soğumuş çisenti","donan çiseleme","Donan çisenti"],"tanim":["Sıfır derecenin altındaki soğuk yer yüzeyine veya cisimlere çarptığında donarak şeffaf ve kaygan bir buz örtüsü (glaze) oluşturan aşırı soğumuş yağmur damlaları.","Damlalar yüksek seviyedeki sıcak katmanda eridikten sonra yere yakın sığ ve sıfırın altındaki soğuk hava katmanından geçerken aşırı soğur ve temas anında donar.","Kitapta havada donan buz tanelerinden (sleet) farklı olarak yerde donan ve ağır buz yükü oluşturan tehlikeli yağış olarak geçer."],"tanim_en":"Rain consisting of supercooled liquid droplets that freeze upon impact with cold ground or exposed objects.","bag":{"kavram":["yagis-siddeti"],"soru":["S9"],"hesap":[]}},{"id":"hail","tr":"Dolu","en":"Hail","kisa":"","tur":"surec","es":["hailstone","dolu tanesi","dolu taneleri"],"tanim":["Kümülonimbus bulutlarındaki güçlü yukarı hava hareketleriyle katmanlı şekilde büyüyen ve çapı en az 5 mm olan buz parçaları.","Çapı genellikle 5 ile 50 mm arasında değişir; hava radarında yansıtıcılığı 55 dBZ üzerine çıkararak sinyali aşırı şişirir.","Kitapta konvektif yağış türleri arasında ve radar Z-R bağıntısında aşırı yağış kestirimi hatasına yol açan başlıca bozan etken olarak geçer."],"tanim_en":"Precipitation of balls or irregular lumps of ice with diameters of 5 mm or larger falling from convective clouds.","bag":{"kavram":["yagis-siddeti","zr"],"soru":["S31"],"hesap":[]}},{"id":"shower","tr":"Sağanak","en":"Shower","kisa":"","tur":"surec","es":["sağanak yağış","convective shower","heavy shower"],"tanim":["Konvektif bulutlardan düşen, ani başlayıp ani biten ve şiddeti hızla değişen kısa süreli kuvvetli yağış.","Tipik yağış şiddeti 20 ile 100 mm/h aralığında olup doymamış zeminlerde sızma kapasitesini aşarak Horton türü akış üretir.","Kitapta çiselemeden yüksek şiddeti ve konvektif yapısıyla ayrılan temel yağış biçimidir."],"tanim_en":"A short-lived and heavy rainfall originating from convective clouds with rapid variations in intensity.","bag":{"kavram":["yagis-siddeti"],"soru":["S31"],"hesap":[]}},{"id":"sleet","tr":"buz tanesi (sleet)","en":"Sleet","kisa":"","tur":"surec","es":["ice pellets","sulu kar (İngiliz kullanımı)","buz tanecikleri","sulu kar","pellet"],"tanim":["Kitapta ve ABD kullanımında düşen yağmur damlalarının yere ulaşmadan önce soğuk hava tabakasında donmasıyla oluşan yarı saydam buz taneleri (ice pellets).","WMO terminolojisinde ve İngiliz kullanımında ise kar ile yağmurun karışımı ya da eriyen kar yağışını belirtir.","Kitapta donan yağmurdan farklı olarak sıvı damlanın yere çarpmadan önce havada donmasıyla ayrılan katı yağış türü olarak geçer."],"tanim_en":"Precipitation of transparent pellets of ice formed by the freezing of raindrops before reaching the ground, also denoting mixed rain and snow in British usage.","bag":{"kavram":["yagis-siddeti"],"soru":["S9"],"hesap":[]}},{"id":"squall","tr":"bora (squall)","en":"squall","kisa":"","tur":"surec","es":["kar boranı","fırtına hamlesi","squall line","ani fırtına"],"tanim":["Rüzgâr hızında ani ve sert bir artışla başlayan, en az birkaç dk süren ve genellikle şiddetli yağış ya da kar fırtınasıyla birlikte görülen hava olayı.","Kısa rüzgâr hamlesine göre daha uzun sürer; konvektif fırtına hatları boyunca yoğun kar veya şiddetli sağanak bantlarıyla ilerler.","Kitapta kar yağışının sert rüzgârla birleştiği dinamik hava durumları arasında yer alır."],"tanim_en":"A sudden and violent wind increase lasting for at least one minute before diminishing, frequently accompanied by heavy precipitation.","bag":{"kavram":["yagis-siddeti"],"soru":[],"hesap":[]}},{"id":"virga","tr":"Virga","en":"Virga","kisa":"","tur":"surec","es":["yere ulaşmayan yağış","virga below cloud base","yere ulaşmadan buharlaşan yağış","fallstreaks"],"tanim":["Bulut tabanından aşağıya sarkan ancak yeryüzüne ulaşamadan kuru hava katmanında buharlaşan düşey veya eğik yağış izleri.","Radarda yankı oluşturmasına karşın yer seviyesindeki yağışölçer kaplarına hiçbir sıvı derinliği girmez.","Kitapta yere ulaşmadığı için ölçülen yağış derinliğine (P) girmeyen buharlaşma kaybı olarak tanımlanır."],"tanim_en":"Vertical or inclined trails of precipitation attached to the undersurface of a cloud that evaporate before reaching the ground.","bag":{"kavram":["yagis-siddeti"],"soru":["S9"],"hesap":[]}},{"id":"record-point-rainfall","tr":"rekor nokta yağışı","en":"record point rainfall","kisa":"","tur":"kavram","es":["dünya rekor nokta yağışı","extreme observed rainfall","uç nokta yağışı"],"tanim":["Belirli tek bir istasyon veya noktada ölçülmüş olan doğrulanmış en yüksek yağış derinliği.","Kısa sürelerden (dk) aylara kadar uzanan gözlemler log–log eksende çizildiğinde dünya genelinde üst zarf sınırını oluşturur.","Kitapta dünya zarf eğrisinin türetilmesinde ve hidrolojik tasarımdaki en uç sınırların değerlendirilmesinde temel alınır."],"tanim_en":"The highest verified precipitation depth measured at an individual observation point for a specified duration.","bag":{"kavram":["zarf"],"soru":["S21"],"hesap":[]}},{"id":"unit-dbz","tr":"dBZ (desibel Z)","en":"dBZ (decibels of reflectivity)","kisa":"dBZ","tur":"birim","es":["radar yansıtırlık birimi","dBZ","radar desibel","radar desibeli","desibel Z"],"tanim":["Radar yansıtıcılık faktörü Z büyüklüğünün 1 mm⁶/m³ referansına göre logaritmik ölçekteki boyutsuz birimi.","Hafif yağmur için 20–30 dBZ, kuvvetli yağmur için 40–50 dBZ ve dolu için 55 dBZ üzeri tipik değerler alır.","Kitapta radar eko gücünü doğrudan yağış şiddetine dönüştüren logaritmik bağıntının temel değişkenidir."],"tanim_en":"A logarithmic dimensionless unit of radar reflectivity factor referenced to 1 mm⁶ m⁻³.","bag":{"kavram":["zr"],"soru":["S6"],"hesap":["radar-zr"]}},{"id":"unit-mm6-per-m3","tr":"milimetre üzeri altı bölü metreküp","en":"millimetres to the sixth power per cubic metre","kisa":"mm⁶/m³","tur":"birim","es":["mm6/m3","Z birimi","mm⁶/m³"],"tanim":["Birim hacimdeki yağmur damlalarının çaplarının altıncı kuvvetleri toplamı olan radar yansıtıcılık faktörü Z'nin doğrusal fiziksel birimi.","Rayleigh saçılması kabulü altında radar antenine geri dönen eko gücünün doğrudan orantılı olduğu temel büyüklüktür.","Kitapta Z–R bağıntılarında yağış şiddetiyle ilişkilendirilen doğrusal radar yansıtıcılığının birimidir."],"tanim_en":"The standard volumetric unit of radar reflectivity factor equal to the sum of sixth powers of raindrop diameters per unit volume.","bag":{"kavram":["zr"],"soru":[],"hesap":[]}},{"id":"nexrad","tr":"NEXRAD","en":"NEXRAD","kisa":"NEXRAD","tur":"cihaz","es":["Next-Generation Radar","WSR-88D","Yeni Nesil Radar"],"tanim":["Amerika Birleşik Devletleri genelinde konuşlu yüksek çözünürlüklü WSR-88D Doppler hava radarları ağı.","S bant (yaklaşık 10 cm dalga boyu) frekansında çalışarak yağış alanı ve şiddetini yüksek mekânsal çözünürlükle belirler.","Kitapta havza yağış ortalamalarının hassas kestirimi ve Z–R bağıntılarının uygulanmasında gelişmiş radar ağı örneğidir."],"tanim_en":"A network of high-resolution S-band Doppler weather radars providing precipitation data across the United States.","bag":{"kavram":["zr"],"soru":[],"hesap":[]}},{"id":"passive-microwave-sensor","tr":"Pasif mikrodalga algılayıcı","en":"Passive microwave sensor","kisa":"","tur":"cihaz","es":["uydu mikrodalga radyometresi","mikrodalga radyometresi","Pasif mikrodalga algılayıcısı","pasif mikrodalga algılayıcısı"],"tanim":["Yer yüzeyi ve atmosferden yayılan doğal mikrodalga ışınımını ölçerek yağış ve nem kestirimi yapan uydu radyometresi.","Kendi mikrodalga darbesini göndermez; ölçtüğü parlaklık sıcaklığı verileriyle bulut suyu, buz ve su buharını belirler.","Kitapta radarın bulunmadığı geniş okyanus ve havzalarda yağışa geçebilir su ve yağış tahmininde uydu kaynağı olarak yer alır."],"tanim_en":"A satellite radiometer that detects naturally emitted microwave radiation to estimate precipitation and atmospheric moisture.","bag":{"kavram":["zr","pw"],"soru":[],"hesap":[]}},{"id":"weather-radar","tr":"Hava radarı","en":"Weather radar","kisa":"","tur":"cihaz","es":["meteoroloji radarı","radar","yağış radarı","Doppler radar","ground-based weather radar","yer konuşlu radar"],"tanim":["Hidrometeorolojik olayları belirlemek, konumlandırmak ve niceliksel olarak ölçmek amacıyla yönlendirilmiş, tekrarlı ve zamanlanmış elektromanyetik ışınım kullanan sistem.","Yağış taneciklerinden geri saçılan mikrodalga sinyallerini yansıtıcılık faktörüne çevirerek anlık yağış şiddeti ve hareketini tespit eder.","Kitapta noktasal ölçerlerin aksine geniş bir alanda anlık yağış dağılımını ve şiddetini belirleyen temel uzaktan algılama aracıdır."],"tanim_en":"System in which beamed, repeated and timed electromagnetic radiation is used to detect, locate and quantify hydrometeorological phenomena.","bag":{"kavram":["zr"],"soru":["S6"],"hesap":[]}},{"id":"bright-band","tr":"Parlak bant","en":"Bright band","kisa":"","tur":"kavram","es":["melting layer","erime katmanı","erime seviyesi yankısı","bright band effect","parlak bant hatası","bright band error"],"tanim":["Erime seviyesi civarındaki bulut katmanında, erimenin ilk aşamasındaki buz kristalleri ve kar tanelerinin yüksek yansıtıcılığından kaynaklanan belirgin radar ekosu artışı.","Erimeye başlayan tanelerin yüzeyindeki sıvı su filmi, radara dev birer yağmur damlası gibi görünerek Z değerini yapay biçimde yükseltir.","Kitapta radarla yağış kestiriminde şiddetin gerçek değerinden çok daha yüksek tahmin edilmesine neden olan önemli bir hata kaynağıdır."],"tanim_en":"Characteristic enhanced radar echo, from the layer of a precipitating cloud in the vicinity of the melting level, due to the high reflection of radio energy by ice crystals and snowflakes in the initial stage of melting.","bag":{"kavram":["zr"],"soru":[],"hesap":[]}},{"id":"polarization","tr":"polarizasyon (çift polarizasyonlu radar)","en":"polarization (dual-polarization radar)","kisa":"","tur":"kavram","es":["kutuplanma","radar kutuplanması","kutuplanma nitelikleri","dual polarizasyon","Polarizasyon özellikleri","Polarization characteristics"],"tanim":["Radar anteninden yayılan elektromanyetik dalganın elektrik alan vektörünün yönelimi ve yatay ile düşey düzlemlerde eşzamanlı darbe iletimi özelliği.","Yatay ve düşey yansıtıcılık farkından hidrometeorların boyutu, basıklığı, yönelimi ve faz durumu belirlenir.","Kitapta yağmur damlaları ile dolu veya kar tanelerini ayırt ederek Z–R bağıntısındaki kestirim hatalarını azaltmada temel teknoloji olarak yer alır."],"tanim_en":"The orientation of the electric field vector in radar electromagnetic radiation, transmitting orthogonal wave signals to determine hydrometeor shape and phase.","bag":{"kavram":["zr"],"soru":[],"hesap":[]}},{"id":"tropical-rainfall-measuring-mission","tr":"Tropikal Yağış Ölçüm Görevi","en":"Tropical Rainfall Measuring Mission","kisa":"TRMM","tur":"kod","es":["TRMM uydusu","TRMM","Tropikal Yağış Ölçüm Misyonu"],"tanim":["Tropikal ve subtropikal bölgelerdeki yağış dağılımını uzaydan izlemek amacıyla yürütülen NASA ve JAXA ortak uydu görevi.","1997–2015 döneminde görev yapmış olup uzaydan yağış radarı ile yağışın üç boyutlu yapısını ilk kez doğrudan ölçmüştür.","Kitapta yer radarlarının yetersiz kaldığı okyanus ve geniş havzalarda uydu tabanlı yağış tahmini ve yağışa geçebilir su izlemesinde temel örnek olarak verilir."],"tanim_en":"A joint satellite mission conducted by NASA and JAXA from 1997 to 2015 to observe precipitation across tropical and subtropical regions.","bag":{"kavram":["zr","pw"],"soru":[],"hesap":[]}},{"id":"sym-drop-diameter","tr":"damla çapı","en":"drop diameter","kisa":"D","tur":"olcu","es":["D","yağmur damlası çapı"],"tanim":["Düşen bir hidrometeorun eşdeğer küresel geometrisini belirten doğrusal boyutu.","0,5 mm eşik değeriyle yağış türünü ayırır; damla çapı 0,5 mm altında kalan yağış çiseleme, 0,5 mm ve üzerinde olan yağış yağmur olarak tanımlanır.","Kitapta radar yansıtıcılık faktörü Z'nin damla çaplarının altıncı kuvveti toplamı olarak hesaplanmasında ve damla boyut dağılımında temel değişkendir."],"tanim_en":"The spherical equivalent linear dimension of a falling water drop used to differentiate drizzle from rain at the 0,5 mm threshold.","bag":{"kavram":["zr","marshall-palmer"],"soru":["S9"],"hesap":["radar-zr","marshall-palmer"]}},{"id":"sym-radar-reflectivity-factor","tr":"radar yansıtıcılık çarpanı","en":"radar reflectivity factor","kisa":"Z","tur":"olcu","es":["yansıtıcılık","reflectivity","eko şiddeti","radar yansıtıcılığı","Z"],"tanim":["Radar yansıtıcılık çarpanı Z: birim hacimdeki damlaların çaplarının altıncı kuvvetlerinin toplamı (Z = ΣD⁶); radarın gördüğü yankının büyüklüğünü verir.","Birimi mm⁶/m³'tür; değer aralığı çok geniş olduğundan logaritmik dBZ = 10·log₁₀ Z kullanılır.","Kitapta Z–R bağıntısıyla (Z = 200 R^1,6) yağış şiddetine çevrilir; altıncı kuvvet yüzünden birkaç iri damla ya da dolu Z'yi şişirir."],"tanim_en":"Radar reflectivity factor Z: the sum of the sixth powers of the drop diameters per unit volume (mm⁶ m⁻³), usually expressed in dBZ.","bag":{"kavram":["zr"],"soru":["S6"],"hesap":["radar-zr"]}},{"id":"sym-rain-rate-radar","tr":"yağış hızı (radar, RR)","en":"rain rate","kisa":"RR","tur":"olcu","es":["yağış şiddeti RR","anlık şiddet","yağış oranı","RR","rainfall rate"],"tanim":["Birim zamanda yeryüzüne düşen sıvı yağış miktarı ya da radar örnekleme hacminde hesaplanan anlık yağış akısı.","Birimi mm/h olup radar yansıtıcılık verilerinden ampirik Z–R bağıntıları kullanılarak dolaylı biçimde kestirilir.","Kitapta Marshall–Palmer damla boyut dağılımının eğim parametresini (Λ) belirlemede ve radar tabanlı yağış tahmininde yer alır."],"tanim_en":"Rain rate is the depth of water falling to the surface per unit time, estimated from weather radar reflectivity.","bag":{"kavram":["zr","marshall-palmer"],"soru":["S6","S7"],"hesap":["radar-zr","marshall-palmer"]}},{"id":"backscattering","tr":"Geri saçılma","en":"Backscattering","kisa":"","tur":"surec","es":["saçılma","backscatter","geri saçılım","radar geri saçılması"],"tanim":["Elektromanyetik dalgaların parçacıklarla etkileşimi sonucu geliş doğrultusuna ters yönde saçılması süreci.","Yağmur damlalarında geri saçılan güç miktarı Rayleigh yaklaşımı altında damla çapının altıncı kuvvetiyle orantılı olarak değişir.","Kitapta hava radarının yağış eko gücünü algılamasını ve bu yolla yansıtıcılık çarpanı ile yağış hızının hesaplanmasını açıklar."],"tanim_en":"Scattering of electromagnetic radiation back in the direction opposite to the incident wave upon interaction with particles.","bag":{"kavram":["zr"],"soru":[],"hesap":[]}},{"id":"rayleigh-scattering","tr":"Rayleigh saçılması","en":"Rayleigh scattering","kisa":"","tur":"surec","es":["Rayleigh saçılımı","Rayleigh saçılma rejimi"],"tanim":["Dalga boyundan çok daha küçük çaptaki küresel parçacıkların neden olduğu elektromanyetik saçılma süreci.","Saçılan enerji miktarı dalga boyunun dördüncü kuvvetiyle ters (λ⁻⁴), parçacık çapının altıncı kuvvetiyle (D⁶) doğru orantılıdır.","Kitapta radar yansıtıcılık çarpanı Z bağıntısında damla çapının neden altıncı kuvvetiyle toplandığının fiziksel temelini oluşturur."],"tanim_en":"Scattering of electromagnetic radiation by spherical particles whose diameters are much smaller than the incident wavelength.","bag":{"kavram":["zr"],"soru":[],"hesap":[]}},{"id":"weibull-plotting-position","tr":"Weibull çizim konumu","en":"Weibull plotting position","kisa":"","tur":"yontem","es":["çizim konumu","plotting position","Weibull formülü","m/(n+1)","deneysel aşılma olasılığı","empirical exceedance probability"],"tanim":["Büyükten küçüğe sıralanmış yıllık maksimum serisinde m. değerin aşılma olasılığını kestiren bağıntı: P = m/(n + 1); en büyük değer m = 1.","Dönüş aralığı T = 1/P = (n + 1)/m; seriden okunabilen en uzun aralık T = n + 1 (33 yıllık seride 34 yıl).","Payda n + 1 olduğu için en büyük değer P = 0, en küçük değer P = 1 almaz; m. değerin aşılma olasılığının beklenen değeridir."],"tanim_en":"Estimate of the exceedance probability of the m-th largest value in a ranked series of n annual maxima, P = m/(n + 1).","bag":{"kavram":["taskin-frekansi","gumbel"],"soru":[],"hesap":[]}},{"id":"independence","tr":"bağımsızlık (seri değerlerinin)","en":"independence (of series values)","kisa":"","tur":"kavram","es":["bağımsız seri","olay bağımsızlığı","independent events","serial independence"],"tanim":["Frekans serisindeki her değerin ayrı bir fırtınadan gelmesi; aynı olayın iki tepesi tek değer sayılır.","Hidrograf taban akışına dönmeden gelen ikinci tepe aynı olaydır; seriye yalnız büyüğü girer.","Risk bağıntısı yılları bağımsız sayar ve olasılıkları çarpar: (1 − 1/T)^N; kısmi süreler serisinde bu koşul ayrıca denetlenir."],"tanim_en":"Condition that each value in a frequency series comes from a separate storm event, so that two peaks of one event count as a single value.","bag":{"kavram":["taskin-frekansi","hidrograf","donus-risk"],"soru":[],"hesap":[]}},{"id":"flood-risk","tr":"taşkın riski (N yılda en az bir aşılma)","en":"hydrologic risk (risk of exceedance)","kisa":"","tur":"olcu","es":["hidrolojik risk","risk of exceedance","aşılma riski","tasarım riski","ömür boyu risk"],"tanim":["T yıllık taşkının N yıllık süre (yapı ömrü) içinde en az bir kez aşılma olasılığı: R = 1 − (1 − 1/T)^N.","Olasılıklar toplanmaz: 100 yıllık taşkın 30 yılda %26'dır (%30 değil); T = N iken risk hep %63 dolayındadır.","Tersi tasarımda kullanılır: kabul edilen risk R ve ömür N'den T = 1/[1 − (1 − R)^(1/N)] (25 yıl, %20 → yaklaşık 113 yıl)."],"tanim_en":"Probability that the T-year flood is exceeded at least once during an N-year period, R = 1 - (1 - 1/T)^N.","bag":{"kavram":["donus-risk","taskin-frekansi"],"soru":["S18"],"hesap":["risk"]}}]};
